_EASTERN_TZ = ZoneInfo("America/New_York")


def _count_trading_minutes(start_dt: datetime, end_dt: datetime) -> int:
    """Return the number of in-session minutes within ``[start_dt, end_dt)``."""

    try:
        start = _ensure_utc_dt(start_dt)
        end = _ensure_utc_dt(end_dt)
    except COMMON_EXC:
        return 0

    if end <= start:
        return 0

    total_minutes = 0
    current_date = start.astimezone(_EASTERN_TZ).date()
    final_date = end.astimezone(_EASTERN_TZ).date()

    while current_date <= final_date:
        try:
            if not market_calendar.is_trading_day(current_date):
                current_date += timedelta(days=1)
                continue
        except COMMON_EXC:
            current_date += timedelta(days=1)
            continue

        try:
            session = market_calendar.session_info(current_date)
        except COMMON_EXC:
            current_date += timedelta(days=1)
            continue

        session_start = _ensure_utc_dt(session.start_utc)
        session_end = _ensure_utc_dt(session.end_utc)
        if session_end <= session_start:
            current_date += timedelta(days=1)
            continue

        if session_end <= start or session_start >= end:
            current_date += timedelta(days=1)
            continue

        overlap_start = max(session_start, start)
        overlap_end = min(session_end, end)
        if overlap_end > overlap_start:
            try:
                minutes = int((overlap_end - overlap_start).total_seconds() // 60)
            except COMMON_EXC:
                minutes = 0
            if minutes > 0:
                total_minutes += minutes

        current_date += timedelta(days=1)

    return total_minutes


def _expected_minute_bars_window(start_dt: datetime, end_dt: datetime) -> int:
    """Return the naive minute count for the requested window."""

    try:
        delta = (end_dt - start_dt).total_seconds()
    except COMMON_EXC:
        return 0
    return max(0, int(delta // 60))


def _normalize_broker_order_status(value: Any) -> str:
    """Return a lowercase order status regardless of enum/string input."""

    if value is None:
        return ""
    status_value = getattr(value, "value", value)
    if isinstance(status_value, str):
        return status_value.lower()
    try:
        return str(status_value).lower()
    except COMMON_EXC:
        return ""


_FILLED_TCA_STATUSES: frozenset[str] = frozenset({"filled", "partially_filled"})


def _normalize_order_status_token(value: Any) -> str:
    """Return a normalized status token from enum-like or string values."""

    status_value = getattr(value, "value", value)
    if status_value in (None, ""):
        return ""
    try:
        token = str(status_value).strip().lower()
    except COMMON_EXC:
        return ""
    if not token:
        return ""
    token = token.replace("-", "_").replace(" ", "_")
    if "." in token:
        token = token.rsplit(".", 1)[-1]
    return token


def _extract_order_value(order: Any, *fields: str) -> Any:
    """Return first non-empty order value from execution result or nested payload."""

    nested_order = getattr(order, "order", None)
    candidates: list[Any] = [order]
    if nested_order is not None and nested_order is not order:
        candidates.append(nested_order)

    for candidate in candidates:
        if candidate is None:
            continue
        for field_name in fields:
            if isinstance(candidate, Mapping):
                value = candidate.get(field_name)
            else:
                value = getattr(candidate, field_name, None)
            if value not in (None, ""):
                return value
    return None


def _extract_order_fill_timestamp(order: Any) -> datetime | None:
    """Return best-effort fill timestamp from order payload."""

    for field_name in ("filled_at", "executed_at", "updated_at"):
        raw_value = _extract_order_value(order, field_name)
        if raw_value in (None, ""):
            continue
        if isinstance(raw_value, datetime):
            parsed = raw_value
            if parsed.tzinfo is None:
                parsed = parsed.replace(tzinfo=UTC)
            return parsed.astimezone(UTC)
        parsed = _parse_iso_timestamp(raw_value)
        if parsed is not None:
            return parsed
    return None


_QUOTE_SOURCE_EMPTY_TOKENS: frozenset[str] = frozenset(
    {"", "unknown", "none", "null", "n/a", "na"}
)


def _normalize_quote_source_token(value: Any) -> str | None:
    """Return normalized quote-source token or ``None`` when unavailable."""

    if value in (None, ""):
        return None
    try:
        token = str(value).strip().lower()
    except COMMON_EXC:
        return None
    if token in _QUOTE_SOURCE_EMPTY_TOKENS:
        return None
    return token


def _resolve_quote_proxy_source(
    order: Any,
    *,
    symbol: str,
    default_source: str,
) -> str:
    """Resolve TCA quote proxy source from order metadata with safe fallback."""

    for field_name in (
        "quote_proxy_source",
        "price_source",
        "quote_source",
        "fallback_source",
        "expected_price_source",
    ):
        token = _normalize_quote_source_token(_extract_order_value(order, field_name))
        if token is not None:
            return token

    for container_field in ("metadata", "annotations"):
        container = _extract_order_value(order, container_field)
        if not isinstance(container, MappingABC):
            continue
        for field_name in (
            "quote_proxy_source",
            "price_source",
            "quote_source",
            "fallback_source",
            "expected_price_source",
        ):
            token = _normalize_quote_source_token(container.get(field_name))
            if token is not None:
                return token

    price_source = _normalize_quote_source_token(get_price_source(symbol))
    if price_source is not None:
        return price_source

    default_token = _normalize_quote_source_token(default_source)
    return default_token or "last_trade"


def _resolve_order_quote_basis(
    ctx: Any,
    *,
    symbol: str,
    side: str,
    fallback_price: float | None = None,
) -> tuple[str, float | None, float | None, float | None, float | None, datetime | None]:
    """Return quote-source and NBBO basis for order submit/TCA attribution."""

    price_source = _normalize_quote_source_token(get_price_source(symbol))
    quote_source = price_source or "unknown"
    bid_at_arrival: float | None = None
    ask_at_arrival: float | None = None
    mid_at_arrival: float | None = None

    quote_obj = _fetch_quote(ctx, symbol)
    quote_ts = _quote_timestamp(quote_obj)
    mid_candidate, bid_candidate, ask_candidate = _quote_to_mid(quote_obj)
    if bid_candidate > 0:
        bid_at_arrival = float(bid_candidate)
    if ask_candidate > 0:
        ask_at_arrival = float(ask_candidate)
    if mid_candidate is not None and math.isfinite(float(mid_candidate)):
        mid_at_arrival = float(mid_candidate)
        quote_source = "broker_nbbo"

    arrival_price: float | None = None
    side_token = str(side or "").strip().lower()
    is_buy_side = side_token in {"buy", "cover"}
    if bid_at_arrival is not None and ask_at_arrival is not None:
        arrival_price = ask_at_arrival if is_buy_side else bid_at_arrival
    elif fallback_price is not None:
        try:
            fallback_value = float(fallback_price)
        except (TypeError, ValueError):
            fallback_value = 0.0
        if math.isfinite(fallback_value) and fallback_value > 0.0:
            arrival_price = fallback_value

    return (
        quote_source,
        bid_at_arrival,
        ask_at_arrival,
        mid_at_arrival,
        arrival_price,
        quote_ts,
    )


def _has_persistable_fill(
    *,
    status_token: str,
    filled_qty: float,
    fill_price: float | None,
) -> bool:
    """Return ``True`` when order metadata indicates a real fill."""

    if fill_price is None or filled_qty <= 0.0:
        return False
    if not status_token:
        return True
    return status_token in _FILLED_TCA_STATUSES


def _refresh_broker_order(
    api: Any,
    order: Any,
    *,
    log_on_failure: bool = False,
) -> tuple[Any, str, bool]:
    """Return a possibly refreshed order, status string, and confirmation flag."""

    status = _normalize_broker_order_status(getattr(order, "status", None))
    get_order = getattr(api, "get_order", None)
    if not callable(get_order):
        get_order = getattr(api, "get_order_by_id", None)
    order_id = getattr(order, "id", None) or getattr(order, "client_order_id", None)
    if not callable(get_order) or not order_id:
        return order, status, False
    try:
        refreshed = get_order(order_id)
    except COMMON_EXC as exc:  # pragma: no cover - network/API failure
        if log_on_failure:
            logger.debug(
                "PENDING_ORDER_REFRESH_FAILED",
                extra={
                    "order_id": str(order_id),
                    "cause": exc.__class__.__name__,
                    "detail": str(exc),
                },
                exc_info=True,
            )
        return order, status, False

    refreshed_status = _normalize_broker_order_status(
        getattr(refreshed, "status", None)
    )
    if not refreshed_status:
        refreshed_status = status
    return refreshed or order, refreshed_status, True


def get_confirmed_pending_orders(
    api: Any,
    orders: Iterable[Any] | None = None,
    *,
    require_confirmation: bool = True,
) -> list[Any]:
    """Return orders still pending after confirming with the broker."""

    if api is None:
        return []

    if orders is None:
        try:
            orders = list_open_orders(api)
        except COMMON_EXC as exc:  # pragma: no cover - defensive
            logger.debug(
                "PENDING_ORDER_LIST_FAILED",
                extra={
                    "cause": exc.__class__.__name__,
                    "detail": str(exc),
                },
                exc_info=True,
            )
            return []
    else:
        orders = list(orders)

    get_order = getattr(api, "get_order", None)
    if not callable(get_order):
        get_order = getattr(api, "get_order_by_id", None)
    if require_confirmation and not callable(get_order):
        logger.debug("PENDING_ORDER_CONFIRMATION_UNAVAILABLE")
        return []

    pending: list[Any] = []
    for order in orders:
        initial_status = _normalize_broker_order_status(getattr(order, "status", None))
        if initial_status not in _PENDING_ORDER_STATUSES:
            continue
        refreshed_order, refreshed_status, confirmed = _refresh_broker_order(
            api,
            order,
            log_on_failure=require_confirmation,
        )
        if require_confirmation and not confirmed:
            continue
        if refreshed_status in _PENDING_ORDER_STATUSES:
            pending.append(refreshed_order)
            continue
        logger.debug(
            "PENDING_ORDER_STATUS_CHANGED",
            extra={
                "order_id": str(
                    getattr(order, "id", None)
                    or getattr(order, "client_order_id", "")
                ),
                "initial_status": initial_status or "",
                "refreshed_status": refreshed_status or "",
            },
        )
    return pending


def _ensure_runtime_state(runtime: Any | None) -> dict[str, Any]:
    """Return a mutable runtime.state mapping, creating one if required."""

    if runtime is None:
        return {}
    state = getattr(runtime, "state", None)
    if not isinstance(state, dict):
        state = {}
        try:
            setattr(runtime, "state", state)
        except COMMON_EXC:  # pragma: no cover - defensive
            return cast(dict[str, Any], state)
    return cast(dict[str, Any], state)


def _get_pending_tracker(runtime: Any | None) -> dict[str, float | None]:
    """Return the pending-order tracker dictionary stored on the runtime."""

    state = _ensure_runtime_state(runtime)
    tracker = state.get(_PENDING_ORDER_TRACKER_KEY)
    if not isinstance(tracker, dict):
        tracker = {
            _PENDING_ORDER_FIRST_SEEN_KEY: None,
            _PENDING_ORDER_LAST_LOG_KEY: None,
            _PENDING_ORDER_WARMUP_REMAINING_KEY: 0.0,
        }
        state[_PENDING_ORDER_TRACKER_KEY] = tracker
    else:
        tracker.setdefault(_PENDING_ORDER_FIRST_SEEN_KEY, None)
        tracker.setdefault(_PENDING_ORDER_LAST_LOG_KEY, None)
        tracker.setdefault(_PENDING_ORDER_WARMUP_REMAINING_KEY, 0.0)
    return cast(dict[str, float | None], tracker)


