def _truthy_env(value: Any) -> bool:
    """Return ``True`` when ``value`` looks truthy ("1", "true", etc.)."""

    if value is None:
        return False
    if isinstance(value, bool):
        return value
    try:
        normalized = str(value).strip().lower()
    except COMMON_EXC:
        return False
    return normalized not in {"", "0", "false", "no"}


def _pytest_running() -> bool:
    """Return ``True`` when pytest execution is detected via managed config."""

    try:
        raw = get_env("PYTEST_RUNNING", None, resolve_aliases=False)
    except COMMON_EXC:
        raw = None

    env_provided = raw is not None
    if isinstance(raw, bool):
        env_truthy = raw
    elif raw is not None:
        try:
            env_truthy = _truthy_env(str(raw))
        except COMMON_EXC:
            env_truthy = False
    else:
        env_truthy = False

    if env_provided:
        return bool(env_truthy)

    if "pytest" in sys.modules:
        return True

    try:
        spec = importlib.util.find_spec("pytest")
    except COMMON_EXC:
        return False
    return bool(spec)


def _is_testing_env() -> bool:
    """Detect pytest/test harness execution via common environment markers."""

    if TESTING:
        return True
    for key in _TEST_ENV_VARS:
        raw = None
        try:
            raw = get_env(key, None)
        except COMMON_EXC:
            raw = get_env(key)
        if raw is not None and _truthy_env(str(raw)):
            return True
    return False

def _has_module(name: str) -> bool:
    try:
        spec = importlib.util.find_spec(name)
        return bool(spec) or (name in sys.modules)
    except ValueError:
        return name in sys.modules

