def _update_acceptance_rate_governor_state(
    state: BotState,
    *,
    decision_records_total: int,
    accepted_decisions: int,
) -> None:
    if not _acceptance_rate_governor_enabled():
        state.acceptance_rate_governor_active = False
        state.acceptance_rate_governor_streak = 0
        return

    total = max(0, int(decision_records_total))
    accepted = max(0, int(accepted_decisions))
    if total <= 0:
        return
    accepted = min(accepted, total)
    acceptance_rate = float(accepted) / float(total)

    min_records = _acceptance_rate_governor_min_records()
    if total < min_records:
        return

    min_rate = _acceptance_rate_governor_min_rate()
    low_acceptance = acceptance_rate < min_rate
    streak = int(getattr(state, "acceptance_rate_governor_streak", 0) or 0)
    if low_acceptance:
        streak = streak + 1 if streak > 0 else 1
    else:
        streak = streak - 1 if streak < 0 else -1
    state.acceptance_rate_governor_streak = streak

    active = bool(getattr(state, "acceptance_rate_governor_active", False))
    trigger_streak = _acceptance_rate_governor_trigger_streak()
    recover_streak = _acceptance_rate_governor_recover_streak()
    changed = False
    if not active and streak >= trigger_streak:
        active = True
        changed = True
    elif active and streak <= -recover_streak:
        active = False
        changed = True
    state.acceptance_rate_governor_active = active

    if changed:
        logger.warning(
            "ACCEPTANCE_RATE_GOVERNOR_STATE_CHANGED",
            extra={
                "active": bool(active),
                "streak": int(streak),
                "acceptance_rate": round(float(acceptance_rate), 6),
                "min_rate": round(float(min_rate), 6),
                "records_total": int(total),
                "accepted_records": int(accepted),
                "trigger_streak": int(trigger_streak),
                "recover_streak": int(recover_streak),
            },
        )


def _mean_std(values: Sequence[float]) -> tuple[float, float, int]:
    """Return mean/std/sample-count for finite numeric values."""

    clean = [
        float(value)
        for value in values
        if isinstance(value, (int, float)) and math.isfinite(float(value))
    ]
    count = int(len(clean))
    if count <= 0:
        return 0.0, 0.0, 0
    mean = float(sum(clean) / float(count))
    if count <= 1:
        return mean, 0.0, count
    variance = float(
        sum((float(value) - float(mean)) ** 2 for value in clean) / float(count)
    )
    return mean, math.sqrt(max(variance, 0.0)), count


def _percentile_linear(values: Sequence[float], q: float) -> float | None:
    """Return linearly interpolated percentile over finite values."""

    clean = sorted(
        float(value)
        for value in values
        if isinstance(value, (int, float)) and math.isfinite(float(value))
    )
    if not clean:
        return None
    quantile = max(0.0, min(float(q), 1.0))
    if len(clean) == 1:
        return float(clean[0])
    raw_index = quantile * float(len(clean) - 1)
    lower_index = int(math.floor(raw_index))
    upper_index = int(math.ceil(raw_index))
    if lower_index == upper_index:
        return float(clean[lower_index])
    lower = float(clean[lower_index])
    upper = float(clean[upper_index])
    frac = float(raw_index - lower_index)
    return float(lower + ((upper - lower) * frac))


def _infer_tca_liquidity_role(row: Mapping[str, Any]) -> str:
    raw_role = str(row.get("liquidity_role") or "").strip().lower()
    if raw_role in {"maker", "taker", "mixed"}:
        return raw_role
    order_type = str(row.get("order_type") or "").strip().lower()
    if order_type == "market":
        return "taker"
    spread_paid_bps = _safe_float(row.get("spread_paid_bps"))
    if spread_paid_bps is not None:
        if float(spread_paid_bps) <= 0.05:
            return "maker"
        if float(spread_paid_bps) >= 0.75:
            return "taker"
    if order_type in {"limit", "stop_limit"}:
        return "maker"
    return "mixed"


def _extract_tca_fill_success_ratio(row: Mapping[str, Any]) -> float | None:
    if bool(row.get("pending_event")):
        return None
    status = str(row.get("status") or row.get("order_status") or "").strip().lower()
    if not status:
        return None
    if status in {
        "rejected",
        "canceled",
        "cancelled",
        "expired",
        "done_for_day",
        "no_fill",
        "failed",
    }:
        return 0.0
    if status not in {"filled", "partially_filled", "matched_fill_compacted"}:
        return None
    resolved_qty = _safe_float(row.get("resolved_fill_qty"))
    if resolved_qty is None:
        resolved_qty = _safe_float(row.get("qty"))
    requested_qty = _safe_float(row.get("requested_qty"))
    if requested_qty is None:
        requested_qty = _safe_float(row.get("original_qty"))
    if requested_qty is not None and float(requested_qty) > 0.0 and resolved_qty is not None:
        ratio = float(resolved_qty) / float(requested_qty)
        return max(0.0, min(1.0, ratio))
    partial = bool(row.get("partial_fill"))
    if partial:
        return 0.5
    return 1.0


def _sequential_significance_gate(
    *,
    mean_reward_bps: float,
    std_reward_bps: float,
    samples: int,
    min_samples: int,
    target_mean_bps: float,
    method: str,
    posterior_prob_min: float,
    sprt_alpha: float,
    sprt_beta: float,
    sprt_effect_bps: float,
) -> dict[str, Any]:
    """Evaluate sequential evidence that reward exceeds target."""

    sample_count = max(0, int(samples))
    min_required = max(1, int(min_samples))
    if sample_count < min_required:
        return {
            "passed": False,
            "reason": "insufficient_samples",
            "samples": sample_count,
            "min_samples": min_required,
            "mean_reward_bps": float(mean_reward_bps),
            "std_reward_bps": float(std_reward_bps),
            "target_mean_bps": float(target_mean_bps),
            "method": str(method),
        }
    sigma = max(float(std_reward_bps), 1e-6)
    stderr = sigma / math.sqrt(float(max(sample_count, 1)))
    delta = float(mean_reward_bps) - float(target_mean_bps)
    z_score = float(delta / max(stderr, 1e-9))
    posterior_prob = float(1.0 - NormalDist().cdf((0.0 - delta) / max(stderr, 1e-9)))
    posterior_prob_min = max(0.5, min(float(posterior_prob_min), 0.999999))
    bayesian_pass = bool(posterior_prob >= posterior_prob_min)

    sprt_alpha = max(1e-6, min(float(sprt_alpha), 0.5))
    sprt_beta = max(1e-6, min(float(sprt_beta), 0.5))
    effect = max(float(sprt_effect_bps), 1e-6)
    sigma_for_sprt = max(sigma, effect, 1e-6)
    llr = float(
        (
            float(sample_count)
            * ((float(delta) * float(effect)) - (0.5 * (float(effect) ** 2)))
        )
        / (float(sigma_for_sprt) ** 2)
    )
    llr_accept = float(math.log((1.0 - sprt_beta) / sprt_alpha))
    llr_reject = float(math.log(sprt_beta / (1.0 - sprt_alpha)))
    sprt_state = "continue"
    if llr >= llr_accept:
        sprt_state = "accept"
    elif llr <= llr_reject:
        sprt_state = "reject"
    sprt_pass = sprt_state == "accept"

    mode = str(method or "bayesian").strip().lower()
    if mode not in {"bayesian", "sprt", "either", "both"}:
        mode = "bayesian"
    if mode == "sprt":
        passed = sprt_pass
    elif mode == "either":
        passed = bool(bayesian_pass or sprt_pass)
    elif mode == "both":
        passed = bool(bayesian_pass and sprt_pass)
    else:
        passed = bayesian_pass

    return {
        "passed": bool(passed),
        "reason": "ok" if passed else "sequential_significance_not_met",
        "samples": sample_count,
        "min_samples": min_required,
        "mean_reward_bps": float(mean_reward_bps),
        "std_reward_bps": float(std_reward_bps),
        "target_mean_bps": float(target_mean_bps),
        "stderr_bps": float(stderr),
        "z_score": float(z_score),
        "method": mode,
        "bayesian_pass": bool(bayesian_pass),
        "posterior_prob_gt_target": float(posterior_prob),
        "posterior_prob_min": float(posterior_prob_min),
        "sprt_pass": bool(sprt_pass),
        "sprt_state": str(sprt_state),
        "sprt_llr": float(llr),
        "sprt_llr_accept": float(llr_accept),
        "sprt_llr_reject": float(llr_reject),
        "sprt_effect_bps": float(effect),
    }


def _portfolio_optimizer_decision_token(decision: Any) -> str:
    """Normalize optimizer decision enum/value to a lowercase token."""

    raw_value = getattr(decision, "value", decision)
    token = str(raw_value or "").strip().lower()
    return token or "unknown"


def _build_symbol_return_correlation_matrix(
    symbol_returns: Mapping[str, Sequence[float]],
) -> dict[str, dict[str, float]]:
    """Build a finite pairwise correlation matrix from per-symbol return windows."""

    symbols = [
        str(symbol).strip().upper()
        for symbol, values in symbol_returns.items()
        if str(symbol).strip() and isinstance(values, Sequence)
    ]
    matrix: dict[str, dict[str, float]] = {symbol: {} for symbol in symbols}
    for left_symbol in symbols:
        left_values_raw = symbol_returns.get(left_symbol, ())
        left_values = [
            float(value)
            for value in left_values_raw
            if isinstance(value, (int, float)) and math.isfinite(float(value))
        ]
        for right_symbol in symbols:
            right_values_raw = symbol_returns.get(right_symbol, ())
            right_values = [
                float(value)
                for value in right_values_raw
                if isinstance(value, (int, float)) and math.isfinite(float(value))
            ]
            if left_symbol == right_symbol:
                matrix[left_symbol][right_symbol] = 1.0
                continue
            overlap = min(len(left_values), len(right_values))
            if overlap < 2:
                matrix[left_symbol][right_symbol] = 0.0
                continue
            left_window = np.asarray(left_values[-overlap:], dtype=float)
            right_window = np.asarray(right_values[-overlap:], dtype=float)
            if (
                left_window.size < 2
                or right_window.size < 2
                or np.std(left_window) <= 0.0
                or np.std(right_window) <= 0.0
            ):
                matrix[left_symbol][right_symbol] = 0.0
                continue
            corr_val = float(np.corrcoef(left_window, right_window)[0, 1])
            if not math.isfinite(corr_val):
                corr_val = 0.0
            matrix[left_symbol][right_symbol] = max(-1.0, min(1.0, corr_val))
    return matrix


# No ML model serves runtime decisions: proposals come from the non-model rule
# scorer (``_score_from_bars``). Orders, decision records and TCA rows name it,
# so openings still carry the model_id/model_version the submit-context check
# requires. Rows written before this carried the legacy artifact's file name
# and ``mtime_ns:size`` signature instead.
RULE_SCORER_MODEL_ID = "rule_scorer"
RULE_SCORER_MODEL_VERSION = "score_from_bars"


def _execution_model_lineage() -> dict[str, str]:
    """Return model lineage fields for execution telemetry."""

    model_id = str(get_env("AI_TRADING_MODEL_ID", "", cast=str) or "").strip()
    model_version = str(get_env("AI_TRADING_MODEL_VERSION", "", cast=str) or "").strip()
    dataset_hash = str(get_env("AI_TRADING_DATASET_HASH", "", cast=str) or "").strip()
    feature_version = str(get_env("AI_TRADING_FEATURE_VERSION", "", cast=str) or "").strip()
    model_artifact_hash = str(
        get_env("AI_TRADING_MODEL_ARTIFACT_HASH", "", cast=str) or ""
    ).strip()

    resolved: dict[str, str] = {
        "model_id": model_id or RULE_SCORER_MODEL_ID,
        "model_version": model_version or RULE_SCORER_MODEL_VERSION,
    }
    if dataset_hash:
        resolved["dataset_hash"] = str(dataset_hash)
    if feature_version:
        resolved["feature_version"] = str(feature_version)
    if model_artifact_hash:
        resolved["model_artifact_hash"] = str(model_artifact_hash)
    return resolved


def _portfolio_optimizer_allows_trade(
    *,
    optimizer: Any | None,
    symbol: str,
    proposed_position: float,
    current_positions: Mapping[str, float],
    market_data: Mapping[str, Any],
) -> tuple[bool, dict[str, Any]]:
    """Return allow/block decision from portfolio optimizer."""

    if optimizer is None:
        return True, {"enabled": False, "reason": "optimizer_unavailable"}
    try:
        decision_raw, reason_raw = optimizer.make_portfolio_decision(
            symbol=symbol,
            proposed_position=float(proposed_position),
            current_positions=dict(current_positions),
            market_data=dict(market_data),
        )
    except BOT_ENGINE_FALLBACK_EXC as exc:
        return True, {
            "enabled": True,
            "reason": "decision_error_fail_open",
            "error_type": exc.__class__.__name__,
            "error": str(exc),
            "symbol": str(symbol).upper(),
        }
    decision_token = _portfolio_optimizer_decision_token(decision_raw)
    allowed = decision_token == "approve"
    return bool(allowed), {
        "enabled": True,
        "decision": decision_token,
        "reason": str(reason_raw or ""),
        "symbol": str(symbol).upper(),
        "proposed_position": float(proposed_position),
    }


def _record_prerank_shadow_snapshot(
    *,
    ranked_symbols: Sequence[str],
    selected_symbols: Sequence[str],
    rank_source: str,
    top_n: int | None,
    runtime: Any | None,
) -> None:
    """Emit a lightweight shadow snapshot from the active prerank path.

    Recording here guarantees shadow artifacts reflect the real execution flow.
    """

    def _flag(name: str, default: bool) -> bool:
        try:
            value = get_env(name, default, cast=bool)
        except TypeError:
            value = get_env(name, default)
        except BOT_ENGINE_FALLBACK_EXC:
            return bool(default)
        if isinstance(value, str):
            return value.strip().lower() in {"1", "true", "yes", "on"}
        return bool(value)

    if not _flag("AI_TRADING_ML_SHADOW_ENABLED", False):
        return
    if not _flag("AI_TRADING_ML_SHADOW_PRERANK_ENABLED", True):
        return

    runtime_rank: Mapping[str, Any] | None = None
    if runtime is not None:
        rank_candidate = getattr(runtime, "execution_candidate_rank", None)
        if isinstance(rank_candidate, Mapping):
            runtime_rank = rank_candidate

    ranked_payload: list[dict[str, Any]] = []
    for symbol in list(selected_symbols)[:20]:
        rank_score: float | None = None
        if runtime_rank:
            raw_score = runtime_rank.get(symbol, runtime_rank.get(symbol.lower(), 0.0))
            try:
                numeric_score = float(raw_score)
            except (TypeError, ValueError):
                numeric_score = 0.0
            if math.isfinite(numeric_score):
                rank_score = numeric_score
        ranked_payload.append(
            {
                "symbol": symbol,
                "rank_score": rank_score,
            }
        )

    payload = {
        "ts": datetime.now(UTC).isoformat(),
        "mode": "execution_candidate_prerank",
        "rank_source": str(rank_source),
        "requested": int(len(ranked_symbols)),
        "selected": int(len(selected_symbols)),
        "top_n": int(top_n) if top_n is not None else None,
        "ranked": ranked_payload,
        "provider": _ml_shadow_provider_snapshot(),
        "quote_status": _ml_shadow_quote_snapshot(),
        "session_regime": _session_bucket_from_ts(datetime.now(UTC)),
        "regime_profile": get_regime_signal_profile(),
        "market_regime": RECORDED_MARKET_REGIME_LABEL,
    }
    _record_shadow_prediction(payload)


def _symbol_tokens_from_env(name: str) -> set[str]:
    try:
        raw = str(get_env(name, "", cast=str) or "")
    except BOT_ENGINE_FALLBACK_EXC:
        raw = ""
    return {
        token.strip().upper()
        for token in raw.split(",")
        if token and token.strip()
    }


def _resolve_replay_symbols() -> tuple[set[str], str]:
    explicit = _symbol_tokens_from_env("AI_TRADING_REPLAY_SYMBOLS")
    if explicit:
        return explicit, "AI_TRADING_REPLAY_SYMBOLS"
    canary = _symbol_tokens_from_env("AI_TRADING_CANARY_SYMBOLS")
    if canary:
        paper_allowed = _symbol_tokens_from_env("AI_TRADING_PAPER_SAMPLING_ALLOWED_SYMBOLS")
        if paper_allowed:
            executable_canary = canary.intersection(paper_allowed)
            if executable_canary:
                return (
                    executable_canary,
                    "AI_TRADING_CANARY_SYMBOLS_INTERSECT_AI_TRADING_PAPER_SAMPLING_ALLOWED_SYMBOLS",
                )
        return canary, "AI_TRADING_CANARY_SYMBOLS"
    runtime_universe = _symbol_tokens_from_env("AI_TRADING_SYMBOLS")
    if runtime_universe:
        return runtime_universe, "AI_TRADING_SYMBOLS"
    try:
        use_tickers_file = bool(
            get_env("AI_TRADING_REPLAY_FALLBACK_TO_TICKERS_FILE", True, cast=bool)
        )
    except BOT_ENGINE_FALLBACK_EXC:
        use_tickers_file = True
    if use_tickers_file:
        try:
            symbols = {
                str(symbol).strip().upper()
                for symbol in load_tickers(TICKERS_FILE)
                if str(symbol).strip()
            }
        except BOT_ENGINE_FALLBACK_EXC:
            symbols = set()
        return symbols, "tickers_file"
    return set(), "none"


def _record_symbol_starvation_alert(
    *,
    ranked_symbols: Sequence[str],
    selected_symbols: Sequence[str],
    runtime: Any | None,
    prerank_cycle: int,
) -> None:
    if runtime is None or not selected_symbols:
        return
    try:
        enabled = bool(
            get_env("AI_TRADING_SYMBOL_STARVATION_ALERT_ENABLED", True, cast=bool)
        )
    except BOT_ENGINE_FALLBACK_EXC:
        enabled = True
    if not enabled:
        return
    configured_symbols = {
        str(symbol).strip().upper()
        for symbol in ranked_symbols
        if str(symbol).strip()
    }
    configured_symbols.update(_symbol_tokens_from_env("AI_TRADING_CANARY_SYMBOLS"))
    configured_symbols.update(_symbol_tokens_from_env("AI_TRADING_ML_SHADOW_EXTRA_SYMBOLS"))
    if len(configured_symbols) < 2:
        return
    try:
        window_size = int(
            get_env("AI_TRADING_SYMBOL_STARVATION_WINDOW", 100, cast=int)
        )
    except BOT_ENGINE_FALLBACK_EXC:
        window_size = 100
    window_size = max(10, min(window_size, 1000))
    try:
        min_samples = int(
            get_env("AI_TRADING_SYMBOL_STARVATION_MIN_SAMPLES", 20, cast=int)
        )
    except BOT_ENGINE_FALLBACK_EXC:
        min_samples = 20
    min_samples = max(5, min(min_samples, window_size))
    try:
        threshold = float(
            get_env("AI_TRADING_SYMBOL_STARVATION_DOMINANCE_RATIO", 0.95, cast=float)
        )
    except BOT_ENGINE_FALLBACK_EXC:
        threshold = 0.95
    threshold = max(0.5, min(threshold, 1.0))
    raw_window = getattr(runtime, "_execution_symbol_selection_window", None)
    if not isinstance(raw_window, deque):
        raw_window = deque(maxlen=window_size)
    elif raw_window.maxlen != window_size:
        raw_window = deque(raw_window, maxlen=window_size)
    for raw_symbol in selected_symbols:
        symbol = str(raw_symbol).strip().upper()
        if symbol:
            raw_window.append(symbol)
    try:
        setattr(runtime, "_execution_symbol_selection_window", raw_window)
    except BOT_ENGINE_FALLBACK_EXC:
        return
    total = len(raw_window)
    if total < min_samples:
        return
    counts = Counter(raw_window)
    dominant_symbol, dominant_count = counts.most_common(1)[0]
    dominant_ratio = float(dominant_count / total) if total else 0.0
    if dominant_ratio < threshold:
        return
    try:
        cooldown_cycles = int(
            get_env("AI_TRADING_SYMBOL_STARVATION_ALERT_COOLDOWN_CYCLES", 10, cast=int)
        )
    except BOT_ENGINE_FALLBACK_EXC:
        cooldown_cycles = 10
    cooldown_cycles = max(1, min(cooldown_cycles, 1000))
    last_alert_cycle = getattr(runtime, "_execution_symbol_starvation_last_alert_cycle", 0)
    try:
        last_alert_cycle_int = int(last_alert_cycle)
    except (TypeError, ValueError):
        last_alert_cycle_int = 0
    if int(prerank_cycle) - last_alert_cycle_int < cooldown_cycles:
        return
    try:
        setattr(
            runtime,
            "_execution_symbol_starvation_last_alert_cycle",
            int(prerank_cycle),
        )
    except BOT_ENGINE_FALLBACK_EXC:
        pass
    logger.warning(
        "SYMBOL_STARVATION_ALERT",
        extra={
            "dominant_symbol": dominant_symbol,
            "dominant_ratio": dominant_ratio,
            "dominant_count": int(dominant_count),
            "window_samples": int(total),
            "configured_symbols": sorted(configured_symbols),
            "ranked_symbols": [
                str(symbol).strip().upper()
                for symbol in ranked_symbols
                if str(symbol).strip()
            ][:20],
            "selected_symbols": [
                str(symbol).strip().upper()
                for symbol in selected_symbols
                if str(symbol).strip()
            ][:20],
            "reason": "candidate_selection_collapsed_to_one_symbol",
        },
    )


def _prefetch_ml_shadow_quote(runtime: Any | None, symbol: str) -> None:
    """Refresh the global and per-symbol quote status from the latest quote."""

    normalized_symbol = str(symbol or "").strip().upper()
    if not normalized_symbol:
        return
    try:
        enabled = bool(
            get_env("AI_TRADING_ML_SHADOW_QUOTE_PREFETCH_ENABLED", True, cast=bool)
        )
    except BOT_ENGINE_FALLBACK_EXC:
        enabled = True
    if not enabled:
        return
    try:
        quote = _fetch_quote(runtime, normalized_symbol)
        bid, ask = _extract_quote_bid_ask(quote)
        if bid is None and ask is None:
            return
        quote_age_sec = _quote_age_seconds(quote)
        quote_age_ms: float | None = None
        if math.isfinite(quote_age_sec):
            quote_age_ms = quote_age_sec * 1000.0
        quote_ts = _extract_quote_timestamp(quote)
        runtime_state.update_quote_status(
            allowed=bid is not None and ask is not None,
            symbol=normalized_symbol,
            status="ready" if bid is not None and ask is not None else "partial",
            source="latest_quote",
            synthetic=False,
            bid=bid,
            ask=ask,
            age_sec=quote_age_sec if math.isfinite(quote_age_sec) else None,
            quote_age_ms=quote_age_ms,
            quote_timestamp=quote_ts.isoformat() if quote_ts is not None else None,
        )
    except BOT_ENGINE_FALLBACK_EXC as exc:
        logger.debug(
            "ML_SHADOW_QUOTE_PREFETCH_FAILED",
            extra={"symbol": normalized_symbol, "error": str(exc)},
        )


def _refresh_prerank_quote_status(
    *,
    selected_symbols: Sequence[str],
    runtime: Any | None,
) -> None:
    """Refresh the global quote status for the selected prerank symbols.

    This ran inside the legacy model's shadow scoring until that scoring was
    removed. The primary-feed de-risk gate later in the same cycle reads the
    status it leaves, so the same flags, limit, symbols and order are kept: up
    to the limit of selected symbols plus ``AI_TRADING_ML_SHADOW_EXTRA_SYMBOLS``,
    each refreshed only when minute (or daily) bars are available for it.
    """

    if runtime is None:
        return
    try:
        shadow_enabled = bool(get_env("AI_TRADING_ML_SHADOW_ENABLED", False, cast=bool))
    except BOT_ENGINE_FALLBACK_EXC:
        shadow_enabled = False
    if not shadow_enabled:
        return
    try:
        enabled = bool(
            get_env("AI_TRADING_ML_SHADOW_PRERANK_SIGNAL_ENABLED", True, cast=bool)
        )
    except BOT_ENGINE_FALLBACK_EXC:
        enabled = True
    if not enabled:
        return
    fetcher = getattr(runtime, "data_fetcher", None)
    daily_getter = getattr(fetcher, "get_daily_df", None) if fetcher is not None else None
    try:
        limit = int(get_env("AI_TRADING_ML_SHADOW_PRERANK_SIGNAL_LIMIT", 10, cast=int))
    except BOT_ENGINE_FALLBACK_EXC:
        limit = 10
    limit = max(1, min(limit, 50))
    raw_extra_symbols = str(get_env("AI_TRADING_ML_SHADOW_EXTRA_SYMBOLS", "", cast=str) or "")
    extra_symbols = [
        token.strip().upper()
        for token in raw_extra_symbols.split(",")
        if token and token.strip()
    ]
    symbols_to_refresh: list[str] = []
    seen_symbols: set[str] = set()
    for raw_symbol in list(selected_symbols)[:limit] + extra_symbols:
        symbol = str(raw_symbol).strip().upper()
        if not symbol or symbol in seen_symbols:
            continue
        seen_symbols.add(symbol)
        symbols_to_refresh.append(symbol)
        if len(symbols_to_refresh) >= 50:
            break

    for symbol in symbols_to_refresh:
        frame: pd.DataFrame | None = None
        try:
            frame = fetch_minute_df_safe(symbol)
        except BOT_ENGINE_FALLBACK_EXC as exc:
            logger.debug(
                "PRERANK_QUOTE_REFRESH_MINUTE_UNAVAILABLE",
                extra={"symbol": symbol, "error": str(exc)},
            )
            frame = None
        if (frame is None or getattr(frame, "empty", True)) and callable(daily_getter):
            try:
                try:
                    frame = daily_getter(runtime, symbol)
                except TypeError:
                    frame = daily_getter(symbol)
            except BOT_ENGINE_FALLBACK_EXC as exc:
                logger.debug(
                    "PRERANK_QUOTE_REFRESH_DAILY_UNAVAILABLE",
                    extra={"symbol": symbol, "error": str(exc)},
                )
                frame = None
        if frame is None or getattr(frame, "empty", True):
            continue
        _prefetch_ml_shadow_quote(runtime, symbol)


def _pre_rank_execution_candidates(
    symbols: Sequence[str],
    *,
    runtime: Any | None,
) -> list[str]:
    """Pre-rank symbols before broker calls and optionally truncate to top-N."""
    from ai_trading.core.execution_runtime_metadata import (
        load_execution_prerank_runtime_state,
        store_execution_prerank_runtime_state,
    )

    normalized = [str(sym).strip().upper() for sym in symbols if str(sym).strip()]
    if not normalized:
        return []
    deduped: list[str] = []
    seen_symbols: set[str] = set()
    for symbol in normalized:
        if symbol in seen_symbols:
            continue
        seen_symbols.add(symbol)
        deduped.append(symbol)

    top_n = _resolve_execution_candidate_top_n()
    top_n_source = "configured"
    adaptive_submit_cap: int | None = None
    adaptive_submit_cap_source = "none"
    adaptive_top_n_cap: int | None = None
    try:
        adaptive_top_n_enabled = bool(
            get_env("AI_TRADING_EXEC_CANDIDATE_TOP_N_ADAPTIVE_ENABLED", True, cast=bool)
        )
    except BOT_ENGINE_FALLBACK_EXC:
        adaptive_top_n_enabled = True
    if adaptive_top_n_enabled and runtime is not None:
        exec_engine = getattr(runtime, "execution_engine", None)
        resolve_submit_cap = getattr(exec_engine, "_resolve_order_submit_cap", None)
        if callable(resolve_submit_cap):
            try:
                cap_value, cap_source = resolve_submit_cap()
            except BOT_ENGINE_FALLBACK_EXC:
                cap_value, cap_source = (None, "error")
            if cap_value is not None:
                try:
                    adaptive_submit_cap = max(1, int(cap_value))
                except (TypeError, ValueError):
                    adaptive_submit_cap = None
            adaptive_submit_cap_source = str(cap_source or "none")
    if adaptive_submit_cap is not None:
        try:
            per_order = int(
                get_env("AI_TRADING_EXEC_CANDIDATE_TOP_N_PER_ORDER_CAP", 4, cast=int)
            )
        except BOT_ENGINE_FALLBACK_EXC:
            per_order = 4
        try:
            adaptive_min = int(
                get_env("AI_TRADING_EXEC_CANDIDATE_TOP_N_ADAPTIVE_MIN", 6, cast=int)
            )
        except BOT_ENGINE_FALLBACK_EXC:
            adaptive_min = 6
        per_order = max(1, min(per_order, 25))
        adaptive_min = max(1, min(adaptive_min, 500))
        adaptive_top_n_cap = max(adaptive_min, min(adaptive_submit_cap * per_order, 500))
        if top_n is None:
            top_n = adaptive_top_n_cap
            top_n_source = "adaptive_submit_cap_default"
        else:
            adjusted_top_n = min(top_n, adaptive_top_n_cap)
            if adjusted_top_n != top_n:
                top_n = adjusted_top_n
                top_n_source = "adaptive_submit_cap_clamp"

    weights: Mapping[str, Any] | None = None
    runtime_rank: Mapping[str, Any] | None = None
    opportunity_quality: Mapping[str, Any] | None = None
    try:
        quality_filter_enabled = bool(
            get_env("AI_TRADING_EXEC_OPPORTUNITY_QUALITY_ENABLED", True, cast=bool)
        )
    except TypeError:
        quality_filter_enabled = bool(
            get_env("AI_TRADING_EXEC_OPPORTUNITY_QUALITY_ENABLED", True)
        )
    except BOT_ENGINE_FALLBACK_EXC:
        quality_filter_enabled = True
    try:
        quality_top_quantile = float(
            get_env("AI_TRADING_EXEC_OPPORTUNITY_TOP_QUANTILE", 0.93, cast=float)
        )
    except TypeError:
        quality_top_quantile = float(
            get_env("AI_TRADING_EXEC_OPPORTUNITY_TOP_QUANTILE", 0.93)
        )
    except BOT_ENGINE_FALLBACK_EXC:
        quality_top_quantile = 0.93
    quality_top_quantile = max(0.05, min(quality_top_quantile, 0.99))
    try:
        quality_min_keep = int(
            get_env("AI_TRADING_EXEC_OPPORTUNITY_MIN_KEEP", 6, cast=int)
        )
    except TypeError:
        quality_min_keep = int(get_env("AI_TRADING_EXEC_OPPORTUNITY_MIN_KEEP", 6))
    except BOT_ENGINE_FALLBACK_EXC:
        quality_min_keep = 6
    quality_min_keep = max(1, quality_min_keep)
    quality_threshold: float | None = None
    quality_allowed_symbols: set[str] = set()
    prerank_cycle = 0
    last_selected_cycles: dict[str, int] = {}
    if runtime is not None:
        prerank_runtime_state = load_execution_prerank_runtime_state(runtime)
        weights = prerank_runtime_state.weights or None
        runtime_rank = prerank_runtime_state.runtime_rank or None
        opportunity_quality = prerank_runtime_state.opportunity_quality or None
        prerank_cycle = int(prerank_runtime_state.prerank_cycle)
        last_selected_cycles = dict(prerank_runtime_state.last_selected_cycles)

    if quality_filter_enabled and opportunity_quality and len(deduped) > quality_min_keep:
        quality_pairs = []
        for symbol in deduped:
            score = _safe_float(opportunity_quality.get(symbol))
            if score is None:
                score = _safe_float(opportunity_quality.get(symbol.lower()))
            if score is None:
                continue
            quality_pairs.append((symbol, float(max(0.0, min(score, 1.0)))))
        if len(quality_pairs) >= quality_min_keep:
            threshold = _percentile_linear(
                [score for _symbol, score in quality_pairs],
                quality_top_quantile,
            )
            if threshold is not None:
                quality_threshold = float(threshold)
                quality_pairs.sort(key=lambda item: (-item[1], item[0]))
                quality_allowed_symbols = {
                    symbol
                    for symbol, score in quality_pairs
                    if float(score) >= float(quality_threshold)
                }
                if len(quality_allowed_symbols) < int(quality_min_keep):
                    for symbol, _score in quality_pairs[:quality_min_keep]:
                        quality_allowed_symbols.add(str(symbol))
                filtered = [symbol for symbol in deduped if symbol in quality_allowed_symbols]
                if filtered:
                    deduped = filtered

    def _weight(sym: str) -> float:
        if not weights:
            return 0.0
        raw_weight = weights.get(sym, weights.get(sym.lower(), 0.0))  # type: ignore[union-attr]
        try:
            return abs(float(raw_weight))
        except (TypeError, ValueError):
            return 0.0

    def _runtime_rank_score(sym: str) -> float:
        if not runtime_rank:
            return 0.0
        raw_rank = runtime_rank.get(sym, runtime_rank.get(sym.lower(), 0.0))  # type: ignore[union-attr]
        try:
            rank = float(raw_rank)
        except (TypeError, ValueError):
            return 0.0
        if not math.isfinite(rank):
            return 0.0
        return rank

    def _rotation_key(sym: str) -> int:
        """Return deterministic cycle-local tie-break key to avoid alpha-only bias."""

        cycle_seed = max(int(prerank_cycle), 1)
        digest = hashlib.blake2b(
            f"{cycle_seed}:{sym}".encode("utf-8"),
            digest_size=8,
        ).digest()
        return int.from_bytes(digest, byteorder="big", signed=False)

    rank_source = "input_order"
    if runtime_rank:
        ranked = sorted(
            deduped,
            key=lambda sym: (
                -_runtime_rank_score(sym),
                -_weight(sym),
                _rotation_key(sym),
                sym,
            ),
        )
        rank_source = "runtime_rank"
    elif weights:
        ranked = sorted(deduped, key=lambda sym: (-_weight(sym), _rotation_key(sym), sym))
        rank_source = "portfolio_weights"
    else:
        ranked = list(deduped)

    sampling_priority_symbols: list[str] = []
    sampling_priority_reason = "inactive"
    sampling_snapshot: Mapping[str, Any] = {}
    if runtime is not None and _paper_sampling_runtime_active():
        try:
            sampling_cfg = getattr(runtime, "cfg", None) or _get_trading_config()
            sampling_snapshot = paper_sampling_deficit_snapshot(sampling_cfg)
        except BOT_ENGINE_FALLBACK_EXC as exc:
            logger.warning(
                "PAPER_SAMPLING_PRERANK_SNAPSHOT_FAILED",
                extra={"error": str(exc)},
            )
            sampling_snapshot = {}
        if bool(sampling_snapshot.get("active")) and bool(
            sampling_snapshot.get("fairness_enabled")
        ):
            configured_raw = sampling_snapshot.get("configured_symbols")
            configured_symbols = {
                str(symbol).strip().upper()
                for symbol in configured_raw
                if str(symbol).strip()
            } if isinstance(configured_raw, Sequence) and not isinstance(
                configured_raw,
                (str, bytes),
            ) else set()
            priority_candidates = paper_sampling_reservation_symbols(
                sampling_snapshot
            )
            ranked_set = set(ranked)
            sampling_priority_symbols = [
                symbol
                for symbol in priority_candidates
                if symbol in configured_symbols and symbol in ranked_set
            ]
            sampling_priority_reason = str(
                sampling_snapshot.get("priority_reason") or "balanced"
            )
            if sampling_priority_symbols:
                # Existing quality/rank ordering remains intact within each
                # partition. Only an explicit canonical reserved-stratum
                # deficit may move already-eligible symbols ahead of peers.
                original_rank = {
                    symbol: index for index, symbol in enumerate(ranked)
                }
                priority_rank = {
                    symbol: index
                    for index, symbol in enumerate(sampling_priority_symbols)
                }
                ranked = sorted(
                    ranked,
                    key=lambda symbol: (
                        0 if symbol in priority_rank else 1,
                        priority_rank.get(symbol, original_rank[symbol]),
                        original_rank[symbol],
                    ),
                )
                rank_source = f"{rank_source}+paper_sampling_reservation"

    exploration_enabled = False
    exploration_slots = 0
    exploration_symbols: list[str] = []
    if top_n is None or len(ranked) <= top_n:
        selected = ranked
        dropped: list[str] = []
    else:
        selected = ranked[:top_n]
        dropped = ranked[top_n:]
        if runtime is not None and runtime_rank:
            try:
                exploration_enabled = bool(
                    get_env(
                        "AI_TRADING_EXEC_CANDIDATE_TOP_N_EXPLORATION_ENABLED",
                        False,
                        cast=bool,
                    )
                )
            except BOT_ENGINE_FALLBACK_EXC:
                exploration_enabled = False
        if exploration_enabled and top_n >= 1 and dropped:
            try:
                exploration_fraction = float(
                    get_env(
                        "AI_TRADING_EXEC_CANDIDATE_TOP_N_EXPLORATION_FRAC",
                        0.2,
                        cast=float,
                    )
                )
            except BOT_ENGINE_FALLBACK_EXC:
                exploration_fraction = 0.2
            exploration_fraction = max(0.0, min(exploration_fraction, 0.9))
            try:
                exploration_min = int(
                    get_env(
                        "AI_TRADING_EXEC_CANDIDATE_TOP_N_EXPLORATION_MIN",
                        2,
                        cast=int,
                    )
                )
            except BOT_ENGINE_FALLBACK_EXC:
                exploration_min = 2
            exploration_min = max(1, min(exploration_min, max(top_n - 1, 1)))
            try:
                exploration_stale_cycles = int(
                    get_env(
                        "AI_TRADING_EXEC_CANDIDATE_TOP_N_EXPLORATION_STALE_CYCLES",
                        3,
                        cast=int,
                    )
                )
            except BOT_ENGINE_FALLBACK_EXC:
                exploration_stale_cycles = 3
            exploration_stale_cycles = max(1, min(exploration_stale_cycles, 1000))
            fraction_slots = (
                int(math.ceil(float(top_n) * exploration_fraction))
                if exploration_fraction > 0.0
                else 0
            )
            exploration_slots = max(exploration_min, fraction_slots)
            max_exploration_slots = top_n if top_n == 1 else top_n - 1
            exploration_slots = max(
                0,
                min(exploration_slots, max_exploration_slots, len(dropped)),
            )
            if exploration_slots > 0:

                def _stale_age(sym: str) -> int:
                    last_cycle = max(0, int(last_selected_cycles.get(sym, 0)))
                    cycle_now = max(int(prerank_cycle), 1)
                    return max(cycle_now - last_cycle, cycle_now if last_cycle <= 0 else 0)

                stale_pool = [
                    sym
                    for sym in dropped
                    if _stale_age(sym) >= int(exploration_stale_cycles)
                ]
                stale_pool_set = set(stale_pool)
                fallback_pool = [sym for sym in dropped if sym not in stale_pool_set]
                exploration_pool = stale_pool + fallback_pool
                exploration_pool.sort(
                    key=lambda sym: (
                        -_stale_age(sym),
                        -_runtime_rank_score(sym),
                        _rotation_key(sym),
                        sym,
                    )
                )
                exploration_symbols = exploration_pool[:exploration_slots]
                if exploration_symbols:
                    keep_count = max(0, top_n - len(exploration_symbols))
                    selected = selected[:keep_count] + exploration_symbols
                    selected_set = set(selected)
                    dropped = [sym for sym in ranked if sym not in selected_set]

    if runtime is not None and prerank_cycle > 0:
        store_execution_prerank_runtime_state(
            runtime,
            selected_symbols=selected,
            prerank_cycle=prerank_cycle,
            last_selected_cycles=last_selected_cycles,
        )
    logger.info(
        "EXECUTION_CANDIDATE_PRERANK",
        extra={
            "requested": len(ranked),
            "selected": len(selected),
            "top_n": top_n,
            "top_n_source": top_n_source,
            "adaptive_top_n_cap": adaptive_top_n_cap,
            "adaptive_submit_cap": adaptive_submit_cap,
            "adaptive_submit_cap_source": adaptive_submit_cap_source,
            "rank_source": rank_source,
            "paper_sampling_priority_reason": sampling_priority_reason,
            "paper_sampling_priority_symbols": sampling_priority_symbols,
            "paper_sampling_snapshot_date": sampling_snapshot.get("date"),
            "paper_sampling_snapshot_session": sampling_snapshot.get(
                "session_bucket"
            ),
            "prerank_cycle": int(prerank_cycle),
            "exploration_enabled": bool(exploration_enabled),
            "exploration_slots": int(exploration_slots),
            "exploration_sample": exploration_symbols[:10],
            "selected_sample": selected[:10],
            "dropped_sample": dropped[:10],
            "opportunity_quality_filter_enabled": bool(quality_filter_enabled),
            "opportunity_quality_threshold": (
                float(quality_threshold) if quality_threshold is not None else None
            ),
            "opportunity_quality_allowed_count": int(len(quality_allowed_symbols)),
            "opportunity_quality_allowed_sample": sorted(quality_allowed_symbols)[:10],
        },
    )
    _record_symbol_starvation_alert(
        ranked_symbols=ranked,
        selected_symbols=selected,
        runtime=runtime,
        prerank_cycle=prerank_cycle,
    )
    _record_prerank_shadow_snapshot(
        ranked_symbols=ranked,
        selected_symbols=selected,
        rank_source=rank_source,
        top_n=top_n,
        runtime=runtime,
    )
    _refresh_prerank_quote_status(
        selected_symbols=selected,
        runtime=runtime,
    )
    return selected


def _merge_managed_position_symbols(
    symbols: Sequence[str],
    positions: Mapping[str, Any],
) -> list[str]:
    """Ensure non-zero held positions remain actionable for risk management."""

    merged: list[str] = []
    seen_symbols: set[str] = set()
    for raw_symbol in symbols:
        symbol = str(raw_symbol).strip().upper()
        if not symbol or symbol in seen_symbols:
            continue
        seen_symbols.add(symbol)
        merged.append(symbol)

    for raw_symbol, raw_position in positions.items():
        symbol = str(raw_symbol).strip().upper()
        if not symbol or symbol in seen_symbols:
            continue
        try:
            quantity = float(raw_position or 0.0)
        except (TypeError, ValueError):
            quantity = 0.0
        if not math.isfinite(quantity) or quantity == 0.0:
            continue
        seen_symbols.add(symbol)
        merged.append(symbol)
    return merged


def _select_symbols_with_budget_rotation(
    symbols: Sequence[str],
    positions: Mapping[str, Any],
    *,
    symbol_budget: int,
    state: "BotState",
) -> tuple[list[str], int, int]:
    """Cap symbols while rotating held positions so the same subset is not starved."""

    if symbol_budget <= 0 or len(symbols) <= symbol_budget:
        return list(symbols), 0, 0

    held_symbols_unrotated = [
        sym
        for sym in symbols
        if abs(float(positions.get(sym, 0.0) or 0.0)) > 0.0
    ]
    held_symbols = list(held_symbols_unrotated)
    held_cursor_start = 0
    if held_symbols:
        try:
            held_cursor_start = int(max(getattr(state, "netting_symbol_budget_cursor", 0), 0))
        except (TypeError, ValueError):
            held_cursor_start = 0
        held_cursor_start = held_cursor_start % len(held_symbols)
        if held_cursor_start > 0:
            held_symbols = held_symbols[held_cursor_start:] + held_symbols[:held_cursor_start]

    selected_symbols: list[str] = []
    selected_set: set[str] = set()
    for sym in held_symbols:
        if sym in selected_set:
            continue
        selected_symbols.append(sym)
        selected_set.add(sym)
        if len(selected_symbols) >= symbol_budget:
            break
    for sym in symbols:
        if sym in selected_set:
            continue
        if len(selected_symbols) >= symbol_budget:
            break
        selected_symbols.append(sym)
        selected_set.add(sym)

    if held_symbols_unrotated:
        if len(held_symbols_unrotated) <= symbol_budget:
            state.netting_symbol_budget_cursor = 0
        else:
            state.netting_symbol_budget_cursor = (
                held_cursor_start + symbol_budget
            ) % len(held_symbols_unrotated)

    return selected_symbols, held_cursor_start, len(held_symbols_unrotated)


def _resolve_adaptive_order_cap(
    *,
    cycle_budget: Any | None,
    last_loop_duration_s: float | int | None,
) -> tuple[int | None, dict[str, Any]]:
    """Return adaptive per-cycle order cap based on budget headroom."""

    try:
        enabled = bool(get_env("AI_TRADING_ADAPTIVE_ORDER_CAP_ENABLED", False, cast=bool))
    except BOT_ENGINE_FALLBACK_EXC:
        enabled = False
    details: dict[str, Any] = {"enabled": enabled}
    if not enabled:
        return None, details

    interval_candidates: list[float] = []
    if cycle_budget is not None:
        try:
            interval_candidates.append(float(getattr(cycle_budget, "interval_s", 0.0) or 0.0))
        except BOT_ENGINE_FALLBACK_EXC:
            pass
    try:
        interval_candidates.append(float(get_env("AI_TRADING_INTERVAL", 60, cast=float)))
    except BOT_ENGINE_FALLBACK_EXC:
        pass
    try:
        interval_candidates.append(float(get_env("INTERVAL_WHEN_CLOSED", 60, cast=float)))
    except BOT_ENGINE_FALLBACK_EXC:
        pass
    interval_s = max((val for val in interval_candidates if val > 0.0), default=60.0)
    details["interval_s"] = interval_s

    ratios: list[float] = []
    if cycle_budget is not None:
        budget_obj = getattr(cycle_budget, "budget", None)
        if budget_obj is not None:
            try:
                remaining_s = max(float(budget_obj.remaining()), 0.0)
            except BOT_ENGINE_FALLBACK_EXC:
                remaining_s = None
            if remaining_s is not None:
                ratio = max(0.0, min(1.0, remaining_s / max(interval_s, 1e-6)))
                ratios.append(ratio)
                details["budget_headroom_ratio"] = ratio
    try:
        loop_duration = float(last_loop_duration_s or 0.0)
    except (TypeError, ValueError):
        loop_duration = 0.0
    loop_duration = max(loop_duration, 0.0)
    details["last_loop_duration_s"] = round(loop_duration, 6)
    if interval_s > 0.0:
        loop_headroom_ratio = max(0.0, min(1.0, (interval_s - loop_duration) / interval_s))
        ratios.append(loop_headroom_ratio)
        details["loop_headroom_ratio"] = loop_headroom_ratio

    if not ratios:
        return None, details
    headroom_ratio = min(ratios)
    details["headroom_ratio"] = headroom_ratio

    try:
        warn_ratio = float(
            get_env("AI_TRADING_ADAPTIVE_ORDER_CAP_WARN_HEADROOM_RATIO", 0.40, cast=float)
        )
    except BOT_ENGINE_FALLBACK_EXC:
        warn_ratio = 0.40
    try:
        crit_ratio = float(
            get_env("AI_TRADING_ADAPTIVE_ORDER_CAP_CRIT_HEADROOM_RATIO", 0.20, cast=float)
        )
    except BOT_ENGINE_FALLBACK_EXC:
        crit_ratio = 0.20
    warn_ratio = max(0.0, min(warn_ratio, 1.0))
    crit_ratio = max(0.0, min(crit_ratio, warn_ratio))
    details["warn_ratio"] = warn_ratio
    details["crit_ratio"] = crit_ratio

    try:
        warn_cap_raw = int(get_env("AI_TRADING_ADAPTIVE_ORDER_CAP_WARN_VALUE", 2, cast=int))
    except BOT_ENGINE_FALLBACK_EXC:
        warn_cap_raw = 2
    try:
        crit_cap_raw = int(get_env("AI_TRADING_ADAPTIVE_ORDER_CAP_CRIT_VALUE", 1, cast=int))
    except BOT_ENGINE_FALLBACK_EXC:
        crit_cap_raw = 1
    warn_cap = max(1, min(warn_cap_raw, 25))
    crit_cap = max(1, min(crit_cap_raw, warn_cap))
    details["warn_cap"] = warn_cap
    details["crit_cap"] = crit_cap

    if headroom_ratio <= crit_ratio:
        details["mode"] = "critical"
        return crit_cap, details
    if headroom_ratio <= warn_ratio:
        details["mode"] = "warning"
        return warn_cap, details
    details["mode"] = "normal"
    return None, details


def _resolve_slo_derisk_effective_mode(
    *,
    configured_mode: str,
    reject_breached: bool,
    drift_breached: bool,
    slippage_breached: bool,
    calibration_ece_breached: bool,
    calibration_brier_breached: bool,
    feature_drift_breached: bool,
    label_drift_breached: bool,
    residual_drift_breached: bool,
    pacing_breached: bool,
    pending_breached: bool,
    pacing_hit_rate_pct: float,
    pending_oldest_age_sec: float,
) -> tuple[str, float, dict[str, Any]]:
    """Return effective SLO de-risk mode with optional safe block->scale relaxation."""

    mode = str(configured_mode or "block").strip().lower()
    if mode not in {"block", "scale", "adaptive"}:
        mode = "block"

    try:
        configured_scale = float(get_env("AI_TRADING_DERISK_SLO_SCALE_MULT", 0.50, cast=float))
    except BOT_ENGINE_FALLBACK_EXC:
        configured_scale = 0.50
    configured_scale = max(0.05, min(configured_scale, 1.0))

    try:
        relax_enabled = bool(get_env("AI_TRADING_DERISK_SLO_BLOCK_RELAX_ENABLED", True, cast=bool))
    except BOT_ENGINE_FALLBACK_EXC:
        relax_enabled = True
    try:
        relax_scale = float(get_env("AI_TRADING_DERISK_SLO_BLOCK_RELAX_SCALE_MULT", 0.70, cast=float))
    except BOT_ENGINE_FALLBACK_EXC:
        relax_scale = 0.70
    relax_scale = max(0.05, min(relax_scale, 1.0))
    try:
        severe_pacing_pct = float(
            get_env("AI_TRADING_DERISK_SLO_BLOCK_RELAX_PACING_SEVERE_PCT", 75.0, cast=float)
        )
    except BOT_ENGINE_FALLBACK_EXC:
        severe_pacing_pct = 75.0
    severe_pacing_pct = max(0.0, min(severe_pacing_pct, 100.0))
    try:
        severe_pending_sec = float(
            get_env("AI_TRADING_DERISK_SLO_BLOCK_RELAX_PENDING_SEVERE_SEC", 1800.0, cast=float)
        )
    except BOT_ENGINE_FALLBACK_EXC:
        severe_pending_sec = 1800.0
    severe_pending_sec = max(60.0, min(severe_pending_sec, 86400.0))
    try:
        max_friction_breaches = int(
            get_env("AI_TRADING_DERISK_SLO_BLOCK_RELAX_MAX_FRICTION_BREACHES", 2, cast=int)
        )
    except BOT_ENGINE_FALLBACK_EXC:
        max_friction_breaches = 2
    max_friction_breaches = max(1, min(max_friction_breaches, 10))

    core_breach_count = int(
        sum(
            bool(value)
            for value in (
                reject_breached,
                drift_breached,
                slippage_breached,
                calibration_ece_breached,
                calibration_brier_breached,
                feature_drift_breached,
                label_drift_breached,
                residual_drift_breached,
            )
        )
    )
    friction_breach_count = int(sum(bool(value) for value in (pacing_breached, pending_breached)))
    severe_friction = bool(
        (pacing_breached and float(pacing_hit_rate_pct) >= severe_pacing_pct)
        or (pending_breached and float(pending_oldest_age_sec) >= severe_pending_sec)
        or friction_breach_count > max_friction_breaches
    )

    details: dict[str, Any] = {
        "configured_mode": mode,
        "effective_mode": mode,
        "effective_scale_mult": float(configured_scale if mode == "scale" else 1.0),
        "block_relax_enabled": bool(relax_enabled),
        "block_relax_applied": False,
        "block_relax_reason": "",
        "core_breach_count": int(core_breach_count),
        "friction_breach_count": int(friction_breach_count),
        "friction_severe": bool(severe_friction),
    }

    if mode == "scale":
        return "scale", float(configured_scale), details

    if mode == "adaptive":
        if core_breach_count > 0:
            details["effective_mode"] = "block"
            details["effective_scale_mult"] = 1.0
            details["block_relax_reason"] = "core_breach"
            return "block", 1.0, details
        if friction_breach_count > 0 and not severe_friction:
            details["effective_mode"] = "scale"
            details["effective_scale_mult"] = float(relax_scale)
            details["block_relax_applied"] = True
            details["block_relax_reason"] = "friction_breach"
            return "scale", float(relax_scale), details
        details["effective_mode"] = "block"
        details["effective_scale_mult"] = 1.0
        details["block_relax_reason"] = "friction_severe" if friction_breach_count > 0 else "no_relax"
        return "block", 1.0, details

    if relax_enabled and core_breach_count == 0 and friction_breach_count > 0 and not severe_friction:
        details["effective_mode"] = "scale"
        details["effective_scale_mult"] = float(relax_scale)
        details["block_relax_applied"] = True
        details["block_relax_reason"] = "block_relaxed_friction_only"
        return "scale", float(relax_scale), details

    details["effective_mode"] = "block"
    details["effective_scale_mult"] = 1.0
    if core_breach_count > 0:
        details["block_relax_reason"] = "core_breach"
    elif friction_breach_count > 0 and severe_friction:
        details["block_relax_reason"] = "friction_severe"
    else:
        details["block_relax_reason"] = "block_mode"
    return "block", 1.0, details


def _resolve_capacity_throttle_adaptive_params(
    *,
    spread_soft_bps: float,
    spread_hard_bps: float,
    volume_soft_participation: float,
    volume_hard_participation: float,
    min_scale: float,
    slo_derisk_details: Mapping[str, Any],
) -> tuple[float, float, float, float, float, dict[str, Any]]:
    """Return adaptive capacity-throttle parameters from live execution telemetry."""

    try:
        enabled = bool(get_env("AI_TRADING_CAPACITY_THROTTLE_ADAPTIVE_ENABLED", True, cast=bool))
    except BOT_ENGINE_FALLBACK_EXC:
        enabled = True
    details: dict[str, Any] = {
        "enabled": bool(enabled),
        "mode": "disabled" if not enabled else "steady",
        "base_spread_soft_bps": float(spread_soft_bps),
        "base_spread_hard_bps": float(spread_hard_bps),
        "base_volume_soft_participation": float(volume_soft_participation),
        "base_volume_hard_participation": float(volume_hard_participation),
        "base_min_scale": float(min_scale),
    }
    if not enabled:
        return (
            float(spread_soft_bps),
            float(spread_hard_bps),
            float(volume_soft_participation),
            float(volume_hard_participation),
            float(min_scale),
            details,
        )

    try:
        min_samples = int(get_env("AI_TRADING_CAPACITY_THROTTLE_ADAPTIVE_MIN_SAMPLES", 10, cast=int))
    except BOT_ENGINE_FALLBACK_EXC:
        min_samples = 10
    min_samples = max(1, min(min_samples, 10_000))

    try:
        pacing_clear_pct = float(
            get_env("AI_TRADING_CAPACITY_THROTTLE_ADAPTIVE_PACING_CLEAR_PCT", 8.0, cast=float)
        )
    except BOT_ENGINE_FALLBACK_EXC:
        pacing_clear_pct = 8.0
    try:
        pacing_tighten_pct = float(
            get_env("AI_TRADING_CAPACITY_THROTTLE_ADAPTIVE_PACING_TIGHTEN_PCT", 20.0, cast=float)
        )
    except BOT_ENGINE_FALLBACK_EXC:
        pacing_tighten_pct = 20.0
    pacing_clear_pct = max(0.0, min(pacing_clear_pct, 100.0))
    pacing_tighten_pct = max(pacing_clear_pct, min(pacing_tighten_pct, 100.0))

    try:
        reject_clear_pct = float(
            get_env("AI_TRADING_CAPACITY_THROTTLE_ADAPTIVE_REJECT_CLEAR_PCT", 2.5, cast=float)
        )
    except BOT_ENGINE_FALLBACK_EXC:
        reject_clear_pct = 2.5
    reject_clear_pct = max(0.0, min(reject_clear_pct, 100.0))

    try:
        relax_mult = float(get_env("AI_TRADING_CAPACITY_THROTTLE_ADAPTIVE_RELAX_MULT", 1.15, cast=float))
    except BOT_ENGINE_FALLBACK_EXC:
        relax_mult = 1.15
    try:
        tighten_mult = float(
            get_env("AI_TRADING_CAPACITY_THROTTLE_ADAPTIVE_TIGHTEN_MULT", 0.90, cast=float)
        )
    except BOT_ENGINE_FALLBACK_EXC:
        tighten_mult = 0.90
    relax_mult = max(1.0, min(relax_mult, 3.0))
    tighten_mult = max(0.25, min(tighten_mult, 1.0))

    try:
        relax_min_scale_add = float(
            get_env("AI_TRADING_CAPACITY_THROTTLE_ADAPTIVE_RELAX_MIN_SCALE_ADD", 0.10, cast=float)
        )
    except BOT_ENGINE_FALLBACK_EXC:
        relax_min_scale_add = 0.10
    try:
        tighten_min_scale_mult = float(
            get_env("AI_TRADING_CAPACITY_THROTTLE_ADAPTIVE_TIGHTEN_MIN_SCALE_MULT", 0.85, cast=float)
        )
    except BOT_ENGINE_FALLBACK_EXC:
        tighten_min_scale_mult = 0.85
    relax_min_scale_add = max(0.0, min(relax_min_scale_add, 0.5))
    tighten_min_scale_mult = max(0.2, min(tighten_min_scale_mult, 1.0))
    try:
        pending_soft_sec = float(
            get_env(
                "AI_TRADING_CAPACITY_THROTTLE_ADAPTIVE_PENDING_SOFT_SEC",
                45.0,
                cast=float,
            )
        )
    except BOT_ENGINE_FALLBACK_EXC:
        pending_soft_sec = 45.0
    try:
        pending_hard_sec = float(
            get_env(
                "AI_TRADING_CAPACITY_THROTTLE_ADAPTIVE_PENDING_HARD_SEC",
                120.0,
                cast=float,
            )
        )
    except BOT_ENGINE_FALLBACK_EXC:
        pending_hard_sec = 120.0
    pending_soft_sec = max(0.0, min(float(pending_soft_sec), 3600.0))
    pending_hard_sec = max(float(pending_soft_sec), min(float(pending_hard_sec), 7200.0))
    try:
        slippage_soft_bps = float(
            get_env(
                "AI_TRADING_CAPACITY_THROTTLE_ADAPTIVE_SLIPPAGE_SOFT_BPS",
                10.0,
                cast=float,
            )
        )
    except BOT_ENGINE_FALLBACK_EXC:
        slippage_soft_bps = 10.0
    try:
        slippage_hard_bps = float(
            get_env(
                "AI_TRADING_CAPACITY_THROTTLE_ADAPTIVE_SLIPPAGE_HARD_BPS",
                16.0,
                cast=float,
            )
        )
    except BOT_ENGINE_FALLBACK_EXC:
        slippage_hard_bps = 16.0
    slippage_soft_bps = max(0.0, min(float(slippage_soft_bps), 250.0))
    slippage_hard_bps = max(float(slippage_soft_bps), min(float(slippage_hard_bps), 500.0))
    try:
        stress_tighten_mult = float(
            get_env(
                "AI_TRADING_CAPACITY_THROTTLE_ADAPTIVE_STRESS_TIGHTEN_MULT",
                0.82,
                cast=float,
            )
        )
    except BOT_ENGINE_FALLBACK_EXC:
        stress_tighten_mult = 0.82
    try:
        stress_min_scale_mult = float(
            get_env(
                "AI_TRADING_CAPACITY_THROTTLE_ADAPTIVE_STRESS_MIN_SCALE_MULT",
                0.80,
                cast=float,
            )
        )
    except BOT_ENGINE_FALLBACK_EXC:
        stress_min_scale_mult = 0.80
    stress_tighten_mult = max(0.25, min(float(stress_tighten_mult), 1.0))
    stress_min_scale_mult = max(0.2, min(float(stress_min_scale_mult), 1.0))

    pacing_samples = int(float(slo_derisk_details.get("pacing_samples", 0) or 0.0))
    pacing_hit_pct = float(slo_derisk_details.get("order_pacing_cap_hit_rate_pct", 0.0) or 0.0)
    reject_rate_pct = float(slo_derisk_details.get("reject_rate_pct", 0.0) or 0.0)
    pending_samples = int(float(slo_derisk_details.get("pending_samples", 0) or 0.0))
    pending_oldest_age_sec = float(slo_derisk_details.get("pending_oldest_age_sec", 0.0) or 0.0)
    slippage_samples = int(float(slo_derisk_details.get("slippage_samples", 0) or 0.0))
    slippage_bps = float(slo_derisk_details.get("slippage_bps", 0.0) or 0.0)
    pacing_breached = bool(slo_derisk_details.get("pacing_breached", False))
    pending_breached = bool(slo_derisk_details.get("pending_breached", False))
    pending_latency_stress = bool(
        pending_samples >= 1 and pending_oldest_age_sec >= pending_soft_sec
    )
    pending_latency_severe = bool(
        pending_samples >= 1 and pending_oldest_age_sec >= pending_hard_sec
    )
    slippage_stress = bool(slippage_samples >= min_samples and slippage_bps >= slippage_soft_bps)
    slippage_severe = bool(slippage_samples >= min_samples and slippage_bps >= slippage_hard_bps)
    microstructure_stress = bool(pending_latency_stress or slippage_stress)
    microstructure_severe = bool(pending_latency_severe or slippage_severe)

    details.update(
        {
            "pacing_samples": int(pacing_samples),
            "pacing_hit_rate_pct": float(pacing_hit_pct),
            "reject_rate_pct": float(reject_rate_pct),
            "pacing_breached": bool(pacing_breached),
            "pending_breached": bool(pending_breached),
            "pending_samples": int(pending_samples),
            "pending_oldest_age_sec": float(pending_oldest_age_sec),
            "slippage_samples": int(slippage_samples),
            "slippage_bps": float(slippage_bps),
            "min_samples": int(min_samples),
            "pacing_clear_pct": float(pacing_clear_pct),
            "pacing_tighten_pct": float(pacing_tighten_pct),
            "reject_clear_pct": float(reject_clear_pct),
            "pending_soft_sec": float(pending_soft_sec),
            "pending_hard_sec": float(pending_hard_sec),
            "slippage_soft_bps": float(slippage_soft_bps),
            "slippage_hard_bps": float(slippage_hard_bps),
            "pending_latency_stress": bool(pending_latency_stress),
            "pending_latency_severe": bool(pending_latency_severe),
            "slippage_stress": bool(slippage_stress),
            "slippage_severe": bool(slippage_severe),
            "microstructure_stress": bool(microstructure_stress),
            "microstructure_severe": bool(microstructure_severe),
        }
    )

    tuned_spread_soft = max(0.1, float(spread_soft_bps))
    tuned_spread_hard = max(tuned_spread_soft + 0.1, float(spread_hard_bps))
    tuned_vol_soft = max(0.0001, float(volume_soft_participation))
    tuned_vol_hard = max(tuned_vol_soft + 0.0001, float(volume_hard_participation))
    tuned_min_scale = max(0.05, min(float(min_scale), 1.0))

    if microstructure_stress:
        details["mode"] = "tightened"
        active_tighten_mult = min(tighten_mult, stress_tighten_mult)
        active_min_scale_mult = min(tighten_min_scale_mult, stress_min_scale_mult)
        if microstructure_severe:
            active_tighten_mult = min(active_tighten_mult, 0.85 * stress_tighten_mult)
            active_min_scale_mult = min(active_min_scale_mult, 0.9 * stress_min_scale_mult)
        tuned_spread_soft = max(0.1, tuned_spread_soft * active_tighten_mult)
        tuned_spread_hard = max(tuned_spread_soft + 0.1, tuned_spread_hard * active_tighten_mult)
        tuned_vol_soft = max(0.0001, tuned_vol_soft * active_tighten_mult)
        tuned_vol_hard = max(tuned_vol_soft + 0.0001, tuned_vol_hard * active_tighten_mult)
        tuned_min_scale = max(0.05, min(tuned_min_scale * active_min_scale_mult, 1.0))
    elif pacing_samples < min_samples:
        details["mode"] = "insufficient_samples"
    elif pacing_breached or pending_breached or pacing_hit_pct >= pacing_tighten_pct:
        details["mode"] = "tightened"
        tuned_spread_soft = max(0.1, tuned_spread_soft * tighten_mult)
        tuned_spread_hard = max(tuned_spread_soft + 0.1, tuned_spread_hard * tighten_mult)
        tuned_vol_soft = max(0.0001, tuned_vol_soft * tighten_mult)
        tuned_vol_hard = max(tuned_vol_soft + 0.0001, tuned_vol_hard * tighten_mult)
        tuned_min_scale = max(0.05, min(tuned_min_scale * tighten_min_scale_mult, 1.0))
    elif pacing_hit_pct <= pacing_clear_pct and reject_rate_pct <= reject_clear_pct:
        details["mode"] = "relaxed"
        tuned_spread_soft = max(0.1, tuned_spread_soft * relax_mult)
        tuned_spread_hard = max(tuned_spread_soft + 0.1, tuned_spread_hard * relax_mult)
        tuned_vol_soft = min(1.0, max(0.0001, tuned_vol_soft * relax_mult))
        tuned_vol_hard = min(1.0, max(tuned_vol_soft + 0.0001, tuned_vol_hard * relax_mult))
        tuned_min_scale = min(1.0, max(tuned_min_scale, tuned_min_scale + relax_min_scale_add))

    details.update(
        {
            "spread_soft_bps": float(tuned_spread_soft),
            "spread_hard_bps": float(tuned_spread_hard),
            "volume_soft_participation": float(tuned_vol_soft),
            "volume_hard_participation": float(tuned_vol_hard),
            "min_scale": float(tuned_min_scale),
        }
    )
    return (
        float(tuned_spread_soft),
        float(tuned_spread_hard),
        float(tuned_vol_soft),
        float(tuned_vol_hard),
        float(tuned_min_scale),
        details,
    )


def _mask_env_name(name: str) -> str:
    return f"{name[:8]}***"


def _get_env_str(key: str) -> str:
    raw = get_env(key, resolve_aliases=False)
    if raw not in (None, ""):
        return str(raw)
    masked = _mask_env_name(key)
    logger.error("Missing required environment variable: %s", masked)
    raise RuntimeError(f"Missing required environment variable: {masked}")


def _env_flag(key: str, default: bool = False) -> bool:
    """Return a boolean environment toggle respecting settings aliases."""

    try:
        value = get_env(key, None)
    except COMMON_EXC:
        value = None
    if value is None:
        value = get_env(key)
    if isinstance(value, bool):
        return value
    if value in (None, ""):
        return default
    try:
        return str(value).strip().lower() in {"1", "true", "yes", "on"}
    except COMMON_EXC:
        return default


