def _is_day_sleeve_ml_timeframe(sleeve_name: Any, timeframe: Any) -> bool:
    return (
        str(sleeve_name or "").strip().lower() == "day"
        and normalize_bar_timeframe(timeframe) == DAY_SLEEVE_ML_BAR_TIMEFRAME
    )


def _netting_sleeve_fetch_start(
    *,
    sleeve_name: Any,
    timeframe: Any,
    now: datetime,
) -> datetime:
    """Return enough history for the sleeve's longest required feature window."""

    if _is_day_sleeve_ml_timeframe(sleeve_name, timeframe):
        lookback_days = max(
            7,
            min(
                int(
                    get_env(
                        "AI_TRADING_DAY_SLEEVE_ML_LOOKBACK_DAYS",
                        10,
                        cast=int,
                    )
                ),
                60,
            ),
        )
        return now - timedelta(days=lookback_days)
    return now - timedelta(
        seconds=_freshness_seconds_for_timeframe(str(timeframe)) * 50
    )


def _finalized_day_sleeve_bars(
    frame: pd.DataFrame,
    *,
    now: datetime,
    grace_seconds: float,
) -> pd.DataFrame:
    """Remove any five-minute bar whose close boundary has not passed."""

    if frame is None or frame.empty:
        return frame
    if not isinstance(frame.index, pd.DatetimeIndex) or frame.index.tz is None:
        return frame.iloc[0:0].copy()
    bounded_grace = max(0.0, min(float(grace_seconds), 60.0))
    cutoff = pd.Timestamp(now.astimezone(UTC) - timedelta(seconds=bounded_grace))
    bar_close = frame.index.tz_convert(UTC) + pd.Timedelta(minutes=5)
    return frame.loc[bar_close <= cutoff].copy()


def _day_sleeve_waiting_for_first_finalized_bar(
    frame: pd.DataFrame,
    *,
    now: datetime,
    grace_seconds: float,
) -> bool:
    """Return whether the current session first five-minute bar is not due."""

    now_eastern = now.astimezone(ZoneInfo("America/New_York"))
    if now_eastern.weekday() >= 5:
        return False
    minute = now_eastern.hour * 60 + now_eastern.minute
    if minute < 9 * 60 + 30:
        return False
    first_bar_due = now_eastern.replace(
        hour=9, minute=35, second=0, microsecond=0
    ) + timedelta(seconds=max(0.0, min(float(grace_seconds), 60.0)))
    if now_eastern >= first_bar_due:
        return False
    if frame is None or frame.empty:
        return True
    try:
        latest_session_date = frame.index[-1].tz_convert(
            "America/New_York"
        ).date()
    except (AttributeError, TypeError, ValueError):
        return False
    return bool(latest_session_date < now_eastern.date())


# AI-AGENT-REF: emit-once helper and readiness gate for startup/runtime coordination
_EMITTED_KEYS: set[str] = set()


def _emit_once(logger: Any, key: str, level: int, msg: str) -> None:
    """Emit log message only once per key."""
    if key in _EMITTED_KEYS:
        return
    _EMITTED_KEYS.add(key)
    logger.log(level, msg)


_RUNTIME_READY: bool = False

# Guard to ensure configuration-loaded log only fires once per reload cycle
_CONFIG_LOGGED: bool = False


def _should_relax_drawdown_requirements() -> bool:
    return (
        _pytest_running()
        or _truthy_env(get_env("TESTING", None, resolve_aliases=False))
        or _truthy_env(get_env("RUN_HEALTHCHECK", None, resolve_aliases=False))
    )


def _trading_config_from_env(
    *, allow_missing_drawdown: bool | None = None
) -> TradingConfig:
    if allow_missing_drawdown is None:
        allow_missing_drawdown = _should_relax_drawdown_requirements()
    return TradingConfig.from_env(allow_missing_drawdown=allow_missing_drawdown)


def _log_config_loaded() -> None:
    """Log that configuration settings have been loaded."""
    global _CONFIG_LOGGED
    if not _CONFIG_LOGGED:
        logger.info("Config settings loaded")
        _CONFIG_LOGGED = True


def _reset_config_log() -> None:
    global _CONFIG_LOGGED
    _CONFIG_LOGGED = False


@lru_cache(maxsize=1)
def _get_trading_config() -> TradingConfig:
    """Return cached ``TradingConfig`` and emit log once."""
    cfg = _trading_config_from_env()
    _log_config_loaded()
    return cfg


def _reload_env(path: str | None = None, *, override: bool = False) -> str | None:
    """Reload environment variables and reset log guard."""
    result = config.reload_env(path, override=override)
    _get_trading_config.cache_clear()
    _reset_config_log()
    return result


def _normalize_runtime_trading_mode(raw: Any) -> str:
    """Normalize mode labels and fall back to balanced when invalid."""

    normalized = str(raw or "").strip().lower()
    if normalized in {"conservative", "balanced", "aggressive"}:
        return normalized
    return DEFAULT_TRADING_MODE


def _resolve_runtime_trading_mode() -> str:
    """Resolve trading mode from TradingConfig as the single source of truth."""

    try:
        cfg = _get_trading_config()
        return _normalize_runtime_trading_mode(
            getattr(cfg, "trading_mode", DEFAULT_TRADING_MODE)
        )
    except COMMON_EXC:
        env_mode = get_env("AI_TRADING_TRADING_MODE") or DEFAULT_TRADING_MODE
        return _normalize_runtime_trading_mode(env_mode)


def is_runtime_ready() -> bool:
    """Check if runtime context is fully initialized."""
    return _RUNTIME_READY


_HEALTH_CHECK_FAILURES = 0
_HEALTH_CHECK_FAIL_THRESHOLD = 3

_EMPTY_TRADE_LOG_INFO_EMITTED = False
_PARSE_LOCAL_POSITIONS_EMPTY_EMITTED = False
_PARSE_LOCAL_POSITIONS_MISSING_EMITTED = False
_TRADE_LOG_CACHE: Any | None = None
_TRADE_LOG_CACHE_LOADED = False


def _startup_prefetch_daily_data(ctx: Any, symbols: Sequence[str]) -> dict[str, Any]:
    """Warm a small daily-data slice at startup with bounded retries."""

    summary: dict[str, Any] = {
        "enabled": bool(get_env("AI_TRADING_STARTUP_PREFETCH_ENABLED", True, cast=bool)),
        "attempts": 0,
        "success_count": 0,
        "failure_count": 0,
        "symbols": [],
        "failed_symbols": [],
    }
    if not summary["enabled"]:
        return summary
    if not hasattr(ctx, "data_fetcher"):
        summary["reason"] = "missing_data_fetcher"
        return summary

    symbol_limit = max(
        0,
        int(get_env("AI_TRADING_STARTUP_PREFETCH_SYMBOL_LIMIT", 6, cast=int)),
    )
    selected_symbols = [
        str(symbol).strip().upper()
        for symbol in symbols
        if str(symbol).strip()
    ]
    selected_symbols = list(dict.fromkeys(selected_symbols))
    if symbol_limit > 0:
        selected_symbols = selected_symbols[:symbol_limit]
    summary["symbols"] = selected_symbols
    if not selected_symbols:
        summary["reason"] = "no_symbols"
        return summary

    retries = max(
        1,
        int(get_env("AI_TRADING_STARTUP_PREFETCH_RETRIES", 2, cast=int)),
    )
    retry_delay_sec = max(
        0.0,
        float(get_env("AI_TRADING_STARTUP_PREFETCH_RETRY_DELAY_SEC", 0.75, cast=float)),
    )
    min_success_ratio = min(
        1.0,
        max(
            0.0,
            float(get_env("AI_TRADING_STARTUP_PREFETCH_MIN_SUCCESS_RATIO", 0.5, cast=float)),
        ),
    )
    min_success_count = max(1, math.ceil(len(selected_symbols) * min_success_ratio))

    success_symbols: set[str] = set()
    failures: dict[str, str] = {}
    end_dt = datetime.now(UTC)
    start_dt = end_dt - timedelta(days=10)
    for attempt in range(1, retries + 1):
        summary["attempts"] = attempt
        for symbol in selected_symbols:
            if symbol in success_symbols:
                continue
            try:
                frame = data_fetcher_module.get_daily_df(symbol, start=start_dt, end=end_dt)
            except BOT_ENGINE_FALLBACK_EXC as exc:
                failures[symbol] = str(exc)
                continue
            if frame is None or bool(getattr(frame, "empty", False)):
                failures[symbol] = "empty"
                continue
            success_symbols.add(symbol)
            failures.pop(symbol, None)
        if len(success_symbols) >= min_success_count:
            break
        if attempt < retries and failures:
            time.sleep(retry_delay_sec * attempt)

    summary["success_count"] = len(success_symbols)
    summary["failure_count"] = len(failures)
    summary["failed_symbols"] = sorted(failures.keys())
    if failures:
        summary["failed_reasons"] = {
            symbol: failures[symbol]
            for symbol in sorted(failures.keys())[:5]
        }
    return summary


def _initialize_bot_context_post_setup(ctx: Any) -> None:
    """
    Optional, non-fatal finishing steps after LazyBotContext builds its services.
    Never raise: any failure logs a warning and returns.
    """
    global _HEALTH_CHECK_FAILURES
    _load_trade_log_cache()
    try:
        # Skip health check when market is closed and daily cache is already warm
        try:
            if (not is_market_open()) and hasattr(ctx, "data_fetcher"):
                _dc = getattr(ctx.data_fetcher, "_daily_cache", {})
                if isinstance(_dc, dict) and len(_dc) > 0:
                    logger.info(
                        "HEALTH_CHECK_SKIPPED_CLOSED_CACHE_WARM",
                        extra={"cached_symbols": list(_dc.keys())[:5], "count": len(_dc)},
                    )
                    return
        except (AttributeError, KeyError, TypeError):
            pass
        backup_provider_name = str(get_env("BACKUP_PROVIDER", "yahoo", cast=str) or "yahoo").strip() or "yahoo"
        backup_before = backup_provider_used_total(backup_provider_name)
        startup_symbols = list(globals().get("REGIME_SYMBOLS", []))
        prefetch_summary = _startup_prefetch_daily_data(ctx, startup_symbols)
        if prefetch_summary.get("enabled"):
            prefetch_level = logging.INFO
            if int(prefetch_summary.get("failure_count", 0) or 0) > 0:
                prefetch_level = logging.WARNING
            logger.log(prefetch_level, "STARTUP_PREFETCH_SUMMARY", extra=prefetch_summary)
        if "data_source_health_check" in globals() and "REGIME_SYMBOLS" in globals():
            max_attempts = 3
            for attempt in range(1, max_attempts + 1):
                try:
                    data_source_health_check(ctx, REGIME_SYMBOLS)  # type: ignore[name-defined]
                    logger.info("Post-setup data source health check completed.")
                    _HEALTH_CHECK_FAILURES = 0
                    break
                except APIError as e:
                    if attempt < max_attempts:
                        logger.warning(
                            "HEALTH_CHECK_FAILED",
                            extra={"cause": "APIError", "attempt": attempt, "detail": str(e)},
                        )
                        time.sleep(attempt)
                        continue
                    _HEALTH_CHECK_FAILURES += 1
                    level = (
                        logger.warning
                        if _HEALTH_CHECK_FAILURES < _HEALTH_CHECK_FAIL_THRESHOLD
                        else logger.error
                    )
                    level(
                        "HEALTH_CHECK_FAILED",
                        extra={
                            "cause": "APIError",
                            "detail": str(e),
                            "failures": _HEALTH_CHECK_FAILURES,
                        },
                    )
                    try:
                        ctx.data_fetcher = data_fetcher_module.build_fetcher()  # type: ignore[attr-defined]
                    except (AttributeError, TypeError):
                        pass
                except ImportError as e:
                    logger.warning(
                        "HEALTH_CHECK_SKIPPED_IMPORT",
                        extra={"cause": "ImportError", "detail": str(e)},
                    )
                    break
            backup_after = backup_provider_used_total(backup_provider_name)
            backup_delta = max(0, int(backup_after - backup_before))
            backup_alert_threshold = max(
                1,
                int(get_env("AI_TRADING_STARTUP_BACKUP_ALERT_THRESHOLD", 2, cast=int)),
            )
            if backup_delta >= backup_alert_threshold:
                logger.warning(
                    "STARTUP_BACKUP_PROVIDER_USAGE_HIGH",
                    extra={
                        "provider": backup_provider_name,
                        "delta": backup_delta,
                        "total": backup_after,
                        "threshold": backup_alert_threshold,
                    },
                )
        else:
            logger.debug("Post-setup health check not available; skipping.")
    except (
        APIError,
        TimeoutError,
        ConnectionError,
        KeyError,
        ValueError,
        TypeError,
        OSError,
    ) as e:  # AI-AGENT-REF: tighten health probe error handling
        _HEALTH_CHECK_FAILURES += 1
        level = (
            logger.warning
            if _HEALTH_CHECK_FAILURES < _HEALTH_CHECK_FAIL_THRESHOLD
            else logger.error
        )
        level(
            "HEALTH_CHECK_FAILED",
            extra={"cause": e.__class__.__name__, "detail": str(e), "failures": _HEALTH_CHECK_FAILURES},
        )


