def _resolve_rl_model_path(raw_path: str | None = None) -> Path | None:
    candidate = str(raw_path or "").strip()
    if not candidate:
        candidate = str(get_env("AI_TRADING_RL_MODEL_PATH", "") or "").strip()
    if not candidate:
        return None
    return resolve_runtime_artifact_path(
        candidate,
        default_relative="models/runtime/rl_agent.zip",
    )


def _resolve_rl_governance_sidecar_path(model_path: Path) -> Path:
    return Path(f"{model_path}.governance.json")


def _rl_runtime_governance_allows_load(
    model_path: Path,
    *,
    test_mode: bool,
) -> tuple[bool, str]:
    require_raw = str(
        get_env("AI_TRADING_RL_RUNTIME_REQUIRE_GOVERNANCE", "", cast=str) or ""
    ).strip()
    if require_raw:
        require_governance = require_raw.lower() not in {"0", "false", "no", "off"}
    else:
        require_governance = not test_mode
    if not require_governance:
        return True, "disabled"

    sidecar_path = _resolve_rl_governance_sidecar_path(model_path)
    if not sidecar_path.exists():
        return False, "sidecar_missing"

    try:
        payload = json.loads(sidecar_path.read_text(encoding="utf-8"))
    except (OSError, ValueError, json.JSONDecodeError):
        return False, "sidecar_unreadable"
    if not isinstance(payload, MappingABC):
        return False, "sidecar_invalid"

    status_raw = payload.get("governance_status") or payload.get("status")
    status = str(status_raw or "").strip().lower()
    recommend_use_rl = bool(payload.get("recommend_use_rl_agent", False))
    require_production = bool(
        get_env("AI_TRADING_RL_RUNTIME_REQUIRE_PRODUCTION", True, cast=bool)
    )
    require_recommend = bool(
        get_env("AI_TRADING_RL_RUNTIME_REQUIRE_RECOMMEND", True, cast=bool)
    )

    if require_production and status != "production":
        return False, f"governance_status_{status or 'missing'}"
    if require_recommend and not recommend_use_rl:
        return False, "recommend_use_rl_agent_false"
    return True, "ok"


def _bootstrap_missing_rl_governance_sidecar(model_path: Path) -> tuple[bool, str]:
    sidecar_path = _resolve_rl_governance_sidecar_path(model_path)
    if not model_path.is_file():
        return False, "model_missing"
    payload = {
        "updated_at": dt_.now(UTC).isoformat(),
        "runtime_model_path": str(model_path),
        "governance_status": "shadow",
        "recommend_use_rl_agent": False,
        "bootstrap_reason": "sidecar_missing",
    }
    try:
        sidecar_path.parent.mkdir(parents=True, exist_ok=True)
        sidecar_path.write_text(json.dumps(payload), encoding="utf-8")
    except OSError:
        return False, "sidecar_bootstrap_write_failed"
    return True, "sidecar_bootstrapped"


def _rl_model_signature(path: Path | None) -> tuple[str, int, int] | None:
    if path is None:
        return None
    try:
        stats = path.stat()
    except OSError:
        return None
    return str(path), int(stats.st_mtime_ns), int(stats.st_size)


def _reload_rl_agent_from_runtime_path(
    *,
    model_path: str | None = None,
    reason: str = "runtime",
    force: bool = False,
    use_rl_enabled: bool | None = None,
) -> bool:
    global RL_AGENT, RL_MODEL_PATH, _RL_AGENT_SIGNATURE

    enabled = (
        bool(use_rl_enabled)
        if use_rl_enabled is not None
        else bool(get_env("USE_RL_AGENT", False, cast=bool))
    )
    require_runtime_stack = bool(
        get_env("AI_TRADING_RL_REQUIRE_RUNTIME_STACK", False, cast=bool)
    )
    test_mode = bool(
        str(get_env("PYTEST_CURRENT_TEST", "", cast=str) or "").strip()
        or str(get_env("PYTEST_RUNNING", "", cast=str) or "").strip()
        or bool(get_env("TESTING", False, cast=bool))
    )
    fail_hard_startup = bool(require_runtime_stack and not test_mode and reason == "startup")
    target = _resolve_rl_model_path(model_path)
    if not enabled:
        RL_MODEL_PATH = target
        if RL_AGENT is not None:
            info_kv(
                logger,
                "RL_AGENT_DISABLED",
                extra={"reason": "USE_RL_AGENT_FALSE"},
            )
        RL_AGENT = None
        _RL_AGENT_SIGNATURE = None
        return False
    if target is None:
        warning_kv(
            logger,
            "RL_AGENT_PATH_MISSING",
            extra={"reason": reason},
        )
        if fail_hard_startup:
            raise RuntimeError("RL_AGENT_PATH_MISSING")
        return False
    governance_ok, governance_reason = _rl_runtime_governance_allows_load(
        target,
        test_mode=test_mode,
    )
    if not governance_ok and governance_reason == "sidecar_missing":
        bootstrap_sidecar = bool(
            get_env(
                "AI_TRADING_RL_RUNTIME_BOOTSTRAP_GOVERNANCE_SIDECAR",
                True,
                cast=bool,
            )
        )
        if bootstrap_sidecar:
            bootstrapped, bootstrap_reason = _bootstrap_missing_rl_governance_sidecar(target)
            if bootstrapped:
                info_kv(
                    logger,
                    "RL_AGENT_GOVERNANCE_SIDECAR_BOOTSTRAPPED",
                    extra={"model": str(target), "sidecar_path": str(_resolve_rl_governance_sidecar_path(target))},
                )
                governance_ok, governance_reason = _rl_runtime_governance_allows_load(
                    target,
                    test_mode=test_mode,
                )
            else:
                warning_kv(
                    logger,
                    "RL_AGENT_GOVERNANCE_SIDECAR_BOOTSTRAP_FAILED",
                    extra={
                        "model": str(target),
                        "reason": bootstrap_reason,
                        "sidecar_path": str(_resolve_rl_governance_sidecar_path(target)),
                    },
                )
    if not governance_ok:
        warning_kv(
            logger,
            "RL_AGENT_GOVERNANCE_BLOCKED",
            extra={
                "model": str(target),
                "reason": governance_reason,
                "sidecar_path": str(_resolve_rl_governance_sidecar_path(target)),
            },
        )
        if fail_hard_startup:
            raise RuntimeError("RL_AGENT_GOVERNANCE_BLOCKED")
        return False
    if RLTrader is None:
        warning_kv(
            logger,
            "RL_TRADER_UNAVAILABLE",
            extra={"hint": "ai_trading.rl_trading import failed"},
        )
        if fail_hard_startup:
            raise RuntimeError("RL_TRADER_UNAVAILABLE")
        return False
    target_sig = _rl_model_signature(target)
    if (
        not force
        and RL_AGENT is not None
        and RL_MODEL_PATH == target
        and _RL_AGENT_SIGNATURE == target_sig
    ):
        return True
    try:
        rl = RLTrader(target)
        rl.load()  # load PPO policy from zip path
    except COMMON_EXC as exc:  # noqa: BLE001
        warning_kv(
            logger,
            "RL_AGENT_INIT_FAILED",
            extra={"error": str(exc), "model": str(target)},
        )
        if fail_hard_startup:
            raise RuntimeError("RL_AGENT_INIT_FAILED") from exc
        return False
    RL_AGENT = rl
    RL_MODEL_PATH = target
    _RL_AGENT_SIGNATURE = target_sig
    info_kv(
        logger,
        "RL_AGENT_READY",
        extra={
            "model": str(target),
            "reason": reason,
            "reloaded": bool(force),
        },
    )
    return True


