def limits(*args, **kwargs):
    def decorator(func):
        def wrapped(*a, **k):
            try:
                from ratelimit import limits as _limits
            except ImportError:
                return func(*a, **k)

            return _limits(*args, **kwargs)(func)(*a, **k)

        return wrapped

    return decorator


def sleep_and_retry(func):
    def wrapped(*a, **k):
        try:
            from ratelimit import sleep_and_retry as _sr
        except ImportError:
            return func(*a, **k)

        result = _sr(func)(*a, **k)
        if a and result is a[0]:
            return func(*a, **k)
        return result

    return wrapped
