def _coerce_secret_value(value: Any) -> str | None:
    """Resolve callable/secret-like values into a plain string."""

    candidate = value
    if callable(candidate):
        try:
            candidate = candidate()
        except COMMON_EXC:
            logger.debug("ALPACA_SECRET_CALLABLE_FAILED", exc_info=True)
            return None
    if candidate in (None, ""):
        return None
    try:
        text = str(candidate).strip()
    except COMMON_EXC:
        return None
    return text or None


# Defer credential checks to runtime (avoid import-time crashes before .env loads)
def _resolve_alpaca_env():
    # AI-AGENT-REF: ensure .env is loaded before resolving Alpaca environment
    try:
        from ai_trading.env import ensure_dotenv_loaded
        ensure_dotenv_loaded()
    except COMMON_EXC:
        pass
    env_snapshot: Mapping[str, Any] = {}
    try:
        env_snapshot = config.merged_env_snapshot()
    except COMMON_EXC:
        env_snapshot = {}

    key = _coerce_secret_value(config.get_env("ALPACA_API_KEY"))
    if not key:
        key = _coerce_secret_value(
            config.get_env("ALPACA_API_KEY", None, resolve_aliases=False)
        )
    if not key:
        key = _coerce_secret_value(env_snapshot.get("ALPACA_API_KEY"))
    secret = _coerce_secret_value(config.get_env("ALPACA_SECRET_KEY"))
    if not secret:
        secret = _coerce_secret_value(
            config.get_env("ALPACA_SECRET_KEY", None, resolve_aliases=False)
        )
    if not secret:
        secret = _coerce_secret_value(env_snapshot.get("ALPACA_SECRET_KEY"))
    base_url = _coerce_secret_value(
        config.get_env(
            "ALPACA_TRADING_BASE_URL",
            "https://paper-api.alpaca.markets",
        )
    )
    if not base_url:
        base_url = _coerce_secret_value(
            config.get_env(
                "ALPACA_TRADING_BASE_URL",
                "https://paper-api.alpaca.markets",
                resolve_aliases=False,
            )
        )
    if not base_url:
        base_url = _coerce_secret_value(env_snapshot.get("ALPACA_TRADING_BASE_URL"))
    if not base_url:
        base_url = "https://paper-api.alpaca.markets"
    return key, secret, base_url


def _ensure_alpaca_env_or_raise():
    """
    Contract: always return a (key, secret, base_url) tuple.
    - In SHADOW_MODE, we do not raise; we still return whatever is currently resolved.
    - Outside SHADOW_MODE, if missing key/secret, raise with a clear message.
    """
    k, s, b = _resolve_alpaca_env()
    cached_key = _coerce_secret_value(globals().get("ALPACA_API_KEY"))
    cached_secret = _coerce_secret_value(globals().get("ALPACA_SECRET_KEY"))
    if not k and cached_key:
        k = cached_key
    if not s and cached_secret:
        s = cached_secret
    # Check for shadow mode
    shadow_mode = is_shadow_mode()
    pytest_running = str(get_env("PYTEST_RUNNING", "")).strip().lower() in {"1", "true", "yes", "on"}
    if shadow_mode:
        return k, s, b
    if not (k and s):
        logger.critical(
            "Alpaca credentials missing – aborting client initialization",
            extra={
                "has_key": bool(k),
                "has_secret": bool(s),
                "cached_has_key": bool(cached_key),
                "cached_has_secret": bool(cached_secret),
                "pytest_running": pytest_running,
            },
        )
        raise RuntimeError("Missing Alpaca API credentials")
    return k, s, b


def init_runtime_config():
    """Initialize runtime configuration and validate critical keys."""
    from ai_trading.config import get_settings

    cfg = get_settings()

    # Validate critical keys at runtime, not import time
    global ALPACA_API_KEY, ALPACA_SECRET_KEY, TRADING_MODE_ENV

    # Use the new credential resolution functions
    try:
        ALPACA_API_KEY, ALPACA_SECRET_KEY, _ = _ensure_alpaca_env_or_raise()
    except RuntimeError as e:
        if not getattr(CFG, "testing", False):  # Allow missing credentials in test mode
            raise e
        # AI-AGENT-REF: Use environment variables even in test mode to avoid hardcoded secrets
        ALPACA_API_KEY = str(get_env("TEST_ALPACA_API_KEY", "") or "")
        ALPACA_SECRET_KEY = str(get_env("TEST_ALPACA_SECRET_KEY", "") or "")

    TRADING_MODE_ENV = _normalize_runtime_trading_mode(
        getattr(cfg, "trading_mode", DEFAULT_TRADING_MODE)
    )

    if not callable(validate_alpaca_credentials):
        raise RuntimeError("validate_alpaca_credentials not found in config")

    logger.info(
        "Runtime config initialized",
        extra={
            "alpaca_key_set": bool(ALPACA_API_KEY and len(ALPACA_API_KEY) > 8),
            "trading_mode": TRADING_MODE_ENV,
        },
    )
    return cfg


