def load_hyperparams() -> dict:
    """Load hyperparameters from local overrides or packaged defaults."""
    for path in (BEST_HYPERPARAMS_FILE, HYPERPARAMS_FILE):
        if not os.path.exists(path):
            continue
        try:
            with open(path, encoding="utf-8") as f:
                payload = json.load(f)
            if isinstance(payload, dict):
                return payload
            return {}
        except (OSError, json.JSONDecodeError) as exc:
            logger.warning("Failed to load hyperparameters from %s: %s", path, exc)
            return {}
    try:
        from ai_trading.defaults import load_default_json

        for name in ("best_hyperparams.json", "hyperparams.json"):
            payload = load_default_json(name)
            if isinstance(payload, dict):
                logger.info("Loaded hyperparameters from packaged default %s", name)
                return payload
    except (ImportError, OSError, json.JSONDecodeError) as exc:
        logger.warning("Failed to load packaged hyperparameter defaults: %s", exc)
    logger.warning("Hyperparameter defaults unavailable; using empty defaults")
    return {}


def _fetch_universe_bars(
    symbols: list[str],
    timeframe: str,
    start: datetime | str,
    end: datetime | str,
    feed: str | None = None,
) -> dict[str, pd.DataFrame]:
    """Fetch bars using batch API with safe fallback."""  # AI-AGENT-REF
    out: Dict[str, pd.DataFrame] = {}
    missing: list[str] = list(symbols)
    try:
        batch = get_bars_batch(symbols, timeframe, start, end, feed=feed)
        if isinstance(batch, dict):
            missing = []
            for sym in symbols:
                df = batch.get(sym)
                if df is not None and not getattr(df, "empty", False):
                    out[sym] = df
                else:
                    missing.append(sym)
            if not missing:
                return out
    except COMMON_EXC:
        pass

    # Fallback to per-symbol requests with bounded concurrency.
    if not missing:
        return out

    settings = get_settings()
    max_workers = max(1, int(getattr(settings, "batch_fallback_workers", 4)))

    def _pull(sym: str) -> tuple[str, pd.DataFrame | None]:
        try:
            return sym, get_bars(sym, timeframe, start, end, feed=feed)
        except COMMON_EXC:
            return sym, None

    results: list[tuple[str, pd.DataFrame | None]] = []
    with ThreadPoolExecutor(
        max_workers=max_workers, thread_name_prefix="fallback-bars"
    ) as ex:
        futures = [ex.submit(_pull, s) for s in missing]
        for fut in as_completed(futures):
            results.append(fut.result())

    for sym, df in results:
        if df is not None and not getattr(df, "empty", False):
            out[sym] = df
    return out


def _fetch_universe_bars_chunked(
    symbols: list[str],
    timeframe: str,
    start: datetime | str,
    end: datetime | str,
    feed: str | None = None,
) -> dict[str, pd.DataFrame]:
    """
    Chunked batched fetch for universe bars with safe fallback.
    """
    if not symbols:
        return {}
    settings = get_settings()
    batch_size = max(1, int(getattr(settings, "pretrade_batch_size", 50)))
    out: dict[str, pd.DataFrame] = {}
    for i in range(0, len(symbols), batch_size):
        chunk = symbols[i : i + batch_size]
        out.update(_fetch_universe_bars(chunk, timeframe, start, end, feed))
    total_symbols = len(out)
    try:
        bars_loaded = sum(len(v) for v in out.values())
    except (TypeError, AttributeError):  # AI-AGENT-REF: bars summary fallback
        bars_loaded = 0
    first_symbol = next(iter(out.keys()), None)
    logger.info(
        "FETCH_SUMMARY",
        extra={
            "total_symbols": total_symbols,
            "bars_loaded": bars_loaded,
            "first_symbol": first_symbol,
        },
    )
    return out


