def _normalize_regime_name(raw_regime: Any) -> str:
    value = str(raw_regime or "").strip().lower()
    aliases = {
        "bull": "trending",
        "bear": "mean_reversion",
        "volatile": "high_volatility",
    }
    normalized = aliases.get(value, value)
    return normalized or "sideways"


