def _clip_delta_to_symbol_notional_cap(
    *,
    symbol: str,
    current_shares: int,
    delta_shares: int,
    price: float,
    max_symbol_notional: float,
) -> tuple[int, dict[str, Any] | None]:
    """Clamp delta shares so projected symbol notional does not worsen beyond cap.

    Returns ``(adjusted_delta, details)``. ``details`` is ``None`` when no
    adjustment is required.
    """

    if int(delta_shares) == 0:
        return 0, None
    if price <= 0 or max_symbol_notional <= 0:
        return int(delta_shares), None

    current_qty = int(current_shares)
    requested_delta = int(delta_shares)
    projected_qty = current_qty + requested_delta
    current_notional = abs(float(current_qty) * float(price))
    projected_notional = abs(float(projected_qty) * float(price))
    max_notional = float(max_symbol_notional)

    # Within cap or actively de-risking an already over-cap position.
    if projected_notional <= max_notional + 1e-9:
        return requested_delta, None
    if projected_notional <= current_notional + 1e-9:
        return requested_delta, None

    max_abs_shares = int(math.floor(max_notional / float(price) + 1e-9))
    max_abs_shares = max(0, max_abs_shares)
    if max_abs_shares <= 0:
        adjusted_delta = 0
    elif abs(current_qty) > max_abs_shares:
        # Already above cap: allow only de-risking moves.
        adjusted_delta = 0
    else:
        projected_sign = 1 if projected_qty > 0 else -1
        clamped_target_qty = projected_sign * max_abs_shares
        adjusted_delta = clamped_target_qty - current_qty
        # Never flip direction relative to the original intent.
        if requested_delta > 0 and adjusted_delta < 0:
            adjusted_delta = 0
        if requested_delta < 0 and adjusted_delta > 0:
            adjusted_delta = 0
        if abs(adjusted_delta) > abs(requested_delta):
            adjusted_delta = requested_delta

    if adjusted_delta == requested_delta:
        return requested_delta, None

    adjusted_projected_qty = current_qty + int(adjusted_delta)
    adjusted_projected_notional = abs(float(adjusted_projected_qty) * float(price))
    details = {
        "symbol": str(symbol or "").upper(),
        "price": float(price),
        "max_symbol_notional": max_notional,
        "current_shares": int(current_qty),
        "current_notional": float(current_notional),
        "requested_delta_shares": int(requested_delta),
        "requested_projected_shares": int(projected_qty),
        "requested_projected_notional": float(projected_notional),
        "adjusted_delta_shares": int(adjusted_delta),
        "adjusted_projected_shares": int(adjusted_projected_qty),
        "adjusted_projected_notional": float(adjusted_projected_notional),
    }
    return int(adjusted_delta), details


def _clip_sell_qty_to_available_position(
    *,
    symbol: str,
    current_shares: int,
    requested_qty: int,
    exec_engine: Any | None,
) -> tuple[int, dict[str, Any] | None]:
    """Clip sell quantity to currently available long shares before submit."""

    requested_qty_int = max(int(requested_qty), 0)
    current_qty_int = int(current_shares)
    if requested_qty_int <= 0 or current_qty_int <= 0:
        return requested_qty_int, None

    open_sell_qty = 0.0
    if exec_engine is not None and hasattr(exec_engine, "open_order_totals"):
        try:
            _, open_sell_qty_raw = exec_engine.open_order_totals(symbol)
            open_sell_qty = max(float(_safe_float(open_sell_qty_raw) or 0.0), 0.0)
        except BOT_ENGINE_FALLBACK_EXC:
            open_sell_qty = 0.0
    reserved_shares = int(math.ceil(open_sell_qty - 1e-9))
    available_qty = max(current_qty_int - max(reserved_shares, 0), 0)
    if requested_qty_int <= available_qty:
        return requested_qty_int, None

    adjusted_qty = int(max(available_qty, 0))
    context = {
        "symbol": str(symbol or "").upper(),
        "requested_qty": int(requested_qty_int),
        "available_qty": int(available_qty),
        "current_shares": int(current_qty_int),
        "open_sell_qty": float(open_sell_qty),
        "reserved_shares": int(max(reserved_shares, 0)),
        "adjusted_qty": int(adjusted_qty),
    }
    logger.warning("PRE_SUBMIT_SELL_QTY_CLIPPED_AVAILABLE_POSITION", extra=context)
    return adjusted_qty, context


# --------------------------------------------------------------------------- #
# Buying power enforcement helpers


def _safe_float(value: Any | None) -> float | None:
    """Return a finite float or ``None`` when conversion fails."""

    if value in (None, "", float("inf"), float("-inf")):
        return None
    try:
        candidate = float(value)
    except (TypeError, ValueError):
        return None
    return candidate if math.isfinite(candidate) else None


def _safe_bool(value: Any) -> bool:
    """Return a defensive boolean conversion."""

    if isinstance(value, bool):
        return value
    if value in (None, ""):
        return False
    if isinstance(value, (int, float, np.floating)):
        return bool(value)
    try:
        normalized = str(value).strip().lower()
    except (AttributeError, TypeError, ValueError):
        return False
    if not normalized:
        return False
    return normalized in {"1", "true", "yes", "y", "on", "enabled"}


def _entry_requires_account_snapshot(ctx: Any) -> bool:
    execution_mode = str(
        getattr(ctx, "execution_mode", get_env("EXECUTION_MODE", "paper", cast=str))
        or "paper"
    ).strip().lower()
    return execution_mode == "live"


# ─── K. SIZING & EXECUTION HELPERS ─────────────────────────────────────────────


def scaled_atr_stop(
    entry_price: float,
    atr: float,
    now: datetime,
    market_open: datetime,
    market_close: datetime,
    max_factor: float = 2.0,
    min_factor: float = 0.5,
) -> tuple[float, float]:
    """Calculate scaled ATR stop-loss and take-profit with comprehensive validation."""
    try:
        # AI-AGENT-REF: Add comprehensive input validation for stop-loss calculation

        # Validate entry price
        if not isinstance(entry_price, int | float) or entry_price <= 0:
            logger.error("Invalid entry price for ATR stop: %s", entry_price)
            return (
                entry_price * 0.95,
                entry_price * 1.05,
            )  # Return conservative defaults

        # Validate ATR
        if not isinstance(atr, int | float) or atr < 0:
            logger.error("Invalid ATR for stop calculation: %s", atr)
            return entry_price * 0.95, entry_price * 1.05

        if atr == 0:
            logger.warning("ATR is zero, using 1% stop/take levels")
            return entry_price * 0.99, entry_price * 1.01

        # Validate datetime inputs
        if not all(isinstance(dt, datetime) for dt in [now, market_open, market_close]):
            logger.error("Invalid datetime inputs for ATR stop calculation")
            return entry_price * 0.95, entry_price * 1.05

        # Validate market times make sense
        if market_close <= market_open:
            logger.error(
                "Invalid market times: close=%s <= open=%s", market_close, market_open
            )
            return entry_price * 0.95, entry_price * 1.05

        # Validate factors
        if not isinstance(max_factor, int | float) or max_factor <= 0:
            logger.warning("Invalid max_factor %s, using default 2.0", max_factor)
            max_factor = 2.0

        if not isinstance(min_factor, int | float) or min_factor < 0:
            logger.warning("Invalid min_factor %s, using default 0.5", min_factor)
            min_factor = 0.5

        if min_factor > max_factor:
            logger.warning(
                "min_factor %s > max_factor %s, swapping", min_factor, max_factor
            )
            min_factor, max_factor = max_factor, min_factor

        # Calculate time-based scaling factor
        total = (market_close - market_open).total_seconds()
        elapsed = (now - market_open).total_seconds()

        # Handle edge cases
        if total <= 0:
            logger.warning("Invalid market session duration: %s seconds", total)
            α = 0.5  # Use middle factor
        else:
            α = max(0, min(1, 1 - elapsed / total))

        factor = min_factor + α * (max_factor - min_factor)

        # Validate factor is reasonable
        if factor <= 0 or factor > 10:  # Sanity check - no more than 10x ATR
            logger.warning("Calculated factor %s out of bounds, capping", factor)
            factor = max(0.1, min(factor, 10.0))

        stop = entry_price - factor * atr
        take = entry_price + factor * atr

        # Validate calculated levels are reasonable
        if stop < 0:
            logger.warning("Calculated stop price %s is negative, adjusting", stop)
            stop = entry_price * 0.5  # Minimum 50% stop

        if take <= entry_price:
            logger.warning(
                "Calculated take profit %s <= entry price %s, adjusting",
                take,
                entry_price,
            )
            take = entry_price * 1.1  # Minimum 10% profit target

        # Ensure stop is below entry and take is above entry
        if stop >= entry_price:
            logger.warning(
                "Stop price %s >= entry price %s, adjusting", stop, entry_price
            )
            stop = entry_price * 0.95

        if take <= entry_price:
            logger.warning(
                "Take profit %s <= entry price %s, adjusting", take, entry_price
            )
            take = entry_price * 1.05

        logger.debug(
            "ATR stop calculation: entry=%s, atr=%s, factor=%s, stop=%s, take=%s",
            entry_price,
            atr,
            factor,
            stop,
            take,
        )

        return stop, take

    except (
        FileNotFoundError,
        PermissionError,
        IsADirectoryError,
        JSONDecodeError,
        ValueError,
        KeyError,
        TypeError,
        OSError,
    ) as e:  # AI-AGENT-REF: narrow exception
        logger.error("Error in ATR stop calculation: %s", e)
        # Return conservative defaults on error
        return entry_price * 0.95, entry_price * 1.05


def submit_order(
    ctx: BotContext,
    symbol: str,
    qty: int,
    side: str,
    *,
    price: float | None = None,
    **exec_kwargs: Any,
) -> Any | None:
    """Submit once through the engine, which owns broker retry and reconciliation."""

    try:
        return _submit_order_service(
            ctx,
            symbol,
            qty,
            side,
            price=price,
            **exec_kwargs,
        )
    except (APIError, TimeoutError, ConnectionError, AlpacaOrderHTTPError) as e:
        logger.error(
            "BROKER_OP_FAILED",
            extra={
                "symbol": symbol,
                "qty": qty,
                "side": side,
                "cause": e.__class__.__name__,
                "detail": str(e),
            },
        )
        raise


def poll_order_fill_status(ctx: BotContext, order_id: str, timeout: int = 120) -> None:
    """Poll Alpaca for order fill status until it is no longer open.

    Uses monotonic time to avoid interference from time-freezing utilities
    (e.g., freezegun). Sleeps in short intervals so small timeouts work.
    """
    deadline = monotonic_time() + float(timeout)
    interval = 0.2 if timeout <= 1 else 1.0
    # Hard cap iterations to avoid hangs even if time is monkeypatched
    max_iters = int(max(1, float(timeout) / float(interval))) + 2
    _iter = 0
    while monotonic_time() < deadline and _iter < max_iters:
        try:
            od = ctx.api.get_order(order_id)
            status = getattr(od, "status", "")
            filled = getattr(od, "filled_qty", 0) or 0
            if status not in {"new", "accepted", "partially_filled"}:
                logger.info(
                    "ORDER_FINAL_STATUS",
                    extra={
                        "order_id": order_id,
                        "status": status,
                        "filled_qty": filled,
                    },
                )
                return
        except (
            FileNotFoundError,
            PermissionError,
            IsADirectoryError,
            JSONDecodeError,
            ValueError,
            KeyError,
            TypeError,
            OSError,
        ) as e:  # AI-AGENT-REF: narrow exception
            logger.warning(f"[poll_order_fill_status] failed for {order_id}: {e}")
            return
        remaining = max(0.0, deadline - monotonic_time())
        if remaining <= 0:
            break
        pytime.sleep(min(interval, remaining))
        _iter += 1


