def _coerce_quote_timestamp(value: Any) -> datetime | None:
    if value is None:
        return None
    if isinstance(value, datetime):
        return value if value.tzinfo else value.replace(tzinfo=UTC)
    if isinstance(value, (int, float)):
        try:
            return datetime.fromtimestamp(float(value), tz=UTC)
        except (OSError, OverflowError, ValueError):
            return None
    try:
        dt_val = ensure_datetime(value)
    except COMMON_EXC:
        return None
    if dt_val.tzinfo is None:
        dt_val = dt_val.replace(tzinfo=UTC)
    return dt_val.astimezone(UTC)


def _extract_quote_timestamp(payload: Any) -> datetime | None:
    queue: list[Any] = [payload]
    seen: set[int] = set()
    timestamp_keys = ("timestamp", "time", "ts", "t", "updated_at")
    while queue:
        candidate = queue.pop()
        ident = id(candidate)
        if ident in seen:
            continue
        seen.add(ident)
        if candidate is None:
            continue
        for key in timestamp_keys:
            source = None
            if hasattr(candidate, key):
                try:
                    source = getattr(candidate, key)
                except BOT_ENGINE_FALLBACK_EXC:
                    source = None
            if source is None and isinstance(candidate, Mapping):
                source = candidate.get(key)
            if source is not None:
                ts = _coerce_quote_timestamp(source)
                if ts is not None:
                    return ts
        children: list[Any] = []
        if isinstance(candidate, Mapping):
            children.extend(candidate.values())
        elif isinstance(candidate, (list, tuple, set, frozenset)):
            children.extend(candidate)
        else:
            attrs = getattr(candidate, "__dict__", None)
            if isinstance(attrs, Mapping):
                children.extend(attrs.values())
        for child in children:
            if child is None:
                continue
            if isinstance(child, (Mapping, list, tuple, set, frozenset)) or hasattr(child, "__dict__"):
                queue.append(child)
    return None


_TRANSIENT_FALLBACK_REASONS = frozenset(
    {
        "quote_source_unavailable",
        "quote_fetch_error",
        "quote_timestamp_missing",
    }
)


_MAX_PRICE_DEVIATION = 0.15


def _safe_mode_failsoft_enabled() -> bool:
    try:
        cfg = get_trading_config()
    except COMMON_EXC:
        return True
    return bool(getattr(cfg, "safe_mode_failsoft", True))


def _provider_backup_available(provider_state: Mapping[str, Any] | None) -> bool:
    if not isinstance(provider_state, MappingABC):
        return False
    if bool(provider_state.get("using_backup")):
        return True
    primary = provider_state.get("primary")
    active = provider_state.get("active")
    try:
        if primary and active and str(primary).strip().lower() != str(active).strip().lower():
            return True
    except BOT_ENGINE_FALLBACK_EXC:
        logger.debug("PROVIDER_BACKUP_AVAILABILITY_COMPARE_FAILED", exc_info=True)
    return _minute_fallback_active(provider_state)


def _failsoft_mode_active(provider_state: Mapping[str, Any] | None = None) -> bool:
    if not _safe_mode_failsoft_enabled():
        return False
    safe_mode_flag = provider_monitor.is_safe_mode_active()
    safe_mode_soft = False
    degraded_marker = getattr(provider_monitor, "safe_mode_degraded_only", None)
    if callable(degraded_marker) and safe_mode_flag:
        try:
            safe_mode_soft = bool(degraded_marker())
        except BOT_ENGINE_FALLBACK_EXC:
            safe_mode_soft = False
    if provider_state is None:
        try:
            provider_state = runtime_state.observe_data_provider_state()
        except BOT_ENGINE_FALLBACK_EXC:
            provider_state = {}
    backup_ready = safe_mode_flag and _provider_backup_available(provider_state)
    return safe_mode_soft or backup_ready


def _safe_mode_blocks_trading() -> bool:
    """Return ``True`` when the current degraded policy requires blocking trades."""

    try:
        cfg = get_trading_config()
    except COMMON_EXC:
        return True
    mode = str(getattr(cfg, "degraded_feed_mode", "block") or "block").strip().lower()
    if mode not in {"block", "widen", "hard_block"}:
        mode = "block"
    if mode == "hard_block":
        return True
    failsoft_enabled = _safe_mode_failsoft_enabled()
    if not failsoft_enabled:
        return True
    if failsoft_enabled:
        degraded_marker = getattr(provider_monitor, "safe_mode_degraded_only", None)
        if callable(degraded_marker):
            try:
                if bool(degraded_marker()):
                    return False
            except BOT_ENGINE_FALLBACK_EXC:
                logger.debug("SAFE_MODE_DEGRADED_MARKER_EVAL_FAILED", exc_info=True)
    if bool(getattr(cfg, "execution_market_on_degraded", False)):
        return False
    return mode == "block"


def _current_qty(ctx, symbol: str) -> int:
    symbol_key = str(symbol).upper()
    position_map = getattr(ctx, "position_map", None)
    if not isinstance(position_map, MappingABC):
        position_map = None

    # Fallback to broker positions when the context has not cached a position map yet.
    if position_map is None:
        fresh_map: dict[str, Any] = {}
        api_obj = getattr(ctx, "api", None)
        get_all_positions = getattr(api_obj, "get_all_positions", None)
        list_positions = getattr(api_obj, "list_positions", None)
        positions_fn = get_all_positions if callable(get_all_positions) else list_positions
        if callable(positions_fn):
            try:
                broker_positions = positions_fn()
            except COMMON_EXC:
                broker_positions = ()
            for pos_entry in broker_positions or ():
                raw_symbol = getattr(pos_entry, "symbol", None)
                if raw_symbol in (None, "") and isinstance(pos_entry, MappingABC):
                    raw_symbol = pos_entry.get("symbol")
                if raw_symbol in (None, ""):
                    continue
                try:
                    key = str(raw_symbol).strip().upper()
                except BOT_ENGINE_FALLBACK_EXC:
                    continue
                if key:
                    fresh_map[key] = pos_entry
        position_map = fresh_map
        try:
            setattr(ctx, "position_map", fresh_map)
        except BOT_ENGINE_FALLBACK_EXC:
            logger.debug("CTX_POSITION_MAP_ASSIGN_FAILED", exc_info=True)

    pos = None
    if isinstance(position_map, MappingABC):
        pos = position_map.get(symbol_key)
        if pos is None:
            pos = position_map.get(symbol)
    if pos is None:
        return 0
    qty = getattr(pos, "qty", None)
    if qty in (None, "") and isinstance(pos, MappingABC):
        qty = pos.get("qty")
        if qty in (None, ""):
            qty = pos.get("quantity")
    if qty in (None, ""):
        return 0
    try:
        parsed_qty = int(float(qty))
    except (TypeError, ValueError):
        return 0
    if parsed_qty < 0:
        return parsed_qty
    side = getattr(pos, "side", None)
    if side in (None, "") and isinstance(pos, MappingABC):
        side = pos.get("side")
    try:
        side_token = str(getattr(side, "value", side) or "").strip().lower()
    except BOT_ENGINE_FALLBACK_EXC:
        side_token = ""
    if side_token in {"short", "sell", "sell_short", "sellshort", "sell-short"}:
        return -abs(parsed_qty)
    return parsed_qty


def _record_broker_sync_metrics(state: BotState, snapshot: "BrokerSyncResult" | None) -> None:
    """Update execution metrics from *snapshot* and emit structured log."""

    open_orders_count = 0
    positions_count = 0
    snapshot_fresh = bool(snapshot is not None and getattr(snapshot, "fresh", True))
    open_orders_fresh = bool(
        snapshot is not None
        and getattr(snapshot, "open_orders_fresh", snapshot_fresh)
    )
    positions_fresh = bool(
        snapshot is not None
        and getattr(snapshot, "positions_fresh", snapshot_fresh)
    )
    failed_components = tuple(
        getattr(snapshot, "failed_components", ()) or ()
    ) if snapshot is not None else ("broker_state",)
    if snapshot is not None:
        try:
            open_orders_count = len(getattr(snapshot, "open_orders", ()) or ())
        except BOT_ENGINE_FALLBACK_EXC:
            open_orders_count = 0
        try:
            positions_count = len(getattr(snapshot, "positions", ()) or ())
        except BOT_ENGINE_FALLBACK_EXC:
            positions_count = 0

    metrics = getattr(state, "execution_metrics", None)
    if metrics is not None:
        try:
            metrics.open_orders = int(open_orders_count)
        except BOT_ENGINE_FALLBACK_EXC:
            metrics.open_orders = open_orders_count
        try:
            metrics.positions = int(positions_count)
        except BOT_ENGINE_FALLBACK_EXC:
            metrics.positions = positions_count

    try:
        runtime_state.update_broker_status(
            connected=snapshot_fresh,
            fresh=snapshot_fresh,
            open_orders_fresh=open_orders_fresh,
            positions_fresh=positions_fresh,
            last_error=(
                None
                if snapshot_fresh
                else str(
                    getattr(snapshot, "last_error", None)
                    or "broker_sync_unavailable"
                )
            ),
            failed_components=failed_components,
            consecutive_failures=int(
                getattr(snapshot, "consecutive_failures", 0) or 0
            ) if snapshot is not None else 1,
            stale_age_s=(
                getattr(snapshot, "stale_age_s", None)
                if snapshot is not None
                else None
            ),
            status="connected" if snapshot_fresh else "degraded",
            open_orders_count=int(open_orders_count),
            positions_count=int(positions_count),
        )
    except BOT_ENGINE_FALLBACK_EXC:
        logger.debug("BROKER_SYNC_RUNTIME_STATE_UPDATE_FAILED", exc_info=True)

    logger.info(
        "BROKER_SYNC",
        extra={
            "open_orders": open_orders_count,
            "positions": positions_count,
            "fresh": snapshot_fresh,
            "failed_components": list(failed_components),
        },
    )


