def _average_reward(n: int = 20) -> float:
    if not os.path.exists(REWARD_LOG_FILE):
        return 0.0
    df = pd.read_csv(
        REWARD_LOG_FILE,
        on_bad_lines="skip",
        engine="python",
        usecols=["reward"],
    ).tail(n)
    if df.empty:
        if _is_market_open_now():
            logger.debug(
                "Loaded DataFrame from %s is empty after parsing/fallback",
                REWARD_LOG_FILE,
            )
        else:
            logger.debug(
                "Loaded DataFrame from %s is empty (market closed)",
                REWARD_LOG_FILE,
            )
    if df.empty or "reward" not in df.columns:
        return 0.0
    return float(df["reward"].mean())


def _current_drawdown() -> float:
    try:
        with open(PEAK_EQUITY_FILE) as pf:
            peak = float(pf.read().strip() or 0)
        with open(EQUITY_FILE) as ef:
            eq = float(ef.read().strip() or 0)
    except PermissionError:
        _log_peak_equity_permission()
        return 0.0
    except (
        FileNotFoundError,
        IsADirectoryError,
        JSONDecodeError,
        ValueError,
        KeyError,
        TypeError,
        OSError,
    ):  # AI-AGENT-REF: narrow exception
        return 0.0
    if peak <= 0:
        return 0.0
    return max(0.0, (peak - eq) / peak)


def _adaptive_mode_switch_enabled(cfg: TradingConfig) -> tuple[bool, str]:
    """Return whether adaptive mode switching is enabled and why."""

    if not bool(getattr(cfg, "trading_mode_adaptive_enabled", False)):
        return False, "adaptive_disabled"
    precedence_policy = str(getattr(cfg, "trading_mode_precedence", "strict_mode") or "strict_mode").strip().lower()
    if precedence_policy == "env_wins":
        if get_env("AI_TRADING_TRADING_MODE") not in (None, ""):
            return False, "env_wins_locked"
    return True, "enabled"


def update_bot_mode(state: BotState) -> None:
    try:
        cfg = _get_trading_config()
        enabled, gate_reason = _adaptive_mode_switch_enabled(cfg)
        if not enabled:
            logger.debug("MODE_SWITCH_SKIPPED", extra={"reason": gate_reason})
            return

        avg_r = _average_reward()
        dd = _current_drawdown()
        if dd > 0.05 or avg_r < -0.01:
            new_mode = "conservative"
        else:
            new_mode = "balanced"

        current_mode = str(getattr(state.mode_obj, "mode", DEFAULT_TRADING_MODE)).lower()
        if new_mode == current_mode:
            return

        state.mode_obj = BotMode(new_mode)
        mode_obj = cast(Any, state.mode_obj)
        params.update(mode_obj.get_config())
        runtime_ctx = globals().get("ctx")
        if runtime_ctx is not None and hasattr(runtime_ctx, "kelly_fraction"):
            try:
                runtime_ctx.kelly_fraction = float(params.get("KELLY_FRACTION", runtime_ctx.kelly_fraction))
            except (TypeError, ValueError):
                pass
        logger.info(
            "MODE_SWITCH",
            extra={
                "previous_mode": current_mode,
                "new_mode": new_mode,
                "avg_reward": avg_r,
                "drawdown": dd,
                "regime": RECORDED_MARKET_REGIME_LABEL,
                "precedence_policy": str(getattr(cfg, "trading_mode_precedence", "strict_mode")),
            },
        )
    except (
        FileNotFoundError,
        PermissionError,
        IsADirectoryError,
        JSONDecodeError,
        ValueError,
        KeyError,
        TypeError,
        OSError,
    ) as e:  # AI-AGENT-REF: narrow exception
        logger.exception(f"update_bot_mode failed: {e}")


def adaptive_risk_scaling(ctx: BotContext) -> None:
    """Adjust risk parameters based on volatility, rewards and drawdown."""
    try:
        vol_raw = _VOL_STATS.get("mean", 0.0)
        spy_atr_raw = _VOL_STATS.get("last", 0.0)
        vol = float(vol_raw) if isinstance(vol_raw, (int, float)) else 0.0
        spy_atr = float(spy_atr_raw) if isinstance(spy_atr_raw, (int, float)) else 0.0
        avg_r = _average_reward(30)
        dd = _current_drawdown()
        try:
            equity = float(ctx.api.get_account().equity)
        except (
            FileNotFoundError,
            PermissionError,
            IsADirectoryError,
            JSONDecodeError,
            ValueError,
            KeyError,
            TypeError,
            OSError,
        ):  # AI-AGENT-REF: narrow exception
            equity = 0.0
        update_if_present(ctx, equity)
        params["get_capital_cap()"] = ctx.params["get_capital_cap()"]
        frac = params.get("KELLY_FRACTION", 0.6)
        if spy_atr and vol and spy_atr > vol * 1.5:
            frac *= 0.5
        if avg_r < -0.02:
            frac *= 0.7
        if dd > 0.1:
            frac *= 0.5
        ctx.kelly_fraction = round(max(0.2, min(frac, 1.0)), 2)
        params["get_capital_cap()"] = round(
            max(0.02, min(0.1, params.get("get_capital_cap()", 0.25) * (1 - dd))), 3
        )
        logger.info(
            "RISK_SCALED",
            extra={
                "kelly_fraction": ctx.kelly_fraction,
                "dd": dd,
                "atr": spy_atr,
                "avg_reward": avg_r,
            },
        )
    except (
        FileNotFoundError,
        PermissionError,
        IsADirectoryError,
        JSONDecodeError,
        ValueError,
        KeyError,
        TypeError,
        OSError,
    ) as e:  # AI-AGENT-REF: narrow exception
        logger.exception(f"adaptive_risk_scaling failed: {e}")


def check_disaster_halt() -> None:
    try:
        dd = _current_drawdown()
        if dd >= get_disaster_dd_limit():
            set_halt_flag(f"DISASTER_DRAW_DOWN_{dd:.2%}")
            logger.error("DISASTER_HALT_TRIGGERED", extra={"drawdown": dd})
    except (
        FileNotFoundError,
        PermissionError,
        IsADirectoryError,
        JSONDecodeError,
        ValueError,
        KeyError,
        TypeError,
        OSError,
    ) as e:  # AI-AGENT-REF: narrow exception
        logger.exception(f"check_disaster_halt failed: {e}")


# retrain_meta_learner is imported above if available


def _resolve_meta_retrain_trade_log_path() -> str | None:
    """Resolve meta-learning retrain source with optional canonical enforcement."""

    enforce_fill_derived = bool(
        get_env("AI_TRADING_META_CANONICAL_FILL_DERIVED_ONLY", False, cast=bool)
    )
    if not enforce_fill_derived:
        return str(TRADE_LOG_FILE)

    source_raw = str(
        get_env(
            "AI_TRADING_META_FILL_DERIVED_CSV_PATH",
            "runtime/meta_learning_fill_derived.csv",
            cast=str,
        )
        or "runtime/meta_learning_fill_derived.csv"
    ).strip()
    source_path = resolve_runtime_artifact_path(
        source_raw,
        default_relative="runtime/meta_learning_fill_derived.csv",
    )
    require_existing = bool(
        get_env("AI_TRADING_META_CANONICAL_SOURCE_REQUIRE_EXISTING", True, cast=bool)
    )
    if require_existing and not source_path.exists():
        logger.error(
            "META_RETRAIN_SOURCE_MISSING",
            extra={
                "source_mode": "canonical_fill_derived",
                "trade_log_path": str(source_path),
                "requested_path": source_raw,
            },
        )
        return None
    logger.info(
        "META_RETRAIN_SOURCE_SELECTED",
        extra={
            "source_mode": "canonical_fill_derived",
            "trade_log_path": str(source_path),
        },
    )
    return str(source_path)


def _learning_readiness_fail_hard_enabled() -> bool:
    return bool(get_env("AI_TRADING_LEARNING_READINESS_FAIL_HARD", False, cast=bool))


def _mark_learning_readiness_block(
    state: BotState,
    *,
    reason: str,
    details: Mapping[str, Any],
) -> None:
    payload = {"reason": reason, **dict(details)}
    logger.warning("LEARNING_READINESS_BLOCKED", extra=payload)
    try:
        from ai_trading.monitoring.alerts import emit_runtime_alert

        emit_runtime_alert(
            "ALERT_LEARNING_READINESS_BLOCKED",
            severity="warning",
            details=payload,
        )
    except BOT_ENGINE_FALLBACK_EXC:
        logger.debug("LEARNING_READINESS_ALERT_EMIT_FAILED", exc_info=True)
    if _learning_readiness_fail_hard_enabled():
        state.halt_trading = True
        state.halt_reason = reason


def _resolve_runtime_sleeve_whitelist() -> set[str]:
    raw = str(get_env("AI_TRADING_RUNTIME_SLEEVE_WHITELIST", "") or "").strip()
    if not raw:
        return set()
    parsed = [token.strip() for token in raw.split(",") if token and token.strip()]
    if not parsed:
        return set()
    max_active = max(0, int(get_env("AI_TRADING_RUNTIME_SLEEVE_MAX_ACTIVE", 0, cast=int)))
    if max_active > 0:
        parsed = parsed[:max_active]
    return {value for value in parsed}


def load_or_retrain_daily(ctx: BotContext) -> Any:
    """
    1. Check RETRAIN_MARKER_FILE for last retrain date (YYYY-MM-DD).
    2. If missing or older than today, call retrain_meta_learner(ctx, symbols) and update marker.
    3. Then load the (new) model from MODEL_PATH.
    """
    today_str = (
        datetime.now(UTC).astimezone(ZoneInfo("America/New_York")).strftime("%Y-%m-%d")
    )
    marker = RETRAIN_MARKER_FILE

    execution_mode = _runtime_execution_mode()
    allow_paper_train = bool(get_env("AI_TRADING_ALLOW_PAPER_TRAIN", "0", cast=bool))
    auto_train_allowed = _auto_train_allowed(
        execution_mode,
        allow_paper_train=allow_paper_train,
    )

    need_to_retrain = True
    if CFG.disable_daily_retrain:
        logger.info("Daily retraining disabled via DISABLE_DAILY_RETRAIN")
        need_to_retrain = False
    if os.path.isfile(marker):
        with open(marker) as f:
            last_date = f.read().strip()
        if last_date == today_str:
            need_to_retrain = False

    model_missing = not MODEL_PATH or not os.path.exists(MODEL_PATH)
    if model_missing:
        logger.warning(
            "MODEL_PATH missing; forcing initial retrain.",
            extra={"path": MODEL_PATH or ""},
        )
        if execution_mode == "live":
            logger.error(
                "MODEL_VERIFICATION_FAILED",
                extra={
                    "reason_code": "MODEL_FILE_MISSING",
                    "execution_mode": execution_mode,
                    "model_path": MODEL_PATH or "",
                },
            )
            raise RuntimeError("MODEL_VERIFICATION_FAILED: MODEL_FILE_MISSING")
        if auto_train_allowed:
            need_to_retrain = True  # AI-AGENT-REF: guard for missing model path
        else:
            raise RuntimeError(
                "Auto-train blocked: set EXECUTION_MODE=paper and AI_TRADING_ALLOW_PAPER_TRAIN=1"
            )

    if need_to_retrain and not auto_train_allowed:
        logger.info(
            "AUTO_TRAIN_BLOCKED",
            extra={
                "execution_mode": execution_mode,
                "allow_paper_train": allow_paper_train,
            },
        )
        need_to_retrain = False

    from ai_trading.config.research_policy import training_block_reason

    block_reason = training_block_reason()
    if block_reason:
        logger.info("DAILY_TRAINING_SKIPPED", extra={"reason": block_reason})
        need_to_retrain = False
    if need_to_retrain:
        if not callable(globals().get("retrain_meta_learner")):
            logger.warning(
                "Daily retraining requested, but retrain_meta_learner is unavailable."
            )
        else:
            if not meta_lock.acquire(blocking=False):
                logger.warning("METALEARN_SKIPPED_LOCKED")
            else:
                try:
                    symbols = load_tickers(TICKERS_FILE)
                    logger.info(
                        f"RETRAINING START for {today_str} on {len(symbols)} tickers"
                    )
                    valid_symbols = []
                    for symbol in symbols:
                        try:
                            df_min = fetch_minute_df_safe(symbol)
                        except DataFetchError:
                            logger.info(
                                f"{symbol} returned no minute data; skipping symbol."
                            )
                            continue
                        if df_min is None or df_min.empty:
                            logger.info(
                                f"{symbol} returned no minute data; skipping symbol."
                            )
                            continue
                        valid_symbols.append(symbol)
                    if not valid_symbols:
                        logger.warning(
                            "No symbols returned valid minute data; skipping retraining entirely."
                        )
                    else:
                        force_train = (not MODEL_PATH) or (
                            not os.path.exists(MODEL_PATH)
                        )  # AI-AGENT-REF: guard for missing model path
                        if is_market_open():
                            from ai_trading.meta_learning import (
                                retrain_meta_learner,  # AI-AGENT-REF: lazy import
                            )

                            meta_trade_log = _resolve_meta_retrain_trade_log_path()
                            if not meta_trade_log:
                                success = False
                                logger.warning("META_RETRAIN_SKIPPED_SOURCE_UNAVAILABLE")
                            else:
                                success = retrain_meta_learner(
                                    trade_log_path=meta_trade_log,
                                    model_path=MODEL_PATH or "meta_model.joblib",
                                )
                        else:
                            logger.info(
                                "[retrain_meta_learner] Outside market hours; skipping"
                            )
                            success = False
                        if success:
                            try:
                                with open(marker, "w") as f:
                                    f.write(today_str)
                            except (
                                FileNotFoundError,
                                PermissionError,
                                IsADirectoryError,
                                JSONDecodeError,
                                ValueError,
                                KeyError,
                                TypeError,
                                OSError,
                            ) as e:  # AI-AGENT-REF: narrow exception
                                logger.warning(
                                    f"Failed to write retrain marker file: {e}"
                                )
                        else:
                            logger.warning(
                                "Retraining failed; continuing with existing model."
                            )
                finally:
                    meta_lock.release()

    df_train = _get_daily_df_for_feed_role(
        ctx,
        REGIME_SYMBOLS[0],
        feed_role=_resolve_model_data_feed_role(),
    )
    if df_train is not None and not df_train.empty:
        X_train = (
            df_train[["open", "high", "low", "close", "volume"]]
            .astype(float)
            .iloc[:-1]
            .values
        )
        y_train = (
            df_train["close"]
            .pct_change(fill_method=None)
            .shift(-1)
            .fillna(0)
            .values[:-1]
        )
        mp = _import_model_pipeline()
        with model_lock:
            try:
                if len(X_train) == 0:
                    logger.warning("DAILY_MODEL_TRAIN_SKIPPED_EMPTY")
                else:
                    mp.fit(X_train, y_train)
                    mse = float(np.mean((mp.predict(X_train) - y_train) ** 2))
                    logger.info("TRAIN_METRIC", extra={"mse": mse})
            except (
                FileNotFoundError,
                PermissionError,
                IsADirectoryError,
                JSONDecodeError,
                ValueError,
                KeyError,
                TypeError,
                OSError,
            ) as e:  # AI-AGENT-REF: narrow exception
                logger.error(f"Daily retrain failed: {e}")

        date_str = datetime.now(UTC).strftime("%Y%m%d_%H%M")
        os.makedirs("models", exist_ok=True)
        path = f"models/sgd_{date_str}.pkl"
        atomic_joblib_dump(mp, path)
        logger.info(f"Model checkpoint saved: {path}")

        for model_file in os.listdir("models"):
            if model_file.endswith(".pkl"):
                dt = datetime.strptime(model_file.split("_")[1].split(".")[0], "%Y%m%d").replace(
                    tzinfo=UTC
                )
                if datetime.now(UTC) - dt > timedelta(days=30):
                    os.remove(os.path.join("models", model_file))

        batch_mse = float(np.mean((mp.predict(X_train) - y_train) ** 2))
        _get_metrics_logger().log_metrics(  # AI-AGENT-REF: lazy metrics import
            {
                "timestamp": utc_now_iso(),
                "type": "daily_retrain",
                "batch_mse": batch_mse,
                "hyperparams": json.dumps(utils.to_serializable(CFG.sgd_params)),
                "seed": SEED,
                "model": "SGDRegressor",
                "git_hash": get_git_hash(),
            }
        )

    return mp


def _resolve_after_hours_training_marker_path() -> Path:
    raw_marker_path = str(
        get_env(
            "AI_TRADING_AFTER_HOURS_TRAINING_MARKER_PATH",
            "runtime/after_hours_training.marker.json",
            cast=str,
        )
        or ""
    ).strip()
    return resolve_runtime_artifact_path(
        raw_marker_path,
        default_relative="runtime/after_hours_training.marker.json",
    )


def _resolve_after_hours_training_marker_fallback_path() -> Path:
    return (paths.DATA_DIR / "runtime/after_hours_training.marker.json").resolve()


def _resolve_after_hours_training_marker_paths() -> tuple[Path, ...]:
    marker_path = _resolve_after_hours_training_marker_path()
    fallback_path = _resolve_after_hours_training_marker_fallback_path()
    if fallback_path == marker_path:
        return (marker_path,)
    return marker_path, fallback_path


def _load_after_hours_training_marker(path: Path) -> dict[str, Any]:
    try:
        with path.open("r", encoding="utf-8") as handle:
            payload = json.load(handle)
    except FileNotFoundError:
        return {}
    except (
        PermissionError,
        IsADirectoryError,
        JSONDecodeError,
        ValueError,
        TypeError,
        OSError,
    ) as exc:
        logger.warning(
            "AFTER_HOURS_TRAINING_MARKER_READ_FAILED",
            extra={"path": str(path), "error": str(exc)},
        )
        return {}
    if not isinstance(payload, Mapping):
        logger.warning(
            "AFTER_HOURS_TRAINING_MARKER_INVALID",
            extra={"path": str(path), "reason": "non_mapping_payload"},
        )
        return {}
    return dict(payload)


def _after_hours_training_completed_for_date(date_key: str) -> bool:
    terminal_skip_reasons = {
        "no_candidate_models",
        "no_new_signal_data",
        "no_qualified_candidate",
    }
    for marker_path in _resolve_after_hours_training_marker_paths():
        marker = _load_after_hours_training_marker(marker_path)
        marker_date = str(marker.get("date") or "").strip()
        marker_status = str(marker.get("status") or "").strip().lower()
        marker_reason = str(marker.get("reason") or "").strip().lower()
        if marker_date == date_key and (
            marker_status == "trained"
            or (
                marker_status == "skipped"
                and marker_reason in terminal_skip_reasons
            )
        ):
            return True
    return False


def _write_after_hours_training_marker_file(path: Path, payload: Mapping[str, Any]) -> None:
    tmp_path = path.with_suffix(path.suffix + ".tmp")
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        with tmp_path.open("w", encoding="utf-8") as handle:
            json.dump(payload, handle, sort_keys=True)
            handle.write("\n")
        os.replace(tmp_path, path)
    finally:
        try:
            tmp_path.unlink(missing_ok=True)
        except OSError:
            pass


def _write_after_hours_training_marker(date_key: str, outcome: Mapping[str, Any]) -> None:
    marker_paths = _resolve_after_hours_training_marker_paths()
    marker_path = marker_paths[0]
    payload = {
        "date": date_key,
        "status": str(outcome.get("status") or "").strip().lower(),
        "reason": str(outcome.get("reason") or "").strip().lower(),
        "model_id": str(outcome.get("model_id") or "").strip(),
        "model_name": str(outcome.get("model_name") or "").strip(),
        "governance_status": str(outcome.get("governance_status") or "").strip(),
        "updated_at": datetime.now(UTC).isoformat(),
    }
    last_error: Exception | None = None
    for index, target_path in enumerate(marker_paths):
        try:
            _write_after_hours_training_marker_file(target_path, payload)
            if target_path != marker_path:
                logger.warning(
                    "AFTER_HOURS_TRAINING_MARKER_PATH_FALLBACK",
                    extra={
                        "requested_path": str(marker_path),
                        "fallback_path": str(target_path),
                        "error": str(last_error) if last_error is not None else None,
                    },
                )
            return
        except (
            FileNotFoundError,
            PermissionError,
            IsADirectoryError,
            ValueError,
            TypeError,
            OSError,
        ) as exc:
            last_error = exc
            if index + 1 < len(marker_paths):
                continue
            logger.warning(
                "AFTER_HOURS_TRAINING_MARKER_WRITE_FAILED",
                extra={
                    "path": str(target_path),
                    "requested_path": str(marker_path),
                    "error": str(exc),
                },
            )


def _resolve_after_hours_training_date_key(now_est: datetime) -> str | None:
    """Return the session date key eligible for after-hours training."""

    minutes = (int(now_est.hour) * 60) + int(now_est.minute)
    close_minutes = 16 * 60
    catchup_end_minutes = (9 * 60) + 30
    if minutes >= close_minutes:
        return now_est.date().isoformat()
    catchup_enabled = bool(
        get_env("AI_TRADING_AFTER_HOURS_TRAINING_CATCHUP_ENABLED", True, cast=bool)
    )
    if catchup_enabled and minutes < catchup_end_minutes:
        return _prev_bus_day(now_est.date()).isoformat()
    return None


def on_market_close() -> None:
    """Trigger daily retraining after the market closes."""
    now_est = dt_.now(UTC).astimezone(ZoneInfo("America/New_York"))
    from ai_trading.config.research_policy import training_block_reason

    block_reason = training_block_reason(now_est)
    if block_reason:
        logger.info("MARKET_CLOSE_TRAINING_SKIPPED", extra={"reason": block_reason})
        return
    if market_is_open(now_est):
        logger.info("RETRAIN_SKIP_MARKET_OPEN")
        return
    if should_stop():
        logger.info(
            "MARKET_CLOSE_TRAINING_SKIPPED",
            extra={"reason": "shutdown_requested", "stage": "entry"},
        )
        return
    after_hours_date_key = _resolve_after_hours_training_date_key(now_est)
    if not after_hours_date_key:
        logger.info("RETRAIN_SKIP_WINDOW", extra={"time": now_est.isoformat()})
        return
    after_hours_enabled = bool(
        get_env("AI_TRADING_AFTER_HOURS_TRAINING_ENABLED", False, cast=bool)
    )
    after_hours_once_per_day = bool(
        get_env("AI_TRADING_AFTER_HOURS_TRAINING_ONCE_PER_DAY", True, cast=bool)
    )
    if (
        after_hours_enabled
        and after_hours_once_per_day
        and _after_hours_training_completed_for_date(after_hours_date_key)
    ):
        logger.info(
            "AFTER_HOURS_TRAINING_ALREADY_COMPLETED",
            extra={"date": after_hours_date_key},
        )
        after_hours_enabled = False
    if after_hours_enabled:
        if should_stop():
            logger.info(
                "MARKET_CLOSE_TRAINING_SKIPPED",
                extra={"reason": "shutdown_requested", "stage": "before_after_hours"},
            )
            return
        try:
            from ai_trading.training.after_hours import run_after_hours_training

            outcome = run_after_hours_training(now=now_est.astimezone(UTC))
            logger.info(
                "AFTER_HOURS_TRAINING_OUTCOME",
                extra={
                    "status": outcome.get("status"),
                    "model_id": outcome.get("model_id"),
                    "model_name": outcome.get("model_name"),
                    "governance_status": outcome.get("governance_status"),
                    "reason": outcome.get("reason"),
                },
            )
            if after_hours_once_per_day and isinstance(outcome, Mapping):
                outcome_status = str(outcome.get("status") or "").strip().lower()
                outcome_reason = str(outcome.get("reason") or "").strip().lower()
                terminal_outcome = bool(
                    outcome_status == "trained"
                    or (
                        outcome_status == "skipped"
                        and outcome_reason
                        in {
                            "no_candidate_models",
                            "no_new_signal_data",
                            "no_qualified_candidate",
                        }
                    )
                )
                if terminal_outcome:
                    _write_after_hours_training_marker(
                        after_hours_date_key,
                        outcome,
                    )
            if isinstance(outcome, Mapping):
                rl_overlay_outcome = outcome.get("rl_overlay")
                if isinstance(rl_overlay_outcome, Mapping):
                    promoted_rl_model_path = str(
                        rl_overlay_outcome.get("promoted_model_path") or ""
                    ).strip()
                    if promoted_rl_model_path:
                        _reload_rl_agent_from_runtime_path(
                            model_path=promoted_rl_model_path,
                            reason="after_hours_training",
                            force=True,
                        )
        except BOT_ENGINE_FALLBACK_EXC as exc:
            logger.exception(f"after-hours training failed: {exc}")
    if should_stop():
        logger.info(
            "MARKET_CLOSE_TRAINING_SKIPPED",
            extra={"reason": "shutdown_requested", "stage": "before_legacy"},
        )
        return
    legacy_daily_retrain = bool(
        get_env("AI_TRADING_LEGACY_DAILY_RETRAIN_ENABLED", True, cast=bool)
    )
    if not legacy_daily_retrain:
        logger.info("LEGACY_DAILY_RETRAIN_SKIPPED")
        return
    try:
        load_or_retrain_daily(get_ctx())
    except (
        FileNotFoundError,
        PermissionError,
        IsADirectoryError,
        JSONDecodeError,
        ValueError,
        KeyError,
        TypeError,
        OSError,
    ) as exc:  # AI-AGENT-REF: narrow exception
        logger.exception(f"on_market_close failed: {exc}")


