def start_healthcheck() -> None:
    from ai_trading.core.runtime_services import start_healthcheck_runtime

    bootstrap_runtime_defaults()
    start_healthcheck_runtime()


def start_metrics_server(default_port: int = 9200) -> None:
    """Start Prometheus metrics server handling port conflicts."""
    if not PROMETHEUS_AVAILABLE:
        logger.debug("Prometheus not available; skipping metrics server start")
        return
    try:
        start_http_server(default_port)
        logger.debug("Metrics server started on %d", default_port)
        return
    except OSError as exc:
        if "Address already in use" in str(exc):
            try:
                resp = http.get(
                    f"http://localhost:{default_port}",
                    timeout=clamp_request_timeout(2),
                )
                if resp.ok:
                    logger.info("Metrics port %d already serving; reusing", default_port)
                    return
            except (
                FileNotFoundError,
                PermissionError,
                IsADirectoryError,
                JSONDecodeError,
                ValueError,
                KeyError,
                TypeError,
                OSError,
            ) as e:  # AI-AGENT-REF: narrow exception
                # Metrics server connectivity check failed - continue with port search
                logger.debug(
                    "Metrics server check failed on port %d: %s", default_port, e
                )
            # Avoid NameError (no 'utils' alias imported here)
            from ai_trading.utils import (
                get_free_port,
            )  # AI-AGENT-REF: local import avoids cycles

            port = get_free_port(default_port + 1, default_port + 50)
            if port is None:
                logger.warning("No free port available for metrics server")
                return
            logger.warning("Metrics port %d busy; using %d", default_port, port)
            try:
                start_http_server(port)
            except (
                FileNotFoundError,
                PermissionError,
                IsADirectoryError,
                JSONDecodeError,
                ValueError,
                KeyError,
                TypeError,
                OSError,
            ) as exc2:  # AI-AGENT-REF: narrow exception
                logger.warning("Failed to start metrics server on %d: %s", port, exc2)
        else:
            logger.warning("Failed to start metrics server on %d: %s", default_port, exc)
    except (
        FileNotFoundError,
        PermissionError,
        IsADirectoryError,
        JSONDecodeError,
        ValueError,
        KeyError,
        TypeError,
        OSError,
    ) as exc:  # pragma: no cover - unexpected error  # AI-AGENT-REF: narrow exception
        logger.warning("Failed to start metrics server on %d: %s", default_port, exc)


def _quote_to_mid(quote: Any | None) -> tuple[float | None, float, float]:
    """Return (mid, bid, ask) for ``quote`` when available."""

    if quote is None:
        return None, 0.0, 0.0
    bid_value, ask_value = _extract_quote_bid_ask(quote)
    bid = float(bid_value) if bid_value is not None else 0.0
    ask = float(ask_value) if ask_value is not None else 0.0
    if bid > 0 and ask > 0:
        return (bid + ask) / 2.0, bid, ask
    return None, bid, ask


def _quote_timestamp(quote: Any | None) -> datetime | None:
    """Return best-effort UTC timestamp for a quote payload."""

    if quote is None:
        return None
    for field_name in (
        "timestamp",
        "ts",
        "t",
        "time",
        "quote_timestamp",
    ):
        if isinstance(quote, Mapping):
            raw_value = quote.get(field_name)
        else:
            raw_value = getattr(quote, field_name, None)
        if raw_value in (None, ""):
            continue
        if isinstance(raw_value, datetime):
            parsed = raw_value
            if parsed.tzinfo is None:
                parsed = parsed.replace(tzinfo=UTC)
            return parsed.astimezone(UTC)
        parsed = _parse_iso_timestamp(raw_value)
        if parsed is not None:
            return parsed
    return None


def _fetch_quote(ctx: Any, symbol: str, *, feed: str | None = None) -> Any | None:
    """Fetch the latest quote using the configured data client."""

    def _unwrap_quote_payload(payload: Any) -> Any:
        """Return the innermost quote object exposing bid/ask fields."""

        def _has_bid_ask_fields(candidate: Any) -> bool:
            for attr in ("bid_price", "bp", "bid", "ask_price", "ap", "ask"):
                if getattr(candidate, attr, None) is not None:
                    return True
            if isinstance(candidate, Mapping):
                for key in ("bid_price", "bp", "bid", "ask_price", "ap", "ask"):
                    if candidate.get(key) is not None:
                        return True
            return False

        def _resolve_symbol_mapping(candidate: Mapping[Any, Any]) -> Any | None:
            if not candidate:
                return None
            symbol_keys = (symbol, symbol.upper(), symbol.lower())
            for key in symbol_keys:
                if key in candidate:
                    return candidate.get(key)
            if len(candidate) == 1:
                try:
                    return next(iter(candidate.values()))
                except BOT_ENGINE_FALLBACK_EXC:
                    return None
            return None

        current = payload
        seen: set[int] = set()
        while current is not None:
            identifier = id(current)
            if identifier in seen:
                break
            seen.add(identifier)

            if _has_bid_ask_fields(current):
                return current

            next_level: Any | None = None
            if isinstance(current, Mapping):
                next_level = _resolve_symbol_mapping(current)
                if next_level is None:
                    for key in ("quote", "latest_quote", "quotes", "data"):
                        mapped = current.get(key)
                        if mapped is None:
                            continue
                        if isinstance(mapped, Mapping):
                            next_level = _resolve_symbol_mapping(mapped)
                            if next_level is None:
                                next_level = mapped
                        else:
                            next_level = mapped
                        if next_level is not None:
                            break
            if next_level is None:
                for attr in ("quote", "latest_quote", "quotes", "data"):
                    nested = getattr(current, attr, None)
                    if nested is None:
                        continue
                    if isinstance(nested, Mapping):
                        next_level = _resolve_symbol_mapping(nested)
                        if next_level is None:
                            next_level = nested
                    else:
                        next_level = nested
                    if next_level is not None:
                        break
            if next_level is None or next_level is current:
                break
            current = next_level
        return current

    try:
        if not _stock_quote_request_ready():
            raise RuntimeError("StockLatestQuoteRequest unavailable")
        effective_feed = _sanitize_alpaca_feed(feed) if feed else None
        if effective_feed is not None:
            try:
                req = StockLatestQuoteRequest(symbol_or_symbols=[symbol], feed=effective_feed)
            except TypeError:
                req = StockLatestQuoteRequest(symbol_or_symbols=[symbol])
        else:
            req = StockLatestQuoteRequest(symbol_or_symbols=[symbol])
        clients: list[Any] = []
        try:
            context_client = getattr(ctx, "data_client", None)
        except COMMON_EXC:
            context_client = None
        if context_client is not None:
            clients.append(context_client)
        global_client = data_client
        if global_client is not None and all(global_client is not client for client in clients):
            clients.append(global_client)
        if not clients:
            raise RuntimeError("No data_client available for quote fetch")
        for client in clients:
            quote = client.get_stock_latest_quote(req)
            if quote is None:
                continue
            # alpaca-py returns ``StockLatestQuoteResponse`` with the quote nested
            # under ``quote`` or ``latest_quote``; unwrap so downstream helpers see
            # ``bid_price``/``ask_price`` attributes directly. Some test doubles
            # mimic the production response shape as ``quote.quote`` so walk the
            # nesting chain until a leaf object is reached.
            return _unwrap_quote_payload(quote)
        return None
    except COMMON_EXC as exc:  # pragma: no cover - best effort logging
        logger.debug(
            "QUOTE_FETCH_FAILED",
            extra={
                "symbol": symbol,
                "feed": effective_feed or "nbbo",
                "error": str(exc),
            },
        )
        return None


def _quote_age_seconds(quote: Any | None) -> float:
    """Return the age of ``quote`` in seconds, ``inf`` when unavailable."""

    if quote is None:
        return float("inf")
    ts = _extract_quote_timestamp(quote)
    if ts is None:
        return float("inf")
    try:
        return max(0.0, (datetime.now(UTC) - ts.astimezone(UTC)).total_seconds())
    except COMMON_EXC:
        return float("inf")


def _extract_quote_bid_ask(quote: Any | None) -> tuple[float | None, float | None]:
    """Return ``(bid, ask)`` from *quote* when available and positive."""

    if quote is None:
        return None, None

    def _coerce(value: Any | None) -> float | None:
        try:
            if value is None:
                return None
            parsed = float(value)
        except (TypeError, ValueError):
            return None
        if not math.isfinite(parsed) or parsed <= 0:
            return None
        return parsed

    bid_source = None
    ask_source = None
    for attr in ("bid_price", "bp", "bid"):
        bid_source = getattr(quote, attr, None)
        if bid_source is not None:
            break
    for attr in ("ask_price", "ap", "ask"):
        ask_source = getattr(quote, attr, None)
        if ask_source is not None:
            break
    if isinstance(quote, Mapping):
        if bid_source is None:
            bid_source = quote.get("bid_price") or quote.get("bp") or quote.get("bid")
        if ask_source is None:
            ask_source = quote.get("ask_price") or quote.get("ap") or quote.get("ask")
    return _coerce(bid_source), _coerce(ask_source)


def _slippage_setting_bps() -> float:
    """Return configured slippage (basis points) for synthetic pricing paths."""

    for key in ("PRICE_SLIPPAGE_BPS", "SLIPPAGE_BPS"):
        try:
            value = get_env(key, None, cast=float)
        except COMMON_EXC:
            continue
        if value is not None:
            try:
                return max(float(value), 0.0)
            except (TypeError, ValueError):
                continue
    try:
        cfg = get_trading_config()
    except COMMON_EXC:
        cfg = None
    if cfg is not None:
        try:
            configured = getattr(cfg, "price_slippage_bps", None)
        except AttributeError:
            configured = None
        if configured is not None:
            try:
                return max(float(configured), 0.0)
            except (TypeError, ValueError):
                pass
    return 10.0


def _fallback_active_for_timeframes(
    provider_state: Mapping[str, Any] | None,
    *,
    include_daily: bool,
) -> bool:
    if not isinstance(provider_state, MappingABC):
        return False
    tf_state = provider_state.get("timeframes")
    if not isinstance(tf_state, MappingABC):
        return False
    for tf_key, flag in tf_state.items():
        try:
            normalized = str(tf_key).strip().lower()
        except BOT_ENGINE_FALLBACK_EXC:
            normalized = str(tf_key)
        if not normalized:
            continue
        is_minute = normalized.endswith("min") or normalized in {
            "1m",
            "1min",
            "intraday",
            "minute",
        }
        is_daily = normalized.endswith("day") or normalized in {"1d", "1day", "daily"}
        if is_minute or (include_daily and is_daily):
            try:
                if bool(flag):
                    return True
            except BOT_ENGINE_FALLBACK_EXC:
                continue
    return False


def _minute_fallback_active(provider_state: Mapping[str, Any] | None) -> bool:
    return _fallback_active_for_timeframes(provider_state, include_daily=False)


def _quote_age_limit_ms() -> float:
    try:
        return max(float(get_env("QUOTE_MAX_AGE_MS", 2000, cast=float)), 0.0)
    except BOT_ENGINE_FALLBACK_EXC:
        logger.debug("QUOTE_AGE_LIMIT_PARSE_FAILED", exc_info=True)
        return 2000.0


def _quote_age_ms_from_state(state: Mapping[str, Any] | None) -> float | None:
    if not isinstance(state, MappingABC):
        return None
    age_ms = state.get("quote_age_ms")
    if age_ms is None:
        age_sec = state.get("age_sec")
        try:
            if age_sec is not None:
                age_ms = float(age_sec) * 1000.0
        except BOT_ENGINE_FALLBACK_EXC:
            age_ms = None
    if age_ms is None:
        return None
    try:
        value = float(age_ms)
    except (TypeError, ValueError):
        return None
    return value if value >= 0.0 and math.isfinite(value) else None


def _resolve_primary_feed_derisk_state(runtime: Any) -> dict[str, Any]:
    """Resolve derisk policy state for prolonged fallback/quote-quality failures."""

    try:
        enabled = bool(
            get_env("AI_TRADING_PRIMARY_FEED_DERISK_ENABLED", True, cast=bool)
        )
    except BOT_ENGINE_FALLBACK_EXC:
        enabled = True

    try:
        mode_raw = str(
            get_env(
                "AI_TRADING_PRIMARY_FEED_DERISK_MODE",
                "scale",
                cast=str,
            )
            or "scale"
        )
    except BOT_ENGINE_FALLBACK_EXC:
        mode_raw = "scale"
    mode = mode_raw.strip().lower()
    if mode not in {"scale", "block"}:
        mode = "scale"

    try:
        trigger_after_s = float(
            get_env(
                "AI_TRADING_PRIMARY_FEED_DERISK_AFTER_SEC",
                180.0,
                cast=float,
            )
        )
    except BOT_ENGINE_FALLBACK_EXC:
        trigger_after_s = 180.0
    if not math.isfinite(trigger_after_s):
        trigger_after_s = 180.0
    trigger_after_s = max(0.0, min(trigger_after_s, 86400.0))

    try:
        block_after_s = float(
            get_env(
                "AI_TRADING_PRIMARY_FEED_DERISK_BLOCK_AFTER_SEC",
                900.0,
                cast=float,
            )
        )
    except BOT_ENGINE_FALLBACK_EXC:
        block_after_s = 900.0
    if not math.isfinite(block_after_s):
        block_after_s = 900.0
    block_after_s = max(0.0, min(block_after_s, 86400.0))

    try:
        scale_mult = float(
            get_env(
                "AI_TRADING_PRIMARY_FEED_DERISK_SCALE_MULT",
                0.5,
                cast=float,
            )
        )
    except BOT_ENGINE_FALLBACK_EXC:
        scale_mult = 0.5
    if not math.isfinite(scale_mult):
        scale_mult = 0.5
    scale_mult = max(0.05, min(scale_mult, 1.0))

    try:
        include_daily_fallback = bool(
            get_env("AI_TRADING_PRIMARY_FEED_DERISK_INCLUDE_DAILY", False, cast=bool)
        )
    except BOT_ENGINE_FALLBACK_EXC:
        include_daily_fallback = False
    try:
        suppress_on_healthy_backup = bool(
            get_env(
                "AI_TRADING_PRIMARY_FEED_DERISK_SUPPRESS_ON_HEALTHY_BACKUP",
                True,
                cast=bool,
            )
        )
    except BOT_ENGINE_FALLBACK_EXC:
        suppress_on_healthy_backup = True
    try:
        exit_only_on_degraded = bool(
            get_env("AI_TRADING_PRIMARY_FEED_DERISK_EXIT_ONLY_ON_DEGRADED", True, cast=bool)
        )
    except BOT_ENGINE_FALLBACK_EXC:
        exit_only_on_degraded = True

    try:
        provider_state = runtime_state.observe_data_provider_state()
    except BOT_ENGINE_FALLBACK_EXC:
        provider_state = {}
    try:
        quote_state = runtime_state.observe_quote_status()
    except BOT_ENGINE_FALLBACK_EXC:
        quote_state = {}

    fallback_active = _fallback_active_for_timeframes(
        provider_state,
        include_daily=include_daily_fallback,
    )
    quote_age_ms = _quote_age_ms_from_state(quote_state)
    quote_age_limit_ms = _quote_age_limit_ms()
    quote_synthetic = bool(quote_state.get("synthetic"))
    quote_stale = quote_age_ms is not None and quote_age_ms > quote_age_limit_ms
    quote_quality_failed = bool(quote_synthetic or quote_stale)
    provider_status = (
        str(provider_state.get("status") or "").strip().lower()
        if isinstance(provider_state, MappingABC)
        else ""
    )
    provider_data_status = (
        str(provider_state.get("data_status") or "").strip().lower()
        if isinstance(provider_state, MappingABC)
        else ""
    )
    provider_reason_token = (
        str(provider_state.get("reason") or "").strip().lower()
        if isinstance(provider_state, MappingABC)
        else ""
    )
    hard_reason_tokens = (
        "unavailable",
        "offline",
        "halt",
        "disabled",
        "timeout",
        "error",
        "stale",
        "gap",
    )
    backup_healthy = bool(
        fallback_active
        and not quote_quality_failed
        and provider_status in {"degraded", "healthy", "ok", "unknown"}
        and provider_data_status in {"ready", "healthy", "ok"}
        and not any(token in provider_reason_token for token in hard_reason_tokens)
    )
    fallback_derisk_suppressed = bool(
        suppress_on_healthy_backup and backup_healthy
    )

    reasons: list[str] = []
    provider_reason = provider_state.get("reason") if isinstance(provider_state, MappingABC) else None
    if fallback_active and not fallback_derisk_suppressed:
        reasons.append(
            str(provider_reason or "minute_fallback_active")
        )
    if quote_synthetic:
        reasons.append("synthetic_quote")
    if quote_stale:
        reasons.append("stale_quote")
    reason_tokens = list(dict.fromkeys(reasons))
    reason = ",".join(reason_tokens) if reason_tokens else None

    now_ts = float(time.time())
    state_map = _ensure_runtime_state(runtime)
    degraded_active = bool(
        enabled and ((fallback_active and not fallback_derisk_suppressed) or quote_quality_failed)
    )
    since_raw = state_map.get(_PRIMARY_FEED_DERISK_SINCE_TS_KEY)
    try:
        since_ts = float(since_raw) if since_raw not in (None, "") else 0.0
    except (TypeError, ValueError):
        since_ts = 0.0

    duration_s = 0.0
    if degraded_active:
        if since_ts <= 0.0:
            since_ts = now_ts
            state_map[_PRIMARY_FEED_DERISK_SINCE_TS_KEY] = since_ts
        duration_s = max(now_ts - since_ts, 0.0)
    else:
        state_map[_PRIMARY_FEED_DERISK_SINCE_TS_KEY] = None

    triggered = bool(degraded_active and duration_s >= trigger_after_s)
    exit_only = bool(enabled and exit_only_on_degraded and degraded_active)
    prolonged_block = bool(
        degraded_active
        and block_after_s > 0.0
        and duration_s >= block_after_s
    )
    block = bool((triggered and mode == "block") or exit_only or prolonged_block)
    scale = float(scale_mult if triggered and mode == "scale" and not block else 1.0)
    if prolonged_block and "prolonged_degraded_feed" not in reason_tokens:
        reason_tokens.append("prolonged_degraded_feed")
    reason = ",".join(reason_tokens) if reason_tokens else None
    return {
        "enabled": bool(enabled),
        "mode": mode,
        "trigger_after_s": float(trigger_after_s),
        "block_after_s": float(block_after_s),
        "duration_s": float(duration_s),
        "triggered": bool(triggered),
        "block": bool(block),
        "prolonged_block": bool(prolonged_block),
        "scale": float(scale),
        "exit_only": bool(exit_only),
        "exit_only_on_degraded": bool(exit_only_on_degraded),
        "fallback_active": bool(fallback_active),
        "fallback_derisk_suppressed": bool(fallback_derisk_suppressed),
        "suppress_on_healthy_backup": bool(suppress_on_healthy_backup),
        "backup_healthy": bool(backup_healthy),
        "quote_quality_failed": bool(quote_quality_failed),
        "quote_synthetic": bool(quote_synthetic),
        "quote_stale": bool(quote_stale),
        "quote_age_ms": float(quote_age_ms) if quote_age_ms is not None else None,
        "quote_age_limit_ms": float(quote_age_limit_ms),
        "provider_active": provider_state.get("active")
        if isinstance(provider_state, MappingABC)
        else None,
        "provider_status": provider_state.get("status")
        if isinstance(provider_state, MappingABC)
        else None,
        "provider_data_status": provider_state.get("data_status")
        if isinstance(provider_state, MappingABC)
        else None,
        "reason": reason,
        "include_daily_fallback": bool(include_daily_fallback),
    }


def ensure_data_fetcher(runtime) -> DataFetcher:
    """Ensure a market data fetcher is attached to ``runtime``.

    Attempts to lazily rebuild the fetcher if it is missing. Raises
    ``DataFetchError`` if a fetcher cannot be constructed so callers fail
    fast during startup.
    """

    global data_fetcher
    fetcher = getattr(runtime, "data_fetcher", None)
    if fetcher is not None:
        return cast(DataFetcher, fetcher)
    if data_fetcher is not None:
        logger.warning(
            "DATA_FETCHER_ATTACHED_LATE",
            extra={"key": "data_fetcher_attached_late"},
        )
        runtime.data_fetcher = data_fetcher
        return cast(DataFetcher, data_fetcher)
    # Do not treat a late-construction as a warning to keep startup logs clean
    logger.info("DATA_FETCHER_MISSING", extra={"key": "data_fetcher_missing"})
    try:
        fetcher = data_fetcher_module.build_fetcher()
    except COMMON_EXC as exc:  # pragma: no cover - best effort during startup
        logger_once.error(
            "DATA_FETCHER_INIT_FAILED", extra={"detail": str(exc)},
            key="data_fetcher_init_failed",
        )
        raise DataFetchError("data_fetcher not available") from exc
    runtime.data_fetcher = fetcher
    data_fetcher = fetcher
    return cast(DataFetcher, fetcher)


def _log_loop_heartbeat(loop_id: str, start: float) -> None:
    duration = monotonic_time() - start
    logger.info(
        "HEARTBEAT",
        extra={
            "loop_id": loop_id,
            "timestamp": utc_now_iso(),  # AI-AGENT-REF: Use UTC timestamp utility
            "duration": duration,
        },
    )


def _ensure_execution_engine(runtime) -> None:
    """Ensure an execution engine with the post-cycle check_stops hook is attached."""
    try:
        execution_module = importlib.import_module("ai_trading.execution")
    except ImportError as exc:
        missing_mod = getattr(exc, "name", None)
        logger_once.error(
            "EXECUTION_ENGINE_IMPORT_ABORTED",
            key="execution_engine_import_aborted",
            extra={
                "error": str(exc),
                "missing_module": missing_mod,
            },
        )
        raise RuntimeError(
            "Execution engine dependencies are unavailable. Install the required runtime "
            "packages (pydantic, pydantic-settings, alpaca-py) before trading."
        ) from exc

    try:
        get_execution_runtime_status = getattr(
            execution_module, "get_execution_runtime_status"
        )
    except AttributeError as exc:
        logger_once.error(
            "EXECUTION_ENGINE_IMPORT_ABORTED",
            key="execution_engine_import_aborted",
            extra={"error": str(exc), "missing_module": "ai_trading.execution"},
        )
        raise RuntimeError(
            "Execution engine dependencies are unavailable. Install the required runtime "
            "packages (pydantic, pydantic-settings, alpaca-py) before trading."
        ) from exc

    def _capture_status() -> tuple[Any, dict[str, Any]]:
        status_local = get_execution_runtime_status()
        engine_class_path_local = status_local.engine_class or ""
        missing_deps_local = tuple(status_local.missing_dependencies)
        missing_creds_local = tuple(status_local.missing_credentials)
        diagnostics_local = {
            "engine_class": engine_class_path_local or None,
            "execution_mode": status_local.mode,
            "shadow_mode": status_local.shadow_mode,
            "missing_dependencies": missing_deps_local or None,
            "missing_credentials": missing_creds_local or None,
            "reason": status_local.reason,
            "settings_fallback": status_local.settings_fallback,
        }
        return status_local, diagnostics_local

    status, diagnostics = _capture_status()
    try:
        _ExecutionEngine = getattr(execution_module, "ExecutionEngine")
    except AttributeError as exc:
        logger_once.error(
            "EXECUTION_ENGINE_IMPORT_ABORTED",
            key="execution_engine_import_aborted",
            extra={"error": str(exc), "missing_module": "ai_trading.execution"},
        )
        raise RuntimeError(
            "Execution engine dependencies are unavailable. Install the required runtime "
            "packages (pydantic, pydantic-settings, alpaca-py) before trading."
        ) from exc

    global _exec_engine, ExecutionEngine

    def _attach_stub_engine(
        failure: Exception | None = None,
        delegate_cls: type[Any] | None = None,
    ) -> None:
        """Attach a minimal execution-engine stub exposing the expected hooks."""
        if not _is_testing_env():
            raise RuntimeError(
                "Execution engine stub recovery is test-only; startup aborted."
            ) from failure

        class _RuntimeExecutionEngineStub:
            """Lightweight stub used when the real execution engine is unavailable."""

            _IS_STUB = True

            def __init__(self, ctx) -> None:  # noqa: D401 - simple holder
                self.ctx = ctx
                self._delegate_cls = (
                    delegate_cls
                    if delegate_cls is not None
                    and not getattr(delegate_cls, "_IS_STUB", False)
                    else None
                )
                self._delegate_instance: Any | None = None
                self._delegate_failed = False

            def _get_delegate(self) -> Any | None:
                if self._delegate_cls is None or self._delegate_failed:
                    return None
                if self._delegate_instance is not None:
                    return self._delegate_instance
                try:
                    self._delegate_instance = self._delegate_cls(self.ctx)
                except COMMON_EXC as exc:  # pragma: no cover - delegate optional in tests
                    self._delegate_failed = True
                    logger.debug(
                        "EXECUTION_ENGINE_STUB_DELEGATE_FAILED",
                        extra={
                            "cause": exc.__class__.__name__,
                            "detail": str(exc),
                        },
                    )
                    return None
                return self._delegate_instance

            def start_cycle(self) -> None:  # pragma: no cover - simple stub
                return None

            def end_cycle(self) -> None:  # pragma: no cover - simple stub
                return None

            def check_stops(self) -> None:
                delegate = self._get_delegate()
                if delegate is not None and hasattr(delegate, "check_stops"):
                    delegate.check_stops()
                return None

            def check_trailing_stops(self) -> None:
                delegate = self._get_delegate()
                if delegate is not None and hasattr(delegate, "check_trailing_stops"):
                    delegate.check_trailing_stops()
                return None

        stub_engine = _RuntimeExecutionEngineStub(runtime)
        runtime.execution_engine = stub_engine
        runtime.exec_engine = stub_engine
        _exec_engine = stub_engine
        logger.debug(
            "EXECUTION_ENGINE_STUB_ATTACHED",
            extra={
                "cause": failure.__class__.__name__ if failure else None,
                "detail": str(failure) if failure else None,
                "testing": _is_testing_env(),
            },
        )

    exec_engine = getattr(runtime, "execution_engine", None) or getattr(
        runtime, "exec_engine", None
    )
    stub_attached = getattr(exec_engine, "_IS_STUB", False)
    stub_class = getattr(_ExecutionEngine, "_IS_STUB", False)
    recovered_stub = False

    if stub_attached or stub_class:
        try:
            execution_module = importlib.reload(execution_module)
            get_execution_runtime_status = getattr(
                execution_module, "get_execution_runtime_status"
            )
        except (ImportError, AttributeError) as exc:
            logger_once.error(
                "EXECUTION_ENGINE_STUB_SELECTED",
                key="execution_engine_stub_selected",
                extra=diagnostics,
            )
            raise RuntimeError(
                "Execution engine stub detected; install runtime dependencies to restore risk-stop enforcement."
            ) from exc

        status, diagnostics = _capture_status()
        try:
            _ExecutionEngine = getattr(execution_module, "ExecutionEngine")
        except AttributeError as exc:
            logger_once.error(
                "EXECUTION_ENGINE_STUB_SELECTED",
                key="execution_engine_stub_selected",
                extra=diagnostics,
            )
            raise RuntimeError(
                "Execution engine stub detected; install runtime dependencies to restore risk-stop enforcement."
            ) from exc
        stub_class = getattr(_ExecutionEngine, "_IS_STUB", False)
        if stub_class:
            logger_once.error(
                "EXECUTION_ENGINE_STUB_SELECTED",
                key="execution_engine_stub_selected",
                extra=diagnostics,
            )
            raise RuntimeError(
                "Execution engine stub detected; install runtime dependencies to restore risk-stop enforcement."
            )

        exec_engine = None
        runtime.execution_engine = None
        runtime.exec_engine = None
        _exec_engine = None
        recovered_stub = True

    ExecutionEngine = _ExecutionEngine

    engine_class_path = status.engine_class or ""
    missing_deps = tuple(status.missing_dependencies)
    missing_creds = tuple(status.missing_credentials)

    if not hasattr(_ExecutionEngine, "check_stops"):
        logger_once.error(
            "EXECUTION_ENGINE_MISSING_CHECK_STOPS",
            key="execution_engine_missing_check_stops",
            extra=diagnostics,
        )
        raise RuntimeError(
            "Execution engine class has no check_stops() post-cycle hook; startup aborted. "
            "Stop-loss and max-hold exits run in the netting position backstop, not in this hook."
        )

    expects_live_engine = status.mode in {"paper", "live"}
    engine_is_live = engine_class_path.startswith("ai_trading.execution.live_trading.")
    if expects_live_engine and not engine_is_live:
        logger_once.error(
            "EXECUTION_ENGINE_LIVE_UNAVAILABLE",
            key="execution_engine_live_unavailable",
            extra=diagnostics,
        )
        missing_desc = f" missing_dependencies={missing_deps}" if missing_deps else ""
        creds_desc = f" missing_credentials={missing_creds}" if missing_creds else ""
        raise RuntimeError(
            "Live execution requested but the live trading engine was not selected." +
            f"{missing_desc}{creds_desc}"
        )

    if expects_live_engine and missing_creds:
        if _is_testing_env():
            logger.debug(
                "EXECUTION_ENGINE_CREDENTIALS_MISSING_TEST_ENV",
                extra=diagnostics,
            )
        else:
            logger_once.error(
                "EXECUTION_ENGINE_CREDENTIALS_MISSING",
                key="execution_engine_credentials_missing",
                extra=diagnostics,
            )
            raise RuntimeError(
                "Live execution requested but Alpaca credentials are missing."
            )

    if missing_deps and status.mode in {"paper", "live"}:
        logger_once.error(
            "EXECUTION_ENGINE_DEPENDENCY_GAP",
            key="execution_engine_dependency_gap",
            extra=diagnostics,
        )
        raise RuntimeError(
            "Execution engine dependencies missing: " + ", ".join(missing_deps)
        )

    exec_engine = getattr(runtime, "execution_engine", None) or getattr(
        runtime, "exec_engine", None
    )
    if exec_engine is None and _exec_engine is not None:
        exec_engine = _exec_engine
        runtime.execution_engine = exec_engine
        runtime.exec_engine = exec_engine
    if exec_engine is None:
        try:
            exec_engine = _ExecutionEngine(runtime)
            runtime.execution_engine = exec_engine
            runtime.exec_engine = exec_engine
            _exec_engine = exec_engine
            logger.debug(
                "Execution engine initialized and attached to runtime"
            )
        except (ImportError, AttributeError, RuntimeError, ValueError) as e:  # pragma: no cover - initialization rarely fails
            logger.warning(
                "Execution engine initialization failed: %s", e
            )
            if not _is_testing_env():
                raise RuntimeError(
                    "Execution engine initialization failed and stub recovery is disabled outside tests."
                ) from e
            delegate_cls = None if getattr(_ExecutionEngine, "_IS_STUB", False) else _ExecutionEngine
            _attach_stub_engine(e, delegate_cls)
            if recovered_stub:
                raise RuntimeError(
                    "Execution engine initialization failed after replacing stub; aborting startup."
                ) from e
            return
    else:
        runtime.execution_engine = exec_engine
        runtime.exec_engine = exec_engine
        _exec_engine = exec_engine
    if getattr(exec_engine, "_IS_STUB", False):
        if _is_testing_env():
            logger.debug(
                "Execution engine stub active in testing environment; continuing"
            )
        else:
            raise RuntimeError(
                "Execution engine stub detected after initialization; aborting startup."
            )
    if not hasattr(exec_engine, "check_stops"):
        raise RuntimeError(
            "Execution engine has no check_stops() post-cycle hook; startup aborted. "
            "Stop-loss and max-hold exits run in the netting position backstop, not in this hook."
        )


def _check_runtime_stops(runtime) -> None:
    """Run post-cycle stop checks if supported."""
    exec_engine = getattr(runtime, "exec_engine", None) or getattr(
        runtime, "execution_engine", None
    )
    if exec_engine is None:
        logger.warning(
            "Execution engine missing check_stops; risk-stop checks skipped",
        )
        return
    check_stops = getattr(exec_engine, "check_stops", None)
    if callable(check_stops):
        try:
            check_stops()
        except (ValueError, TypeError) as e:  # AI-AGENT-REF: guard check_stops
            logger.info("check_stops raised but was suppressed: %s", e)
    else:
        logger.warning(
            "Execution engine missing check_stops; risk-stop checks skipped",
        )
    check_trailing = getattr(exec_engine, "check_trailing_stops", None)
    if not callable(check_trailing):
        logger.debug(
            "Execution engine missing check_trailing_stops; trailing-stop checks skipped"
        )
        return
    try:
        check_trailing()
    except (ValueError, TypeError) as e:  # AI-AGENT-REF: guard trailing stops
        logger.info(
            "TRAILING_STOP_CHECK_SUPPRESSED",
            extra={"cause": e.__class__.__name__, "detail": str(e)},
        )
    try:
        liquidate_positions_if_needed(runtime)
    except (ValueError, TypeError) as e:
        logger.info(
            "EOD_FLATTEN_CHECK_SUPPRESSED",
            extra={"cause": e.__class__.__name__, "detail": str(e)},
        )

_LAST_MARKET_CLOSED_LOG = 0.0


def _log_market_closed(msg: str) -> None:
    """Log a market-closed message with basic throttling."""
    global _LAST_MARKET_CLOSED_LOG
    now = monotonic_time()
    if now - _LAST_MARKET_CLOSED_LOG >= 60:
        logger.info(msg)
        _LAST_MARKET_CLOSED_LOG = now


def _pending_order_force_cleanup_seconds() -> float:
    try:
        value = float(
            get_env(
                "AI_TRADING_PENDING_NEW_FORCE_CANCEL_SEC",
                _PENDING_ORDER_FORCE_CLEANUP_SEC_DEFAULT,
                cast=float,
            )
        )
    except COMMON_EXC:
        value = _PENDING_ORDER_FORCE_CLEANUP_SEC_DEFAULT
    return max(5.0, min(value, 3600.0))


def _pending_cleanup_warmup_cycles() -> int:
    """Return how many cycles to skip after forced pending-order cleanup."""

    try:
        raw_value = get_env("AI_TRADING_PENDING_CLEANUP_WARMUP_CYCLES", 0, cast=int)
    except COMMON_EXC:
        raw_value = 0
    try:
        value = int(raw_value)
    except (TypeError, ValueError):
        value = 0
    return max(0, min(value, 10))


def _arm_pending_cleanup_warmup(
    runtime: Any,
    *,
    source: str,
    open_count: int,
    pending_count: int,
) -> bool:
    """Arm skip-cycle warmup after a cleanup action when configured."""

    cycles = _pending_cleanup_warmup_cycles()
    tracker = _get_pending_tracker(runtime)
    if cycles <= 0:
        tracker[_PENDING_ORDER_WARMUP_REMAINING_KEY] = 0.0
        return False
    tracker[_PENDING_ORDER_WARMUP_REMAINING_KEY] = float(max(cycles - 1, 0))
    logger.info(
        "PENDING_CLEANUP_WARMUP_ARMED",
        extra={
            "source": source,
            "warmup_cycles": cycles,
            "open_count": open_count,
            "pending_count": pending_count,
        },
    )
    return True


def _consume_pending_cleanup_warmup(runtime: Any, *, open_count: int) -> bool:
    """Consume one warmup cycle, returning True when cycle should be skipped."""

    tracker = _get_pending_tracker(runtime)
    raw_remaining = tracker.get(_PENDING_ORDER_WARMUP_REMAINING_KEY, 0.0)
    try:
        remaining = int(float(raw_remaining or 0.0))
    except (TypeError, ValueError):
        remaining = 0
    if remaining <= 0:
        tracker[_PENDING_ORDER_WARMUP_REMAINING_KEY] = 0.0
        return False
    remaining = max(remaining - 1, 0)
    tracker[_PENDING_ORDER_WARMUP_REMAINING_KEY] = float(remaining)
    logger.info(
        "PENDING_CLEANUP_WARMUP_SKIP",
        extra={
            "remaining_cycles": remaining,
            "open_count": open_count,
        },
    )
    return True


def _startup_cancel_mode() -> str:
    """Resolve startup cleanup mode with legacy env compatibility."""

    try:
        raw_mode = str(get_env("AI_TRADING_STARTUP_CANCEL_MODE", "", cast=str) or "")
    except COMMON_EXC:
        raw_mode = ""
    mode = raw_mode.strip().lower()
    if mode in {"off", "none", "disabled", "0", "false", "no"}:
        return "off"
    if mode in {"all", "always", "force"}:
        return "all"
    if mode in {"stale", "stale_only", "stale_pending"}:
        return "stale_only"
    try:
        legacy_enabled = bool(
            get_env("AI_TRADING_STARTUP_CANCEL_UNEXPECTED_ORDERS", "0", cast=bool)
        )
    except COMMON_EXC:
        legacy_enabled = False
    if legacy_enabled:
        return "all"
    return "off"


def _startup_cancel_stale_seconds() -> float:
    """Return stale-age threshold used by startup stale-only cleanup mode."""

    try:
        raw_value = float(
            get_env(
                "AI_TRADING_STARTUP_CANCEL_STALE_SEC",
                _STARTUP_CLEANUP_STALE_SEC_DEFAULT,
                cast=float,
            )
        )
    except COMMON_EXC:
        raw_value = _STARTUP_CLEANUP_STALE_SEC_DEFAULT
    return max(10.0, min(raw_value, 7200.0))


def _extract_order_identifier(order: Any) -> str | None:
    """Return broker order id/client_order_id when available."""

    if isinstance(order, MappingABC):
        for key in ("id", "client_order_id"):
            value = order.get(key)
            if value not in (None, ""):
                return str(value)
        return None
    for attr in ("id", "client_order_id"):
        value = getattr(order, attr, None)
        if value not in (None, ""):
            return str(value)
    return None


def _select_startup_stale_orders(open_orders: Iterable[Any]) -> list[Any]:
    """Return stale pending orders for startup cleanup in stale-only mode."""

    stale_after = _startup_cancel_stale_seconds()
    now_dt = datetime.now(UTC)
    selected: list[Any] = []
    for order in open_orders:
        status_raw = order.get("status") if isinstance(order, MappingABC) else getattr(order, "status", None)
        status = _normalize_broker_order_status(status_raw)
        if status and status not in _PENDING_ORDER_STUCK_STATUSES:
            continue
        age_s = _pending_order_broker_age_seconds(order, now_dt)
        if age_s is None or age_s < stale_after:
            continue
        selected.append(order)
    return selected


def _cancel_open_orders_subset(
    runtime: Any,
    *,
    orders: Iterable[Any],
    reason_code: str,
) -> CancelAllResult:
    """Cancel only ``orders`` and return a structured result summary."""

    target_orders = list(orders)
    if not target_orders:
        return CancelAllResult(
            total_open=0,
            cancelled=0,
            failed=0,
            reason_code=reason_code,
            errors=[],
        )

    api = getattr(runtime, "api", None)
    if api is None:
        return CancelAllResult(
            total_open=len(target_orders),
            cancelled=0,
            failed=len(target_orders),
            reason_code=reason_code,
            errors=[{"error": "missing_api"}],
        )

    cancel_order = getattr(api, "cancel_order", None)
    cancel_order_by_id = getattr(api, "cancel_order_by_id", None)
    if not callable(cancel_order) and not callable(cancel_order_by_id):
        return CancelAllResult(
            total_open=len(target_orders),
            cancelled=0,
            failed=len(target_orders),
            reason_code=reason_code,
            errors=[{"error": "missing_cancel_capability"}],
        )

    cancelled = 0
    failed = 0
    errors: list[dict[str, Any]] = []
    for order in target_orders:
        order_id = _extract_order_identifier(order)
        if not order_id:
            failed += 1
            errors.append({"error": "missing_order_identifier"})
            continue
        try:
            if callable(cancel_order):
                cancel_order(order_id)
            elif callable(cancel_order_by_id):
                cancel_order_by_id(order_id)
            cancelled += 1
        except BOT_ENGINE_FALLBACK_EXC as exc:
            failed += 1
            errors.append({"order_id": order_id, "error": str(exc)})
    return CancelAllResult(
        total_open=len(target_orders),
        cancelled=cancelled,
        failed=failed,
        reason_code=reason_code,
        errors=errors,
    )


def _startup_cancel_decision(
    open_orders: Iterable[Any],
    *,
    mode: str,
) -> tuple[bool, dict[str, Any]]:
    """Return (should_cancel, diagnostics) for startup cleanup."""

    open_list = list(open_orders)
    details: dict[str, Any] = {"mode": mode, "open_count": len(open_list)}
    if mode == "off":
        details["reason"] = "disabled"
        return False, details
    if not open_list:
        details["reason"] = "no_open_orders"
        return False, details
    if mode == "all":
        details["reason"] = "mode_all"
        return True, details

    stale_after = _startup_cancel_stale_seconds()
    now_dt = datetime.now(UTC)
    stale_ids: list[str] = []
    stale_statuses: set[str] = set()
    oldest_stuck_age_s: float | None = None
    for order in open_list:
        status = _normalize_broker_order_status(getattr(order, "status", None))
        if status and status not in _PENDING_ORDER_STUCK_STATUSES:
            continue
        age_s = _pending_order_broker_age_seconds(order, now_dt)
        if age_s is None:
            continue
        if oldest_stuck_age_s is None or age_s > oldest_stuck_age_s:
            oldest_stuck_age_s = age_s
        if age_s >= stale_after:
            stale_ids.append(str(getattr(order, "id", "?")))
            if status:
                stale_statuses.add(status)
    details["stale_after_s"] = int(stale_after)
    details["stale_count"] = len(stale_ids)
    details["stale_ids"] = stale_ids[:_PENDING_ORDER_SAMPLE_LIMIT]
    if oldest_stuck_age_s is not None:
        details["oldest_stuck_age_s"] = int(max(oldest_stuck_age_s, 0))
    if stale_statuses:
        details["stale_statuses"] = sorted(stale_statuses)
    if stale_ids:
        details["reason"] = "stale_pending"
        return True, details
    details["reason"] = "no_stale_pending"
    return False, details


def _pending_order_broker_age_seconds(order: Any, now_dt: datetime) -> float | None:
    """Return broker-reported order age in seconds when timestamps are available."""

    for attr in ("updated_at", "submitted_at", "created_at"):
        raw_value = order.get(attr) if isinstance(order, MappingABC) else getattr(order, attr, None)
        if raw_value in (None, ""):
            continue
        try:
            ts_value = _ensure_utc_dt(raw_value)
        except COMMON_EXC:
            continue
        if ts_value.tzinfo is None:
            ts_value = ts_value.replace(tzinfo=UTC)
        else:
            ts_value = ts_value.astimezone(UTC)
        age_s = (now_dt - ts_value).total_seconds()
        return max(age_s, 0.0)
    return None


def _pending_orders_block_scope() -> str:
    """Return pending-order block scope (`cycle` or `symbol`)."""

    try:
        raw_scope = str(
            get_env("AI_TRADING_PENDING_ORDERS_BLOCK_SCOPE", "cycle", cast=str) or ""
        )
    except COMMON_EXC:
        raw_scope = "cycle"
    normalized = raw_scope.strip().lower()
    if normalized in {"symbol", "per_symbol", "symbol_only"}:
        return "symbol"
    return "cycle"


def _pending_orders_warn_after_seconds() -> float:
    """Resolve pending backlog age threshold for WARNING severity."""

    try:
        value = float(
            get_env(
                "AI_TRADING_PENDING_ORDERS_WARN_AFTER_SEC",
                _PENDING_BACKLOG_WARN_AFTER_SEC_DEFAULT,
                cast=float,
            )
        )
    except COMMON_EXC:
        value = _PENDING_BACKLOG_WARN_AFTER_SEC_DEFAULT
    if not math.isfinite(value):
        value = _PENDING_BACKLOG_WARN_AFTER_SEC_DEFAULT
    return max(0.0, min(float(value), 86400.0))


def _pending_orders_warn_every_seconds() -> float:
    """Resolve cooldown between repeated pending backlog warnings."""

    try:
        value = float(
            get_env(
                "AI_TRADING_PENDING_ORDERS_WARN_EVERY_SEC",
                _PENDING_BACKLOG_WARN_EVERY_SEC_DEFAULT,
                cast=float,
            )
        )
    except COMMON_EXC:
        value = _PENDING_BACKLOG_WARN_EVERY_SEC_DEFAULT
    if not math.isfinite(value):
        value = _PENDING_BACKLOG_WARN_EVERY_SEC_DEFAULT
    return max(0.0, min(float(value), 86400.0))


def _pending_stale_sweep_enabled() -> bool:
    """Return ``True`` when stale pending-order sweep policy is enabled."""

    try:
        return bool(get_env("AI_TRADING_PENDING_STALE_SWEEP_ENABLED", True, cast=bool))
    except COMMON_EXC:
        return True


def _pending_stale_sweep_age_seconds() -> float:
    """Return minimum broker age required for stale-sweep cancellation."""

    default_value = _startup_cancel_stale_seconds()
    try:
        value = float(
            get_env(
                "AI_TRADING_PENDING_STALE_SWEEP_SEC",
                default_value,
                cast=float,
            )
        )
    except COMMON_EXC:
        value = default_value
    if not math.isfinite(value):
        value = default_value
    return max(10.0, min(value, 7200.0))


def _pending_stale_sweep_include_partially_filled() -> bool:
    """Return ``True`` when stale sweep should include aged ``partially_filled`` orders."""

    try:
        return bool(
            get_env(
                "AI_TRADING_PENDING_STALE_SWEEP_INCLUDE_PARTIALLY_FILLED",
                True,
                cast=bool,
            )
        )
    except COMMON_EXC:
        return True


def _pending_stale_sweep_partial_fill_age_seconds(stuck_age_s: float) -> float:
    """Return minimum age for sweeping stale ``partially_filled`` orders."""

    default_value = max(float(stuck_age_s) * 6.0, 900.0)
    try:
        value = float(
            get_env(
                "AI_TRADING_PENDING_STALE_SWEEP_PARTIALLY_FILLED_SEC",
                default_value,
                cast=float,
            )
        )
    except COMMON_EXC:
        value = default_value
    if not math.isfinite(value):
        value = default_value
    return max(float(stuck_age_s), min(float(value), 86400.0))


def _pending_stale_sweep_max_cancels() -> int:
    """Return max stale pending orders to cancel per sweep invocation."""

    try:
        value = int(
            get_env(
                "AI_TRADING_PENDING_STALE_SWEEP_MAX_CANCELS",
                1,
                cast=int,
            )
        )
    except COMMON_EXC:
        value = 1
    return max(0, min(value, 100))


def _pending_stale_sweep_cooldown_seconds() -> float:
    """Return cooldown between stale-sweep cancellation attempts."""

    try:
        value = float(
            get_env(
                "AI_TRADING_PENDING_STALE_SWEEP_COOLDOWN_SEC",
                30.0,
                cast=float,
            )
        )
    except COMMON_EXC:
        value = 30.0
    if not math.isfinite(value):
        value = 30.0
    return max(0.0, min(value, 3600.0))


