def _handle_pending_orders(open_orders: Iterable[Any], runtime: Any) -> bool:
    from ai_trading.core.pending_order_runtime import handle_pending_orders

    return handle_pending_orders(open_orders, runtime)


def _resolve_trading_config(runtime) -> TradingConfig:
    cfg = getattr(runtime, "cfg", None)
    if cfg is None or not isinstance(cfg, TradingConfig):
        cfg = get_trading_config()
    return cast(TradingConfig, cfg)


def _enforce_dependency_preflight(runtime) -> None:
    cfg = _resolve_trading_config(runtime)
    testing_flag = bool(getattr(cfg, "testing", False))
    try:
        testing_flag = testing_flag or bool(get_env("AI_TRADING_TESTING", "0", cast=bool))
    except BOT_ENGINE_FALLBACK_EXC:
        testing_flag = testing_flag or False
    testing_flag = testing_flag or is_runtime_contract_testing_mode() or _is_testing_env()
    if testing_flag:
        return
    execution_mode = str(getattr(cfg, "execution_mode", "sim") or "sim").strip().lower()
    if execution_mode not in {"paper", "live"}:
        return
    require_dependency(
        _PYBREAKER_AVAILABLE,
        "pybreaker is required for paper/live trading",
        execution_mode=execution_mode,
    )
    exec_engine = getattr(runtime, "execution_engine", None) or getattr(runtime, "exec_engine", None)
    require_dependency(
        exec_engine is not None,
        "Execution engine is required for paper/live trading",
        execution_mode=execution_mode,
    )
    require_no_stubs(
        {
            "runtime": runtime,
            "_HTTP_SESSION": _HTTP_SESSION,
            "execution_engine": exec_engine,
        },
        execution_mode=execution_mode,
    )
    _enforce_order_type_failfast(runtime, cfg=cfg, execution_mode=execution_mode)


def _enforce_order_type_failfast(
    runtime: Any,
    *,
    cfg: Any | None = None,
    execution_mode: str | None = None,
) -> None:
    if not bool(get_env("AI_TRADING_ORDER_TYPES_ENABLED", "0", cast=bool)):
        return
    if not bool(get_env("AI_TRADING_ORDER_TYPE_FAILFAST_ON_UNSUPPORTED", "1", cast=bool)):
        return

    runtime_cfg = cfg if cfg is not None else _resolve_trading_config(runtime)
    mode = str(execution_mode or getattr(runtime_cfg, "execution_mode", "sim") or "sim").strip().lower()
    if mode not in {"paper", "live"}:
        return
    if bool(getattr(runtime_cfg, "testing", False)) or _is_testing_env() or is_runtime_contract_testing_mode():
        return

    capabilities = _resolve_order_type_capabilities(runtime)
    if capabilities is None:
        raise RuntimeError("ORDER_TYPE_CAPABILITIES_MISSING")
    try:
        validate_order_type_support(
            configured_entry_type=str(
                get_env("AI_TRADING_DEFAULT_ENTRY_ORDER_TYPE", "limit")
            ).strip().lower(),
            configured_exit_type=str(
                get_env("AI_TRADING_DEFAULT_EXIT_ORDER_TYPE", "stop_limit")
            ).strip().lower(),
            allow_bracket=bool(get_env("AI_TRADING_ALLOW_BRACKET_ORDERS", "0", cast=bool)),
            allow_oco_oto=bool(get_env("AI_TRADING_ALLOW_OCO_OTO", "0", cast=bool)),
            capabilities=capabilities,
        )
    except RuntimeError as exc:
        raise RuntimeError(f"ORDER_TYPE_UNSUPPORTED: {exc}") from exc


def _resolve_order_type_capabilities(runtime: Any) -> Mapping[str, bool] | None:
    from ai_trading.core.execution_runtime_metadata import resolve_order_type_capabilities

    return resolve_order_type_capabilities(runtime)


def _get_pretrade_limit_env(
    primary_key: str,
    *,
    fallback_key: str | None = None,
    default: int,
) -> int:
    raw_primary = get_env(primary_key, None)
    if raw_primary is not None:
        return int(get_env(primary_key, default, cast=int))
    if fallback_key is not None:
        raw_fallback = get_env(fallback_key, None)
        if raw_fallback is not None:
            return int(get_env(fallback_key, default, cast=int))
    return int(default)


def _dependency_breakers(state: BotState) -> DependencyBreakers:
    breakers = getattr(state, "dependency_breakers", None)
    if isinstance(breakers, DependencyBreakers):
        return breakers
    breakers = DependencyBreakers()
    state.dependency_breakers = breakers
    return cast(DependencyBreakers, breakers)


def _pretrade_rate_limiter(state: BotState) -> SlidingWindowRateLimiter:
    limiter = getattr(state, "pretrade_rate_limiter", None)
    if isinstance(limiter, SlidingWindowRateLimiter):
        return limiter
    limiter_persist_enabled = bool(
        get_env(
            "AI_TRADING_PRETRADE_RATE_LIMITER_PERSIST",
            not is_test_runtime(),
            cast=bool,
        )
    )
    limiter_state_path: Path | None = None
    if limiter_persist_enabled:
        limiter_state_path = resolve_runtime_artifact_path(
            get_env(
                "AI_TRADING_PRETRADE_RATE_LIMITER_PATH",
                "runtime/pretrade_rate_limiter.db",
                cast=str,
            ),
            default_relative="runtime/pretrade_rate_limiter.db",
            for_write=True,
        )
    limiter = SlidingWindowRateLimiter(
        global_orders_per_min=_get_pretrade_limit_env(
            "MAX_ORDERS_PER_MINUTE_GLOBAL",
            fallback_key="AI_TRADING_ORDERS_PER_MIN_GLOBAL",
            default=60,
        ),
        per_symbol_orders_per_min=_get_pretrade_limit_env(
            "MAX_ORDERS_PER_MINUTE_PER_SYMBOL",
            fallback_key="AI_TRADING_ORDERS_PER_MIN_SYMBOL",
            default=6,
        ),
        cancels_per_min=_get_pretrade_limit_env(
            "MAX_CANCELS_PER_MINUTE_GLOBAL",
            fallback_key="AI_TRADING_CANCELS_PER_MIN",
            default=60,
        ),
        cancel_loop_max_without_fill=int(
            get_env("AI_TRADING_CANCEL_LOOP_MAX_WITHOUT_FILL", 5, cast=int)
        ),
        cancel_loop_block_bars=int(get_env("AI_TRADING_CANCEL_LOOP_BLOCK_BARS", 3, cast=int)),
        state_path=limiter_state_path,
    )
    state.pretrade_rate_limiter = limiter
    return cast(SlidingWindowRateLimiter, limiter)


def _handle_error(
    error_info: ErrorInfo,
    *,
    state: BotState,
    ctx: Any,
    symbol: str | None = None,
    sleeve: str | None = None,
) -> None:
    details = dict(error_info.details)
    if symbol:
        details.setdefault("symbol", symbol)
    if sleeve:
        details.setdefault("sleeve", sleeve)
    details.setdefault("dependency", error_info.dependency)
    details.setdefault("reason_code", error_info.reason_code)

    if error_info.action is ErrorAction.SKIP_SYMBOL:
        logger.warning("ERROR_SKIP_SYMBOL", extra=details)
        return

    if error_info.action is ErrorAction.DISABLE_PROVIDER:
        state.degraded_providers.add(error_info.dependency)
        logger.error("ERROR_DISABLE_PROVIDER", extra=details)
        evaluate_runtime_alert_thresholds(
            breaker_open=error_info.dependency,
            state=state,
        )
        return

    if error_info.action is ErrorAction.HALT_TRADING:
        state.halt_trading = True
        state.halt_reason = error_info.reason_code
        logger.error("ALERT_HALT_TRADING", extra=details)
        evaluate_runtime_alert_thresholds(
            halt_reason=error_info.reason_code,
            state=state,
        )
        if error_info.category in {
            ErrorCategory.INVARIANT_VIOLATION,
            ErrorCategory.PROGRAMMING_ERROR,
        }:
            logger.error("ALERT_INVARIANT_OR_PROGRAMMING_HALT", extra=details)
        return

    logger.error("ERROR_ACTION_UNHANDLED", extra=details)


def _kill_switch_active(cfg: TradingConfig) -> tuple[bool, str | None]:
    flag = bool(getattr(cfg, "kill_switch", False))
    if flag:
        return True, "env"
    path = getattr(cfg, "kill_switch_path", None)
    if path:
        try:
            if Path(path).exists():
                return True, "file"
        except BOT_ENGINE_FALLBACK_EXC:
            logger.debug("KILL_SWITCH_PATH_CHECK_FAILED", extra={"path": path}, exc_info=True)
            return True, "file_error"
    return False, None


def _score_drawdown_breaker(runtime: Any, exec_engine: Any) -> dict[str, Any]:
    """Feed the cycle's cached account snapshot to the drawdown breaker.

    Returns the gate payload the symbol loop applies. An open breaker does not
    set ``state.halt_trading``: that latches and stops exits as well.
    """
    breaker = getattr(runtime, "drawdown_circuit_breaker", None)
    if not isinstance(breaker, DrawdownCircuitBreaker):
        logger_once.warning(
            "DRAWDOWN_BREAKER_UNAVAILABLE",
            key="drawdown_breaker_unavailable",
        )
        return {"open": False}
    account_snapshot = None
    get_account_snapshot = getattr(exec_engine, "_get_account_snapshot", None)
    if callable(get_account_snapshot):
        try:
            account_snapshot = get_account_snapshot()
        except BOT_ENGINE_FALLBACK_EXC as exc:
            logger.warning(
                "DRAWDOWN_BREAKER_ACCOUNT_SNAPSHOT_FAILED",
                extra={"cause": exc.__class__.__name__, "detail": str(exc)},
                exc_info=True,
            )
    return breaker.score_account_snapshot(account_snapshot)


def _broker_position_field(position: Any, name: str) -> Any:
    if isinstance(position, Mapping):
        return position.get(name)
    return getattr(position, name, None)


def _position_entry_basis(
    runtime: Any, positions: Mapping[str, Any]
) -> tuple[dict[str, Any], dict[str, str]]:
    """Broker average entry prices that can arm the position stop loss.

    Reads broker position rows the engine already holds (no broker call of
    its own): first the rows behind this cycle's ``positions`` (kept by
    ``compute_current_positions``), so a position that filled after the last
    broker sync arms on the first cycle that holds it; without them, the
    execution engine's broker-sync snapshot. A basis is valid only when the
    rows are fresh, their quantity equals the cycle's position and the price
    is finite and positive. Returns ``(bases, unarmed)``; ``unarmed`` maps
    each held symbol without a valid basis to ``no_basis``, ``qty_mismatch``
    or ``stale_snapshot``.
    """

    from ai_trading.core.netting_position_backstop import (
        POSITION_BACKSTOP_BASIS_MAX_AGE_SECONDS,
        PositionBasis,
    )

    held: dict[str, float] = {}
    for raw_symbol, raw_qty in positions.items():
        qty = _safe_float(raw_qty)
        if qty is not None and math.isfinite(qty) and qty != 0:
            held[str(raw_symbol).strip().upper()] = float(qty)
    if not held:
        return {}, {}

    def _fresh(timestamp: Any) -> bool:
        ts = _safe_float(timestamp)
        if ts is None or not math.isfinite(ts):
            return False
        age_s = float(monotonic_time()) - ts
        return 0.0 <= age_s <= POSITION_BACKSTOP_BASIS_MAX_AGE_SECONDS

    cycle_rows = getattr(runtime, _BROKER_POSITION_ROWS_ATTR, None)
    rows: tuple[Any, ...]
    if isinstance(cycle_rows, tuple) and len(cycle_rows) == 2 and _fresh(cycle_rows[0]):
        rows = tuple(cycle_rows[1] or ())
    else:
        engine = getattr(runtime, "execution_engine", None)
        snapshot = getattr(engine, "_broker_sync", None) if engine is not None else None
        if snapshot is None:
            return {}, {symbol: "no_basis" for symbol in held}
        if not bool(getattr(snapshot, "positions_fresh", False)) or not _fresh(
            getattr(snapshot, "timestamp", None)
        ):
            return {}, {symbol: "stale_snapshot" for symbol in held}
        rows = tuple(getattr(snapshot, "positions", ()) or ())
    broker_rows: dict[str, tuple[float | None, float | None]] = {}
    for position in rows:
        symbol = str(_broker_position_field(position, "symbol") or "").strip().upper()
        if not symbol:
            continue
        qty = _safe_float(_broker_position_field(position, "qty"))
        side_raw = _broker_position_field(position, "side")
        side = str(getattr(side_raw, "value", side_raw) or "").strip().lower()
        if qty is not None and side in {"short", "sell"}:
            qty = -abs(qty)
        broker_rows[symbol] = (qty, _safe_float(_broker_position_field(position, "avg_entry_price")))
    bases: dict[str, Any] = {}
    unarmed: dict[str, str] = {}
    for symbol, qty in held.items():
        row = broker_rows.get(symbol)
        if row is None:
            unarmed[symbol] = "no_basis"
            continue
        broker_qty, avg_entry = row
        if broker_qty is None or not math.isfinite(broker_qty) or abs(broker_qty - qty) > 1e-9:
            unarmed[symbol] = "qty_mismatch"
        elif avg_entry is None or not math.isfinite(avg_entry) or avg_entry <= 0.0:
            unarmed[symbol] = "no_basis"
        else:
            bases[symbol] = PositionBasis(avg_entry_price=float(avg_entry), qty=float(qty))
    return bases, unarmed


def _load_position_backstop(state: BotState) -> Any:
    """Process-lifetime position backstop, loaded once from its runtime artifact."""

    backstop = getattr(state, "_position_backstop", None)
    if backstop is not None:
        return backstop
    from ai_trading.core.netting_position_backstop import (
        POSITION_BACKSTOP_STATE_PATH,
        PositionBackstop,
    )

    backstop = PositionBackstop(
        _resolve_runtime_artifact_path(POSITION_BACKSTOP_STATE_PATH), logger
    )
    setattr(state, "_position_backstop", backstop)
    return backstop


_TRANSIENT_HALT_REASONS: frozenset[str] = frozenset({"DERISK_SLO_BREACH_BLOCK"})


def _clear_transient_halt_state(state: BotState) -> bool:
    """Clear non-latching halt reasons so they are re-evaluated each cycle."""

    if not bool(getattr(state, "halt_trading", False)):
        return False
    reason = str(getattr(state, "halt_reason", "") or "").strip().upper()
    if reason not in _TRANSIENT_HALT_REASONS:
        return False
    state.halt_trading = False
    state.halt_reason = None
    logger.info("TRANSIENT_HALT_CLEARED", extra={"reason": reason})
    return True


def _freshness_seconds_for_timeframe(timeframe: str) -> int:
    mapping = {
        "1Min": 120,
        "5Min": 600,
        "15Min": 1800,
        "1Hour": 7200,
        "1Day": 86400,
    }
    return int(mapping.get(timeframe, 900))


def _score_from_bars(df) -> tuple[float, float]:
    try:
        if df is None or df.empty:
            return 0.0, 0.0
        if "close" not in getattr(df, "columns", ()):
            return 0.0, 0.0

        def _clamped_int_env(name: str, default: int, lower: int, upper: int) -> int:
            try:
                value = int(get_env(name, default, cast=int))
            except BOT_ENGINE_FALLBACK_EXC:
                value = int(default)
            return max(lower, min(value, upper))

        fast_bars = _clamped_int_env("AI_TRADING_SCORE_FAST_BARS", 3, 1, 240)
        slow_bars = _clamped_int_env("AI_TRADING_SCORE_SLOW_BARS", 12, 2, 480)
        vol_bars = _clamped_int_env("AI_TRADING_SCORE_VOL_BARS", 30, 5, 720)

        try:
            fast_weight = float(get_env("AI_TRADING_SCORE_FAST_WEIGHT", 0.65, cast=float))
        except BOT_ENGINE_FALLBACK_EXC:
            fast_weight = 0.65
        if not math.isfinite(fast_weight):
            fast_weight = 0.65
        fast_weight = max(0.0, min(fast_weight, 1.0))

        try:
            z_clip = float(get_env("AI_TRADING_SCORE_Z_CLIP", 3.0, cast=float))
        except BOT_ENGINE_FALLBACK_EXC:
            z_clip = 3.0
        if not math.isfinite(z_clip):
            z_clip = 3.0
        z_clip = max(0.5, min(z_clip, 10.0))

        try:
            min_abs_score = float(get_env("AI_TRADING_SCORE_MIN_ABS", 0.04, cast=float))
        except BOT_ENGINE_FALLBACK_EXC:
            min_abs_score = 0.04
        if not math.isfinite(min_abs_score):
            min_abs_score = 0.04
        min_abs_score = max(0.0, min(min_abs_score, 0.95))

        required_bars = max(fast_bars, slow_bars, vol_bars) + 1
        close_tail = df["close"].tail(required_bars).tolist()
        close_values: list[float] = []
        for raw_value in close_tail:
            try:
                value = float(raw_value)
            except (TypeError, ValueError):
                continue
            if not math.isfinite(value) or value <= 0.0:
                continue
            close_values.append(value)
        if len(close_values) < 3:
            return 0.0, 0.0

        last_px = close_values[-1]
        fast_idx = len(close_values) - 1 - min(fast_bars, len(close_values) - 1)
        slow_idx = len(close_values) - 1 - min(slow_bars, len(close_values) - 1)
        fast_prev = close_values[fast_idx]
        slow_prev = close_values[slow_idx]
        if fast_prev <= 0.0 or slow_prev <= 0.0:
            return 0.0, 0.0

        fast_ret = (last_px / fast_prev) - 1.0
        slow_ret = (last_px / slow_prev) - 1.0
        blended_ret = (fast_weight * fast_ret) + ((1.0 - fast_weight) * slow_ret)

        returns: list[float] = []
        vol_window = min(max(vol_bars, 2), len(close_values) - 1)
        start_idx = len(close_values) - (vol_window + 1)
        for idx in range(max(start_idx, 1), len(close_values)):
            prev_px = close_values[idx - 1]
            cur_px = close_values[idx]
            if prev_px <= 0.0:
                continue
            returns.append((cur_px / prev_px) - 1.0)
        if len(returns) < 2:
            return 0.0, 0.0

        mean_ret = sum(returns) / len(returns)
        variance = sum((ret - mean_ret) ** 2 for ret in returns) / max(len(returns) - 1, 1)
        realized_vol = math.sqrt(max(variance, 0.0))
        if not math.isfinite(realized_vol) or realized_vol <= 0.0:
            return 0.0, 0.0

        z_score = blended_ret / max(realized_vol, 1e-9)
        clipped_z = max(-z_clip, min(z_clip, z_score))
        score = clipped_z / z_clip
        if abs(score) < min_abs_score:
            return 0.0, 0.0

        sample_ratio = min(1.0, float(len(returns)) / float(max(vol_bars, 1)))
        confidence = max(0.0, min(1.0, abs(score) * sample_ratio))
        return score, confidence
    except BOT_ENGINE_FALLBACK_EXC:
        logger.debug("SCORE_FROM_BARS_FAILED", exc_info=True)
        return 0.0, 0.0


def _record_netting_model_liveness(*, proposals_total: int) -> None:
    """Emit model heartbeat signals from the active netting decision path."""

    if int(max(0, proposals_total)) <= 0:
        return
    try:
        rl_enabled = bool(get_env("USE_RL_AGENT", False, cast=bool))
    except BOT_ENGINE_FALLBACK_EXC:
        rl_enabled = False
    if not rl_enabled or RL_AGENT is None:
        return
    try:
        note_rl_signals_emitted()
    except BOT_ENGINE_FALLBACK_EXC:
        logger.debug("NETTING_MODEL_LIVENESS_RL_NOTE_FAILED", exc_info=True)


def _resolve_submit_none_reason(runtime: Any) -> str:
    """Resolve a structured gate reason when submit_order returns ``None``."""

    default_reason = "ORDER_SUBMIT_SKIPPED"
    exec_engine = getattr(runtime, "execution_engine", None) or getattr(runtime, "exec_engine", None)
    outcome = getattr(exec_engine, "_last_submit_outcome", None)
    if not isinstance(outcome, Mapping):
        return default_reason

    reason_raw = outcome.get("reason")
    if reason_raw not in (None, ""):
        try:
            token = str(reason_raw).strip().upper()
        except BOT_ENGINE_FALLBACK_EXC:
            token = ""
        if token:
            return token

    status_raw = outcome.get("status")
    try:
        status = str(status_raw or "").strip().lower()
    except BOT_ENGINE_FALLBACK_EXC:
        status = ""
    if status == "failed":
        return "ORDER_SUBMIT_FAILED"
    return default_reason


def _normalize_submit_side(side: Any) -> str | None:
    """Normalize mixed side labels into buy/sell buckets."""

    text = str(side or "").strip().lower()
    if text in {"buy", "buy_to_cover", "cover"}:
        return "buy"
    if text in {"sell", "exit", "sell_short", "short"}:
        return "sell"
    return None


def _reserve_cycle_submit_intent(state_obj: Any, *, symbol: str, side: Any) -> bool:
    """Reserve symbol/side intent for the active cycle; False for duplicates."""

    symbol_key = str(symbol or "").strip().upper()
    side_key = _normalize_submit_side(side)
    if not symbol_key or side_key is None:
        return True
    intents = getattr(state_obj, "cycle_submit_compaction", None)
    if not isinstance(intents, set):
        intents = set()
        setattr(state_obj, "cycle_submit_compaction", intents)
    key = (symbol_key, side_key)
    if key in intents:
        return False
    intents.add(key)
    return True


def _auth_forbidden_cooldown_seconds() -> float:
    try:
        cooldown = float(
            get_env(
                "AI_TRADING_AUTH_FORBIDDEN_COOLDOWN_SECONDS",
                180.0,
                cast=float,
            )
        )
    except (TypeError, ValueError):
        cooldown = 180.0
    return max(cooldown, 0.0)


def _is_auth_forbidden_reason(reason: Any) -> bool:
    token = str(reason or "").strip().upper()
    return token.startswith("AUTH_BROKER_HALT_FORBIDDEN")


def _record_auth_forbidden_cooldown(
    state_obj: Any,
    *,
    symbol: str,
    side: Any,
    reason: Any,
    now: datetime,
) -> None:
    """Start a per-symbol side cooldown when broker returns forbidden auth halt."""

    if not _is_auth_forbidden_reason(reason):
        return
    cooldown = _auth_forbidden_cooldown_seconds()
    if cooldown <= 0.0:
        return
    symbol_key = str(symbol or "").strip().upper()
    side_key = _normalize_submit_side(side)
    if not symbol_key or side_key is None:
        return
    cooldowns = getattr(state_obj, "auth_forbidden_cooldowns", None)
    if not isinstance(cooldowns, dict):
        cooldowns = {}
        setattr(state_obj, "auth_forbidden_cooldowns", cooldowns)
    cooldowns[(symbol_key, side_key)] = now + timedelta(seconds=cooldown)


def _auth_forbidden_cooldown_remaining_seconds(
    state_obj: Any,
    *,
    symbol: str,
    side: Any,
    now: datetime,
) -> float:
    """Return remaining cooldown for symbol/side after forbidden auth halts."""

    symbol_key = str(symbol or "").strip().upper()
    side_key = _normalize_submit_side(side)
    if not symbol_key or side_key is None:
        return 0.0
    cooldowns = getattr(state_obj, "auth_forbidden_cooldowns", None)
    if not isinstance(cooldowns, dict) or not cooldowns:
        return 0.0
    expiry = cooldowns.get((symbol_key, side_key))
    if not isinstance(expiry, datetime):
        return 0.0
    if expiry <= now:
        cooldowns.pop((symbol_key, side_key), None)
        return 0.0
    return max((expiry - now).total_seconds(), 0.0)


def _redact_snapshot_payload(payload: Any) -> Any:
    if isinstance(payload, dict):
        redacted: dict[str, Any] = {}
        for key, value in payload.items():
            key_text = str(key).lower()
            if any(token in key_text for token in ("secret", "token", "api_key", "password")):
                redacted[str(key)] = "***"
            else:
                redacted[str(key)] = _redact_snapshot_payload(value)
        return redacted
    if isinstance(payload, list):
        return [_redact_snapshot_payload(item) for item in payload]
    return payload


def _resolve_runtime_artifact_path(path_value: str) -> Path:
    return resolve_runtime_artifact_path(path_value, default_relative=str(path_value))


def _resolved_tca_path() -> Path:
    return _resolve_runtime_artifact_path(
        str(get_env("AI_TRADING_TCA_PATH", "runtime/tca_records.jsonl"))
    )


def _json_dump_default(value: Any) -> Any:
    if isinstance(value, (bytes, bytearray)):
        return bytes(value).decode("utf-8", errors="replace")

    isoformat = getattr(value, "isoformat", None)
    if callable(isoformat):
        try:
            return isoformat()
        except BOT_ENGINE_FALLBACK_EXC:
            pass

    scalar = getattr(value, "item", None)
    if callable(scalar):
        try:
            candidate = scalar()
        except BOT_ENGINE_FALLBACK_EXC:
            candidate = None
        if isinstance(candidate, (str, int, float, bool)) or candidate is None:
            return candidate

    return str(value)


_DECISION_RECORD_SCHEMA_VERSION = "2.0.0"


def _write_decision_record(record: Any, path: str | None) -> None:
    try:
        payload = record.to_dict() if hasattr(record, "to_dict") else dict(record)
    except BOT_ENGINE_FALLBACK_EXC:
        payload = {"record": repr(record)}
    if isinstance(payload, dict):
        schema_version = str(payload.get("schema_version") or "").strip()
        payload["schema_version"] = schema_version or _DECISION_RECORD_SCHEMA_VERSION
    if bool(get_env("AI_TRADING_DECISION_RECORD_SNAPSHOT_REDACT_SECRETS", True, cast=bool)):
        payload = _redact_snapshot_payload(payload)
    logger.info("DECISION_RECORD", extra={"decision": payload})
    if bool(get_env("AI_TRADING_DECISION_EVENT_EMIT_ENABLED", True, cast=bool)):
        try:
            from ai_trading.oms.decision_events import emit_decision_event_from_payload

            emit_decision_event_from_payload(
                payload if isinstance(payload, Mapping) else {"record": payload},
                event_source="decision_record",
            )
        except BOT_ENGINE_FALLBACK_EXC as exc:
            logger.warning(
                "DECISION_EVENT_EMIT_FAILED",
                extra={"error": str(exc)},
            )
    if not path:
        path_targets: list[str] = []
    else:
        path_targets = [path]
    snapshot_path = str(get_env("AI_TRADING_CONFIG_SNAPSHOT_PATH", "") or "").strip()
    if snapshot_path:
        path_targets.append(snapshot_path)
    for target_path in path_targets:
        resolved_path = str(target_path)
        try:
            dest = _resolve_runtime_artifact_path(str(target_path))
            resolved_path = str(dest)
            dest.parent.mkdir(parents=True, exist_ok=True)
            with dest.open("a", encoding="utf-8") as fh:
                fh.write(json.dumps(payload, sort_keys=True, default=_json_dump_default))
                fh.write("\n")
        except BOT_ENGINE_FALLBACK_EXC as exc:
            logger.warning(
                "DECISION_RECORD_WRITE_FAILED path=%s error=%s",
                resolved_path,
                str(exc),
                extra={"error": str(exc), "path": resolved_path},
            )


def _gate_effectiveness_analytics_enabled() -> bool:
    return bool(get_env("AI_TRADING_GATE_EFFECTIVENESS_ANALYTICS_ENABLED", True, cast=bool))


def _gate_effectiveness_log_path() -> Path:
    return resolve_runtime_artifact_path(
        str(
            get_env(
                "AI_TRADING_GATE_EFFECTIVENESS_LOG_PATH",
                "runtime/gate_effectiveness.jsonl",
                cast=str,
            )
            or ""
        ),
        default_relative="runtime/gate_effectiveness.jsonl",
    )


def _gate_effectiveness_summary_path() -> Path:
    return resolve_runtime_artifact_path(
        str(
            get_env(
                "AI_TRADING_GATE_EFFECTIVENESS_SUMMARY_PATH",
                "runtime/gate_effectiveness_summary.json",
                cast=str,
            )
            or ""
        ),
        default_relative="runtime/gate_effectiveness_summary.json",
    )


def _gate_effectiveness_include_attribution() -> bool:
    return bool(get_env("AI_TRADING_GATE_EFFECTIVENESS_INCLUDE_ATTRIBUTION", True, cast=bool))


def _gate_effectiveness_exclude_global_halts() -> bool:
    return bool(get_env("AI_TRADING_GATE_EFFECTIVENESS_EXCLUDE_GLOBAL_HALTS", True, cast=bool))


def _gate_effectiveness_exclude_warmup_records() -> bool:
    return bool(get_env("AI_TRADING_GATE_EFFECTIVENESS_EXCLUDE_WARMUP_RECORDS", True, cast=bool))


def _gate_name_is_warmup_noise(gate_name: str) -> bool:
    gate = str(gate_name or "").strip().upper()
    return gate in {"WARMUP_DATA_ONLY", "WARMUP_DATA_ONLY_RETRY_BYPASS"}


def _gate_name_is_halt_noise(gate_name: str) -> bool:
    gate = str(gate_name or "").strip().upper()
    if not gate:
        return False
    if gate in {"AUTH_HALT", "HALT_TRADING", "IDLE_MARKET_CLOSED", "MARKET_CLOSED_BLOCK"}:
        return True
    return "HALT" in gate


_GATE_ROOT_EXACT: dict[str, str] = {
    "ENTRY_CONSTRAINED_MIN_NOTIONAL_PRECHECK": "ENTRY_CONSTRAINED",
    "ENTRY_CONSTRAINED_SYMBOL_REENTRY_COOLDOWN_PRECHECK": "ENTRY_CONSTRAINED",
    "PRE_EXECUTION_ORDER_CHECKS_FAILED": "PRE_EXECUTION_CHECKS",
    "PRE_EXECUTION_CHECKS_FAILED": "PRE_EXECUTION_CHECKS",
    "PRE_SUBMIT_INSUFFICIENT_POSITION_AVAILABLE": "PRE_SUBMIT_POSITION",
    "PRE_SUBMIT_SELL_QTY_CLIP_AVAILABLE_POSITION": "PRE_SUBMIT_POSITION",
    "LIQ_THIN_MAX_ORDER_BLOCK": "LIQUIDITY_THIN_MAX_ORDER",
    "LIQ_THIN_MAX_ORDER_BLOCK_BYPASSED": "LIQUIDITY_THIN_MAX_ORDER",
    "LIQ_PARTICIPATION_BLOCK": "LIQUIDITY_PARTICIPATION",
    "LIQ_PARTICIPATION_BLOCK_BYPASSED": "LIQUIDITY_PARTICIPATION",
    "COST_AWARE_ENTRY_GUARD": "COST_AWARE_ENTRY",
    # Position backstop: one root each so de-duplication keeps them apart.
    "POSITION_STOP_LOSS_EXIT": "POSITION_STOP_LOSS",
    "POSITION_MAX_HOLD_EXIT": "POSITION_MAX_HOLD",
    "POSITION_BACKSTOP_REENTRY_BLOCK": "POSITION_BACKSTOP_REENTRY",
    "POSITION_CAP_BLOCK": "POSITION_CAP",
    "PROTECTIVE_EXIT_OVERRIDE": "PROTECTIVE_EXIT_OVERRIDE",
}
_GATE_ROOT_PREFIX: tuple[tuple[str, str], ...] = (
    ("ENTRY_CONSTRAINED_", "ENTRY_CONSTRAINED"),
    ("PRE_SUBMIT_", "PRE_SUBMIT"),
    ("LIQ_", "LIQUIDITY"),
    ("ALPHA_TIME_STOP_", "ALPHA_TIME_STOP"),
    ("ALPHA_DECAY_", "ALPHA_DECAY"),
    ("DERISK_", "DERISK"),
    ("PORTFOLIO_OPTIMIZER_", "PORTFOLIO_OPTIMIZER"),
    ("BANDIT_", "RANKER_BANDIT"),
    ("COUNTERFACTUAL_", "RANKER_COUNTERFACTUAL"),
    ("GEOMETRIC_", "RANKER_GEOMETRIC"),
    ("PORTFOLIO_LOG_GROWTH", "RANKER_PORTFOLIO_LOG_GROWTH"),
)


def _gate_root_cause(gate_name: str) -> str:
    gate = str(gate_name or "").strip().upper()
    if not gate:
        return ""
    exact = _GATE_ROOT_EXACT.get(gate)
    if exact:
        return exact
    for prefix, root in _GATE_ROOT_PREFIX:
        if gate.startswith(prefix):
            return root
    return gate


def _dedupe_gate_root_causes(gates: Sequence[str]) -> list[str]:
    deduped: list[str] = []
    seen_roots: set[str] = set()
    for raw_gate in gates:
        gate = str(raw_gate or "").strip()
        if not gate:
            continue
        root = _gate_root_cause(gate)
        if root in seen_roots:
            continue
        seen_roots.add(root)
        deduped.append(gate)
    return deduped


def _analytics_counter_map(raw: Any) -> dict[str, int]:
    out: dict[str, int] = {}
    if not isinstance(raw, Mapping):
        return out
    for key, value in raw.items():
        try:
            count = int(value)
        except (TypeError, ValueError):
            continue
        if count > 0:
            out[str(key)] = count
    return out


def _analytics_stats_map(raw: Any) -> dict[str, dict[str, float]]:
    out: dict[str, dict[str, float]] = {}
    if not isinstance(raw, Mapping):
        return out
    def _as_float(value: Any) -> float:
        try:
            return float(value or 0.0)
        except (TypeError, ValueError):
            return 0.0
    for key, value in raw.items():
        if not isinstance(value, Mapping):
            continue
        item = {
            "count": _as_float(value.get("count", 0.0)),
            "accepted_records": _as_float(value.get("accepted_records", 0.0)),
            "blocked_records": _as_float(value.get("blocked_records", 0.0)),
            "expected_net_edge_bps_sum": _as_float(value.get("expected_net_edge_bps_sum", 0.0)),
            "edge_proxy_bps_sum": _as_float(value.get("edge_proxy_bps_sum", 0.0)),
        }
        out[str(key)] = item
    return out


def _bump_analytics_stats(
    bucket: dict[str, dict[str, float]],
    key: str,
    *,
    accepted: bool,
    expected_net_edge_bps: float,
    edge_proxy_bps: float,
) -> None:
    item = bucket.setdefault(
        str(key),
        {
            "count": 0.0,
            "accepted_records": 0.0,
            "blocked_records": 0.0,
            "expected_net_edge_bps_sum": 0.0,
            "edge_proxy_bps_sum": 0.0,
        },
    )
    item["count"] += 1.0
    if accepted:
        item["accepted_records"] += 1.0
    else:
        item["blocked_records"] += 1.0
    item["expected_net_edge_bps_sum"] += float(expected_net_edge_bps)
    item["edge_proxy_bps_sum"] += float(edge_proxy_bps)


def _merge_analytics_stats(
    target: dict[str, dict[str, float]],
    source: Mapping[str, Any],
) -> None:
    for key, raw_metrics in source.items():
        if not isinstance(raw_metrics, Mapping):
            continue
        item = target.setdefault(
            str(key),
            {
                "count": 0.0,
                "accepted_records": 0.0,
                "blocked_records": 0.0,
                "expected_net_edge_bps_sum": 0.0,
                "edge_proxy_bps_sum": 0.0,
            },
        )
        item["count"] += float(raw_metrics.get("count", 0.0) or 0.0)
        item["accepted_records"] += float(raw_metrics.get("accepted_records", 0.0) or 0.0)
        item["blocked_records"] += float(raw_metrics.get("blocked_records", 0.0) or 0.0)
        item["expected_net_edge_bps_sum"] += float(
            raw_metrics.get("expected_net_edge_bps_sum", 0.0) or 0.0
        )
        item["edge_proxy_bps_sum"] += float(raw_metrics.get("edge_proxy_bps_sum", 0.0) or 0.0)


def _update_gate_effectiveness_analytics(
    *,
    decision_gate_counts: Mapping[str, int],
    decision_records_total: int,
    accepted_decisions: int,
    decision_observations: Sequence[Mapping[str, Any]] | None = None,
) -> None:
    if not _gate_effectiveness_analytics_enabled():
        return
    log_path = _gate_effectiveness_log_path()
    summary_path = _gate_effectiveness_summary_path()
    include_attribution = _gate_effectiveness_include_attribution()
    exclude_global_halts = _gate_effectiveness_exclude_global_halts()
    exclude_warmup_records = _gate_effectiveness_exclude_warmup_records()
    records_total = int(max(0, decision_records_total))
    accepted_records = int(max(0, accepted_decisions))
    rejected_records = int(max(0, records_total - accepted_records))
    gate_counts: dict[str, int] = {
        str(gate): int(count)
        for gate, count in decision_gate_counts.items()
        if str(gate).strip() and int(count) > 0
    }
    excluded_records = 0
    excluded_gate_counts: Counter[str] = Counter()
    gate_root_counts: Counter[str] = Counter()
    gate_attribution_cycle: dict[str, dict[str, float]] = {}
    gate_root_attribution_cycle: dict[str, dict[str, float]] = {}
    symbol_attribution_cycle: dict[str, dict[str, float]] = {}
    regime_attribution_cycle: dict[str, dict[str, float]] = {}
    total_expected_net_edge_bps = 0.0
    total_edge_proxy_bps = 0.0
    if decision_observations:
        records_total = 0
        accepted_records = 0
        rejected_records = 0
        gate_counts = {}
        gate_root_counts = Counter()
        for raw_item in decision_observations:
            if not isinstance(raw_item, Mapping):
                continue
            gates_raw = raw_item.get("gates")
            if isinstance(gates_raw, (str, bytes, bytearray)):
                gates_iterable: list[Any] = [gates_raw]
            elif isinstance(gates_raw, Sequence):
                gates_iterable = list(gates_raw)
            else:
                gates_iterable = []
            gates = [
                str(gate).strip()
                for gate in gates_iterable
                if str(gate).strip()
            ]
            if not gates:
                continue
            symbol = str(raw_item.get("symbol", "") or "").strip().upper() or "UNKNOWN"
            regime = str(raw_item.get("regime", "") or "").strip().upper() or "UNKNOWN"
            accepted = bool(raw_item.get("accepted", "OK_TRADE" in gates))
            try:
                expected_net_edge_bps = float(raw_item.get("expected_net_edge_bps", 0.0) or 0.0)
            except (TypeError, ValueError):
                expected_net_edge_bps = 0.0
            try:
                edge_proxy_bps = float(raw_item.get("edge_proxy_bps", expected_net_edge_bps) or 0.0)
            except (TypeError, ValueError):
                edge_proxy_bps = float(expected_net_edge_bps)
            is_global_halt_noise = bool(
                exclude_global_halts
                and symbol == "ALL"
                and any(_gate_name_is_halt_noise(gate) for gate in gates)
            )
            is_warmup_noise = bool(
                exclude_warmup_records and any(_gate_name_is_warmup_noise(gate) for gate in gates)
            )
            if is_global_halt_noise or is_warmup_noise:
                excluded_records += 1
                for gate in gates:
                    excluded_gate_counts[str(gate)] += 1
                continue
            records_total += 1
            if accepted:
                accepted_records += 1
            else:
                rejected_records += 1
            total_expected_net_edge_bps += float(expected_net_edge_bps)
            total_edge_proxy_bps += float(edge_proxy_bps)
            if include_attribution:
                _bump_analytics_stats(
                    symbol_attribution_cycle,
                    symbol,
                    accepted=accepted,
                    expected_net_edge_bps=expected_net_edge_bps,
                    edge_proxy_bps=edge_proxy_bps,
                )
                _bump_analytics_stats(
                    regime_attribution_cycle,
                    regime,
                    accepted=accepted,
                    expected_net_edge_bps=expected_net_edge_bps,
                    edge_proxy_bps=edge_proxy_bps,
                )
            for gate in gates:
                gate_key = str(gate)
                gate_counts[gate_key] = int(gate_counts.get(gate_key, 0)) + 1
                if include_attribution:
                    _bump_analytics_stats(
                        gate_attribution_cycle,
                        gate_key,
                        accepted=accepted,
                        expected_net_edge_bps=expected_net_edge_bps,
                        edge_proxy_bps=edge_proxy_bps,
                    )
            gate_roots = {
                _gate_root_cause(str(gate))
                for gate in gates
                if str(gate).strip()
            }
            for gate_root in sorted(gate_roots):
                gate_root_counts[str(gate_root)] += 1
                if include_attribution:
                    _bump_analytics_stats(
                        gate_root_attribution_cycle,
                        str(gate_root),
                        accepted=accepted,
                        expected_net_edge_bps=expected_net_edge_bps,
                        edge_proxy_bps=edge_proxy_bps,
                    )
    elif gate_counts:
        for gate, count in gate_counts.items():
            gate_root_counts[_gate_root_cause(str(gate))] += int(count)
    cycle_payload: dict[str, Any] = {
        "ts": datetime.now(UTC).isoformat(),
        "records_total": int(max(0, records_total)),
        "accepted_records": int(max(0, accepted_records)),
        "rejected_records": int(max(0, rejected_records)),
        "excluded_records": int(max(0, excluded_records)),
        "excluded_gate_counts": {
            str(gate): int(count)
            for gate, count in sorted(excluded_gate_counts.items(), key=lambda item: (-item[1], item[0]))
            if int(count) > 0
        },
        "gate_counts": {
            str(gate): int(count)
            for gate, count in gate_counts.items()
            if str(gate).strip() and int(count) > 0
        },
        "gate_root_counts": {
            str(gate): int(count)
            for gate, count in sorted(gate_root_counts.items(), key=lambda item: (-item[1], item[0]))
            if str(gate).strip() and int(count) > 0
        },
        "total_expected_net_edge_bps": float(total_expected_net_edge_bps),
        "total_edge_proxy_bps": float(total_edge_proxy_bps),
        "gate_attribution": gate_attribution_cycle if include_attribution else {},
        "gate_root_attribution": gate_root_attribution_cycle if include_attribution else {},
        "symbol_attribution": symbol_attribution_cycle if include_attribution else {},
        "regime_attribution": regime_attribution_cycle if include_attribution else {},
    }
    try:
        log_path.parent.mkdir(parents=True, exist_ok=True)
        with log_path.open("a", encoding="utf-8") as handle:
            handle.write(json.dumps(cycle_payload, sort_keys=True, default=_json_dump_default))
            handle.write("\n")
    except BOT_ENGINE_FALLBACK_EXC as exc:
        logger.warning(
            "GATE_EFFECTIVENESS_LOG_WRITE_FAILED",
            extra={"path": str(log_path), "error": str(exc)},
        )

    summary: dict[str, Any] = {
        "total_records": 0,
        "total_accepted_records": 0,
        "total_rejected_records": 0,
        "excluded_records_total": 0,
        "gate_totals": {},
        "gate_root_totals": {},
        "excluded_gate_totals": {},
        "total_expected_net_edge_bps": 0.0,
        "total_edge_proxy_bps": 0.0,
        "gate_attribution": {},
        "gate_root_attribution": {},
        "symbol_attribution": {},
        "regime_attribution": {},
    }
    try:
        if summary_path.exists():
            loaded = json.loads(summary_path.read_text(encoding="utf-8"))
            if isinstance(loaded, dict):
                summary.update(loaded)
    except BOT_ENGINE_FALLBACK_EXC:
        logger.debug("GATE_EFFECTIVENESS_SUMMARY_READ_FAILED", exc_info=True)
    gate_totals = _analytics_counter_map(summary.get("gate_totals"))
    gate_root_totals = _analytics_counter_map(summary.get("gate_root_totals"))
    excluded_gate_totals = _analytics_counter_map(summary.get("excluded_gate_totals"))
    gate_attribution = _analytics_stats_map(summary.get("gate_attribution"))
    gate_root_attribution = _analytics_stats_map(summary.get("gate_root_attribution"))
    symbol_attribution = _analytics_stats_map(summary.get("symbol_attribution"))
    regime_attribution = _analytics_stats_map(summary.get("regime_attribution"))
    summary["total_records"] = int(summary.get("total_records", 0) or 0) + int(
        cycle_payload["records_total"]
    )
    summary["total_accepted_records"] = int(
        summary.get("total_accepted_records", 0) or 0
    ) + int(cycle_payload["accepted_records"])
    summary["total_rejected_records"] = int(
        summary.get("total_rejected_records", 0) or 0
    ) + int(cycle_payload["rejected_records"])
    summary["excluded_records_total"] = int(summary.get("excluded_records_total", 0) or 0) + int(
        cycle_payload["excluded_records"]
    )
    summary["total_expected_net_edge_bps"] = float(
        summary.get("total_expected_net_edge_bps", 0.0) or 0.0
    ) + float(cycle_payload["total_expected_net_edge_bps"])
    summary["total_edge_proxy_bps"] = float(summary.get("total_edge_proxy_bps", 0.0) or 0.0) + float(
        cycle_payload["total_edge_proxy_bps"]
    )
    for gate, count in cycle_payload["gate_counts"].items():
        gate_totals[str(gate)] = int(gate_totals.get(str(gate), 0)) + int(count)
    for gate_root, count in cycle_payload["gate_root_counts"].items():
        gate_root_totals[str(gate_root)] = int(
            gate_root_totals.get(str(gate_root), 0)
        ) + int(count)
    for gate, count in cycle_payload["excluded_gate_counts"].items():
        excluded_gate_totals[str(gate)] = int(excluded_gate_totals.get(str(gate), 0)) + int(count)
    if include_attribution:
        _merge_analytics_stats(gate_attribution, cycle_payload["gate_attribution"])
        _merge_analytics_stats(gate_root_attribution, cycle_payload["gate_root_attribution"])
        _merge_analytics_stats(symbol_attribution, cycle_payload["symbol_attribution"])
        _merge_analytics_stats(regime_attribution, cycle_payload["regime_attribution"])
    summary["gate_totals"] = gate_totals
    summary["gate_root_totals"] = gate_root_totals
    summary["excluded_gate_totals"] = excluded_gate_totals
    total_records = max(1, int(summary["total_records"]))
    gate_effectiveness = {
        gate: {
            "count": int(count),
            "per_record_rate": float(count) / float(total_records),
        }
        for gate, count in sorted(gate_totals.items(), key=lambda item: (-item[1], item[0]))
    }
    summary["gate_effectiveness"] = gate_effectiveness
    summary["gate_root_effectiveness"] = {
        gate: {
            "count": int(count),
            "per_record_rate": float(count) / float(total_records),
        }
        for gate, count in sorted(
            gate_root_totals.items(),
            key=lambda item: (-item[1], item[0]),
        )
    }
    summary["gate_attribution"] = gate_attribution
    summary["gate_root_attribution"] = gate_root_attribution
    summary["symbol_attribution"] = symbol_attribution
    summary["regime_attribution"] = regime_attribution
    summary["updated_at"] = cycle_payload["ts"]
    try:
        summary_path.parent.mkdir(parents=True, exist_ok=True)
        summary_path.write_text(
            json.dumps(summary, sort_keys=True, default=_json_dump_default) + "\n",
            encoding="utf-8",
        )
    except BOT_ENGINE_FALLBACK_EXC as exc:
        logger.warning(
            "GATE_EFFECTIVENESS_SUMMARY_WRITE_FAILED",
            extra={"path": str(summary_path), "error": str(exc)},
        )


def _counterfactual_learning_enabled() -> bool:
    short_toggle = get_env("COUNTERFACTUAL", None, cast=bool)
    if short_toggle is not None:
        return bool(short_toggle)
    exec_toggle = get_env("AI_TRADING_EXEC_COUNTERFACTUAL_LEARNING_ENABLED", None, cast=bool)
    if exec_toggle is not None:
        return bool(exec_toggle)
    return bool(
        get_env("AI_TRADING_COUNTERFACTUAL_LEARNING_ENABLED", False, cast=bool)
    )


def _ensure_counterfactual_learning_artifacts(
    *,
    now: datetime | None = None,
) -> dict[str, Any]:
    """Best-effort bootstrap for counterfactual artifacts to avoid silent no-op state."""

    ts = (now or datetime.now(UTC)).isoformat()
    state_path = _counterfactual_learning_state_path()
    events_path = _counterfactual_learning_events_path()
    context: dict[str, Any] = {
        "state_path": str(state_path),
        "events_path": str(events_path),
        "state_ready": bool(state_path.exists()),
        "events_ready": bool(events_path.exists()),
        "state_created": False,
        "events_created": False,
    }

    default_state = {
        "updated_at": None,
        "global": {
            "events": 0,
            "accepted": 0,
            "rejected": 0,
            "accept_rate": 0.0,
            "ips_mean_bps": 0.0,
            "dr_mean_bps": 0.0,
            "missed_dr_mean_bps": 0.0,
            "missed_dr_sum_bps": 0.0,
            "cycle_records": 0,
            "cycle_rejected": 0,
            "cycle_missed_dr_bps": 0.0,
            "cycle_accepted": 0,
            "cycle_accepted_reward_mean_bps": 0.0,
        },
        "buckets": {},
    }

    if not state_path.exists():
        try:
            state_path.parent.mkdir(parents=True, exist_ok=True)
            state_path.write_text(
                json.dumps(default_state, sort_keys=True, default=_json_dump_default)
                + "\n",
                encoding="utf-8",
            )
            context["state_created"] = True
            context["state_ready"] = True
            logger.info(
                "COUNTERFACTUAL_STATE_BOOTSTRAPPED",
                extra={"path": str(state_path), "ts": ts},
            )
        except BOT_ENGINE_FALLBACK_EXC as exc:
            context["state_error"] = str(exc)
            logger.warning(
                "COUNTERFACTUAL_STATE_BOOTSTRAP_FAILED",
                extra={"path": str(state_path), "error": str(exc)},
            )

    if not events_path.exists():
        try:
            events_path.parent.mkdir(parents=True, exist_ok=True)
            events_path.touch(exist_ok=True)
            context["events_created"] = True
            context["events_ready"] = True
            logger.info(
                "COUNTERFACTUAL_EVENTS_BOOTSTRAPPED",
                extra={"path": str(events_path), "ts": ts},
            )
        except BOT_ENGINE_FALLBACK_EXC as exc:
            context["events_error"] = str(exc)
            logger.warning(
                "COUNTERFACTUAL_EVENTS_BOOTSTRAP_FAILED",
                extra={"path": str(events_path), "error": str(exc)},
            )

    return context


